import{b as s,E as a,S as n,P as t,d as r}from"./vendor-CNKpRggL.js";const i={id:"scenario1",titre:"Le Serment des Sept Thanes",niveau:"Niveaux 1-4 · 6-8 séances · Acte I de la trilogie",vue_ensemble:{ton:"Enquête qui s'assombrit. On commence dans l'atmosphère confiante d'un mandataire de l'Université, puis on bascule vers le mystère, la suspicion et l'horreur douce d'une cité qui ne sait pas ce qu'elle garde.",themes:["La mémoire perdue — une cité qui a oublié pourquoi elle enterre ses fondateurs.","La manipulation bienveillante — un homme brillant qui ne ment jamais mais qui ne dit jamais toute la vérité.","Le verrou caché — les tombes ne sont pas des monuments, ce sont des ancrages actifs.","Le choix impossible — servir un homme bon ou combattre un homme que personne ne veut arrêter."],question_dramatique:"Les PJ peuvent-ils découvrir que Thade Coren, l'homme qui les a engagés, est celui qui profane les tombes — et que les tombes sont le verrou de la Spirale ?",ce_que_les_pj_savent:["Des profanations ont lieu au Cimetière des Terrasses.","Thade Coren, Archimage respecté, les a engagés pour enquêter.","Les clans nains ne parlent pas à l'Université.","Le Conseil traite cela comme du vandalisme."],ce_que_les_pj_doivent_decouvrir:["Les Sept Thanes ne sont pas des fondateurs honorés : ce sont les ancrages du sceau qui maintient la Spirale close.","Les profanations utilisent des outils de l'Université — quelqu'un à l'intérieur est impliqué.","Le protocole S-01 relie Thade à la catastrophe de Nyx et à Sealine.","Thade lui-même orchestre les prélèvements d'ossements pour ouvrir le seuil.","La Résistance de la Vieille Ville est une alternative à l'Université."],structure:[{acte:"Acte I — L'Engagement",resume:"Les PJ acceptent la mission de Thade, descendent aux Terrasses, rencontrent Thorgar et Jaren. La mort de Jaren bascule la campagne.",scenes:3,severite:"Confiance → Suspicion"},{acte:"Acte II — La Découverte du Verrou",resume:"Les PJ comprennent que les tombes sont un système d'ancrage. Thorgar révèle les rites d'Edhrek-Murn. Les archives dévoilent S-01. Olane devient une alliée.",scenes:3,severite:"Suspicion → Révélation"},{acte:"Acte III — Le Tournant",resume:"Le sceau cède visiblement. La Résistance s'offre comme alternative. Les PJ doivent choisir leur camp : Thade, la Résistance, ou une troisième voie.",scenes:3,severite:"Révélation → Choix"}],pnj_cles:[{id:"thade_coren",nom:"Thade Coren",role:"Mandataire des PJ. Antagoniste caché. Poli, précis, jamais cruel — l'atrocité est dans l'efficacité."},{id:"thorgar_pretre_nain",nom:"Thorgar",role:"Prêtre nain du Temple-Forgeron. Gardien des rites qu'il accomplit sans comprendre. Allié potentiel."},{id:"jaren_velt",nom:"Jaren Velt",role:"Étudiant de l'Université. Agent de Thade. Sa mort marque le tournant du scénario."},{id:"maera_olane",nom:"Maëra Olane",role:"Rectrice et conseillère. Alliée institutionnelle isolée. Fournit accès, données et couverture légale."},{id:"mara_dirigeante",nom:"Mara",role:"Dirigeante de la Résistance. Cherche la vérité sur Nyx depuis huit ans."},{id:"sealine_coren",nom:"Sealine Vael",role:"Épouse de Thade, présumée morte à Nyx. Inscrite sous le nom marital « Coren, S. — 12-VAEL » dans les dossiers médicaux. Le récit la nomme Sealine Vael. Les cahiers de Thade la nomment Sealine. Elle est le motif de tout."}],lieux_cles:[{id:"bureau_thade_universite",nom:"Bureau de Thade Coren",role:"Point de départ. Lavande, papier ancien, coffret plombé."},{id:"cimetiere_thanes",nom:"Cimetière des Terrasses",role:"Centre de l'enquête. Tombes en gradins, Mausolée du Seuil, Puits de l'Abîme."},{id:"temple_forgeron",nom:"Temple-Forgeron de Moradin",role:"Chapelle souterraine. Lieu des révélations sur les rites d'Edhrek-Murn."},{id:"archives_scellees_universite",nom:"Archives Médicales Scellées",role:"Sous-sol de l'Université. Dossier S-01 et lien avec Sealine."},{id:"maison_des_retours",nom:"Maison des Retours",role:"QG de la Résistance dans la Vieille Ville. Alternative à l'Université."}]},revelations_indispensables:[{id:"rev_verrou_thanes",titre:"Les tombes des Sept Thanes sont le verrou de la Spirale",resume:"Les Sept Thanes ne sont pas des fondateurs honorés. Leurs tombes sont les points visibles d'un système d'ancrage qui maintient le sceau fermant la Spirale. Les os portent des runes d'ancrage. Les rites d'Edhrek-Murn les maintiennent.",sources:["Temple-Forgeron : Thorgar montre les gestes et identifie les runes (Acte II, scène 1).","Cimetière des Terrasses : les runes dans les os sont visibles dès la première descente (Acte I, scène 2)."],declencheur:"Diplomatie DD 14 avec Thorgar OU Connaissances (religion) DD 15 sur les runes.",plan_b:"Si les PJ ratent Thorgar, Olane peut orienter vers les archives. Le Mausolée du Seuil et son froid anormal sont perceptibles sans jet. Thorgar finit par dire que les rites existent et que les profanations les brisent.",consequence_si_ratee:"Les PJ ne comprennent pas l'enjeu réel. Ils traitent les profanations comme du vandalisme et rapportent à Thade sans soupçon. Le Scénario 2 démarre avec un retard critique."},{id:"rev_outils_universite",titre:"Les profanations utilisent des outils de l'Université",resume:"Les passages sous les dalles ont été creusés avec des ciselets d'Université, pas des outils de vandale. Quelqu'un à l'intérieur de l'institution est impliqué.",sources:["Cimetière des Terrasses : Investigation DD 14 sur les passages (Acte I, scène 2)."],declencheur:"Investigation DD 14.",plan_b:"Même en cas d'échec, Thorgar dit que trois tombes ont été touchées et que les passages viennent par en-dessous. Le MJ peut faire remarquer la précision des coupes sans révéler l'origine exacte.",consequence_si_ratee:"Les PJ ne relient pas les profanations à l'Université. La piste de Thade reste invisible plus longtemps. Le Scénario 2 commence sans soupçon institutionnel."},{id:"rev_protocol_s01",titre:"Le protocole S-01 relie Thade à Nyx et à Sealine",resume:"Le dossier médical scellé de Sealine Vael (inscrit sous le nom marital Coren, S. — 12-VAEL) contient le protocole S-01, établi 28 jours avant la catastrophe de Nyx. S-01 = Sealine. Thade a exploré la 'littérature interdite' avant la catastrophe. Nyx n'était pas un accident — c'était une tentative de sauver Sealine qui a mal tourné.",sources:["Archives Médicales Scellées : dossier 'Coren, S. — 12-VAEL — Médical' (Acte II, scène 2).","Notes de Jaren Velt : cachet de Caldris et écriture inconnue (Acte I, scène 2)."],declencheur:"Médecine DD 15 ou Investigation DD 12 dans les archives.",plan_b:"Le nom 'S-01' et la référence à la 'littérature interdite' sont lisibles sans jet. Olane peut faire le lien si les PJ lui montrent le dossier. Le cachet de Caldris sur les notes de Jaren est trouvable par Discrétion DD 12.",consequence_si_ratee:"Les PJ ne comprennent pas le motif de Thade. Sans S-01, Thade reste un bienfaiteur incompréhensible. La confrontation du Scénario 3 perd sa dimension tragique."},{id:"rev_thade_orchestre",titre:"Thade Coren orchestre lui-même les prélèvements",resume:"Thade ne se contente pas d'enquêter : il commande les profanations. Jaren Velt était son agent. Les textes des Endeuillés d'Edran Morn viennent de la Réserve Interdite — Thade les a laissés circuler. Les os convergent vers la Tour Arcanique.",sources:["Mort de Jaren : rune de Dissection à Distance, signature de Thade (Acte I, scène 3).","Résistance : le Collecteur confirme que des caisses d'os circulent dans les égouts (Acte III, scène 2).","Olane : les flux arcaniques sont détournés vers la Tour (Acte II, scène 3)."],declencheur:"Connaissances (mystères) DD 16 sur la rune + Renseignements DD 14 avec le Collecteur.",plan_b:"Le parfum de lavande relie le bureau de Thade à la mort de Jaren sans jet. Le Collecteur peut confirmer les caisses d'os avec Diplomatie DD 13. Olane dit 'La Tour. Regardez la Tour.' même en cas d'échec.",consequence_si_ratee:"Les PJ soupçonnent l'Université mais pas Thade personnellement. Le choix du Scénario 1 (Acte III) perd sa force. Les PJ peuvent rejoindre la Résistance sans comprendre qui ils combattent."},{id:"rev_resistance_existe",titre:"La Résistance de la Vieille Ville est une alternative à l'Université",resume:"Un réseau clandestin — Mara, Ursula, le Collecteur, Sniv — soigne les malades, cache les fugitifs et cherche la vérité sur Thade depuis huit ans. Ils ont accès aux égouts, à la pègre et aux malades — des pistes que l'Université ne peut pas fournir.",sources:["Maison des Retours : rencontre avec Mara et le réseau (Acte III, scène 2)."],declencheur:"Diplomatie DD 13 avec Mara.",plan_b:"Même en cas d'échec, Mara offre un repas et dit que la Résistance existe. Les PJ peuvent revenir. Sniv propose de montrer les passages des égouts indépendamment de la confiance de Mara.",consequence_si_ratee:"Les PJ restent dépendants de l'Université pour leur enquête. Sans accès aux égouts et à la pègre, ils ne peuvent pas suivre la piste des ossements. Le Scénario 2 démarre avec moins de ressources et d'alliés."}],fronts_actifs:[{id_front:"front_plan_thade",nom:"Le Plan de Thade",etat_initial:"Thade a récupéré les fragments d'os des Thanes T-01 à T-03 via les profanations récentes, plus T-04 grâce à un prélèvement ancien jamais découvert (coffret plombé dans son bureau). Trois tombes sont officiellement profanées ; la quatrième l'a été discrètement il y a des années. Il utilise l'Université comme couverture et les PJ comme outils d'enquête pour contrôler l'information. L'horloge est à l'étape 1.",manifestation_scenarios:"Thade engage les PJ pour enquêter sur ses propres profanations. Jaren Velt est son agent sur le terrain. La mort de Jaren est un nettoyage. Les os convergent vers la Tour par les égouts.",interactions_scenes:[{scene:"Le Bureau de Thade Coren",interaction:"Thade recrute les PJ comme outils. Le coffret plombé est visible. L'horloge avance d'un segment si les PJ acceptent sans poser de questions."},{scene:"Première Descente aux Terrasses",interaction:"Jaren transmet chaque découverte à Thade. Les PJ travaillent pour l'antagoniste sans le savoir."},{scene:"La Mort de Jaren Velt",interaction:"Thade élimine un témoin gênant. La rune de Dissection à Distance est sa signature. L'horloge avance d'un segment."},{scene:"Le Bureau d'Olane",interaction:"Olane révèle que les flux sont détournés vers la Tour. Si les PJ la protègent, l'horloge ralentit. S'ils l'ignorent, Thade accélère son isolement."}],leviers_pj_scenario:"Les PJ peuvent ralentir ce front en : refusant de transmettre leurs découvertes à Thade, en protégeant Olane, en suivant les os via les égouts, en comprenant que Jaren était un agent."},{id_front:"front_sceau_qui_cede",nom:"Le Sceau qui cède",etat_initial:"Trois des sept tombes sont officiellement touchées au début du scénario. En réalité, une quatrième (T-04) a été prélevée discrètement il y a des années — Thade avait déjà commencé avant que la crise ne soit visible. Le froid et les vibrations s'étendent vers les galeries. L'horloge est à l'étape 1-2.",manifestation_scenarios:"Les profanations sont le symptôme visible. Le Mausolée vibre, le Puits de l'Abîme pulse. À l'Acte III, cinq tombes sur sept sont touchées. Thorgar accomplit les rites incomplets chaque nuit.",interactions_scenes:[{scene:"Première Descente aux Terrasses",interaction:"Les PJ voient trois tombes touchées. Le froid du Mausolée est perceptible. Premier signe que le sceau cède."},{scene:"Le Temple-Forgeron et les Rites Perdus",interaction:"Thorgar révèle que les rites maintiennent le sceau. Si les PJ proposent de restaurer les rites, le MJ retire un segment de l'horloge."},{scene:"Le Retour au Cimetière",interaction:"Cinq tombes sur sept sont touchées. Le bourdonnement du Puits est audible. L'horloge est à l'étape 3-4. Urgence maximale."}],leviers_pj_scenario:"Les PJ peuvent ralentir ce front en : restaurant les rites avec Thorgar (retire un segment), en protégeant les deux dernières tombes, en récupérant les ossements pour les replacer."},{id_front:"front_cite_sous_pression",nom:"La Cité sous pression",etat_initial:"Le Conseil traite les profanations comme du vandalisme. L'Université défère à Thade par confiance. Olane est isolée. L'horloge est à l'étape 1.",manifestation_scenarios:"L'Université classe les anomalies comme incidents locaux. Olane n'a plus accès à ses données. Le Conseil enterre la crise sous la procédure. La mémoire du sceau est perdue.",interactions_scenes:[{scene:"Le Bureau de Thade Coren",interaction:"Thade instrumentalise son statut institutionnel. Le Conseil ne s'intéresse pas au Cimetière."},{scene:"Le Bureau d'Olane",interaction:"Olane est le pont entre l'Université et le Conseil. Si les PJ la soutiennent, l'Université peut être retournée. Sinon, elle reste isolée et le front avance."},{scene:"Le Temple-Forgeron et les Rites Perdus",interaction:"La mémoire perdue est un enjeu direct. Thorgar accomplit des gestes sans comprendre leur sens. C'est le symptôme de l'oubli institutionnel."}],leviers_pj_scenario:"Les PJ peuvent ralentir ce front en : soutenant Olane publiquement, en rassemblant des preuves pour le Conseil, en restaurant la mémoire du sceau via Thorgar et les archives."},{id_front:"front_factions_crise",nom:"Les Factions de la Crise",etat_initial:"Les cercles de Nyx commencent à s'organiser. Edran Morn recrute parmi les endeuillés. Le Champion n'est pas encore visible. L'horloge est à l'étape 1, à peine visible.",manifestation_scenarios:"Présence limitée. Les PJ peuvent croiser des agents de Thade ou des Endeuillés d'Edran Morn au Cimetière la nuit. Le cachet de Caldris sur les notes de Jaren est une amorce vers Elian Voss. La Résistance existe déjà mais n'est pas encore un acteur public.",interactions_scenes:[{scene:"Première Descente aux Terrasses",interaction:"Les notes de Jaren portent un cachet de Caldris — amorce de la piste Elian Voss pour le Scénario 2."},{scene:"La Rencontre avec la Résistance",interaction:"La Résistance est un acteur de la crise. Le Collecteur a des informations sur les caisses d'os dans les égouts. Sniv a trouvé des passages récents."}],leviers_pj_scenario:"Les PJ peuvent amorcer ce front en : rencontrant la Résistance, en suivant le cachet de Caldris, en évitant de radicaliser les Endeuillés s'ils les croisent."}],scenes_structure:{legende:{obligatoire:"La scène doit se jouer. Sans elle, le scénario perd sa colonne vertébrale.",obligatoire_flexible:"La scène doit se jouer, mais son ordre, sa forme ou son lieu peuvent varier. La révélation qu'elle apporte est indispensable.",optionnel:"La scène enrichit l'expérience mais peut être sautée ou condensée sans casser le scénario."},scenes:[{titre:"Le Bureau de Thade Coren",acte:"Acte I",statut:"obligatoire",ordre:1,dependances:[],revele:["Thade engage les PJ","coffret plombé visible","parfum de lavande"],flexible:"Peut se jouer dans n'importe quel lieu de l'Université si le bureau ne convient pas. L'essentiel est le mandat et le doute optionnel."},{titre:"Première Descente aux Terrasses",acte:"Acte I",statut:"obligatoire",ordre:2,dependances:["Le Bureau de Thade Coren"],revele:["outils d'Université","runes dans l'os","froid du Mausolée","notes de Jaren"],flexible:"Thorgar peut être remplacé par un autre gardien nain si besoin. Jaren doit être présent — c'est sa seule apparition avant sa mort."},{titre:"La Mort de Jaren Velt",acte:"Acte I",statut:"obligatoire",ordre:3,dependances:["Première Descente aux Terrasses"],revele:["rune de Dissection à Distance","parfum de lavande","pages arrachées"],flexible:"Le timing peut varier (lendemain ou surlendemain). Si les PJ ne sont pas sur place, on les fait appeler. La scène peut aussi se jouer au Pavillon Nord ou ailleurs dans l'Université."},{titre:"Le Temple-Forgeron et les Rites Perdus",acte:"Acte II",statut:"obligatoire_flexible",ordre:4,dependances:["Première Descente aux Terrasses"],revele:["rites d'Edhrek-Murn","runes d'ancrage","les tombes sont un système actif"],flexible:"La révélation sur les rites peut venir d'une autre source (archives, vieux textes) si les PJ n'ont pas gagné la confiance de Thorgar. Mais Thorgar est le meilleur vecteur narratif."},{titre:"Les Archives Médicales Scellées",acte:"Acte II",statut:"obligatoire_flexible",ordre:5,dependances:["La Mort de Jaren Velt"],revele:["protocole S-01","Sealine","littérature interdite","Nyx n'était pas un accident"],flexible:"Les PJ peuvent trouver S-01 par d'autres moyens : cahiers personnels de Thade, confidences d'Olane, ou le laboratoire d'Elian Voss (si le MJ avance cette piste). Mais le dossier scellé est la source la plus directe."},{titre:"Le Bureau d'Olane",acte:"Acte II",statut:"obligatoire_flexible",ordre:6,dependances:["La Mort de Jaren Velt"],revele:["flux détournés vers la Tour","isolement d'Olane","Olane est une alliée"],flexible:"Olane peut rencontrer les PJ ailleurs (bibliothèque, couloir, Conseil). L'essentiel est qu'elle devienne une alliée si les PJ apportent des preuves. Sans cette scène, les PJ perdent leur seul accès institutionnel."},{titre:"Le Retour au Cimetière",acte:"Acte III",statut:"obligatoire_flexible",ordre:7,dependances:["Le Temple-Forgeron et les Rites Perdus"],revele:["cinq tombes sur sept touchées","empreinte planaire","urgence maximale"],flexible:"Peut être fusionné avec une scène d'action si les PJ interceptent des profanateurs sur place. L'essentiel est l'urgence : le sceau est proche de la rupture."},{titre:"La Rencontre avec la Résistance",acte:"Acte III",statut:"obligatoire_flexible",ordre:8,dependances:[],revele:["la Résistance existe","passages des égouts","caisses d'os avec cachet de Caldris"],flexible:"La Résistance peut contacter les PJ plutôt que l'inverse. Ursula, Tibbet ou un malade aidé peuvent servir de pont. La scène peut se jouer plus tôt si les PJ cherchent des alliés en dehors de l'Université."},{titre:"Le Choix",acte:"Acte III",statut:"obligatoire",ordre:9,dependances:["Le Retour au Cimetière","La Rencontre avec la Résistance"],revele:["le moment pivot","Thade prélève les os pour ouvrir le seuil"],flexible:"Le choix peut être différé mais pas évité. Si les PJ refusent de choisir, le temps passe et le sceau cède davantage. La scène peut se jouer dans n'importe quel lieu neutre."}],scenes_optionnelles:[{titre:"Interception de profanateurs",description:"Les PJ croisent des agents de Thade ou des Endeuillés d'Edran Morn au Cimetière de nuit. Combat ou négociation possible.",declencheur:"Si les PJ visitent le Cimetière de nuit sans prévenir.",apport:"Preuve directe que les profanations sont organisées. Possibilité de capturer un agent et de l'interroger."},{titre:"Les Égouts avec Sniv",description:"Sniv guide les PJ dans les passages creusés entre le Cimetière et la Vieille Ville. Exploration, dangers, et découverte des caisses d'os.",declencheur:"Si les PJ acceptent l'aide de Sniv après la Rencontre avec la Résistance.",apport:"Preuve physique du circuit des ossements. Piste directe vers la Tour ou vers les destinataires."},{titre:"Confrontation avec un Loyaliste",description:"Les PJ interpellent un maître arcaniste loyaliste qui défend l'Université. Débat institutionnel.",declencheur:"Si les PJ cherchent à alerter l'Université avant d'avoir des preuves solides.",apport:"Comprendre que l'Université n'est pas complice mais aveugle. Le loyaliste peut être retourné plus tard."},{titre:"Visite à Ursula",description:"Les PJ rencontrent Ursula dans son dispensaire clandestin. Elle soigne des malades que l'Université refuse.",declencheur:"Si les PJ cherchent des soins ou des informations sur les malades de la Vieille Ville.",apport:"Comprendre l'ampleur humaine de la crise. Ursula peut servir de pont vers la Résistance."}]},encadres_mj:[{id:"enc_pj_ratent",titre:"Que faire si les PJ ratent leurs jets",situation:"Les PJ échouent à répétition aux jets d'Investigation, de Connaissances ou de Diplomatie. Ils n'ont aucun indice, aucune révélation, aucun allié.",principe:"Le scénario ne se bloque jamais sur un jet. Chaque révélation a un plan B. Si tous les jets échouent, le MJ utilise les PNJ comme vecteurs de l'information.",proceder:[{etape:"Identifier ce qui manque",detail:"Quelle révélation indispensable n'a pas été obtenue ? Consulter la liste des revelations_indispensables et leur plan_b."},{etape:"Utiliser un PNJ comme vecteur",detail:"Thorgar dit ce qu'il sait sans jet si les PJ lui posent la bonne question. Olane fait le lien si les PJ lui montrent le dossier. Le Collecteur donne les informations sur les caisses si les PJ acceptent le repas de Mara."},{etape:"Laisser le monde réagir",detail:"Si les PJ n'ont pas compris que le sceau cède, le monde le leur montre : le froid s'étend, les lanternes s'éteignent, les mineurs refusent de descendre. Les signes visibles des fronts avancent sans jet."},{etape:"Différer, pas bloquer",detail:"Si les PJ ratent la scène des Archives, S-01 peut être trouvé plus tard — dans les cahiers de Thade au Scénario 2, ou par Olane qui fait le lien elle-même. La révélation est différée, pas perdue."}],a_ne_pas_faire:"Ne pas faire rejouer le jet. Ne pas donner l'information gratuitement. Ne pas punir les PJ pour leurs échecs — laisser le monde s'adapter et offrir d'autres voies."},{id:"enc_accusent_thade",titre:"Que faire si les PJ accusent Thade prématurément",situation:"Dès la scène 1 ou 2, les PJ soupçonnent Thade et l'accusent ouvertement, sans preuve.",principe:"Thade ne peut pas être accusé sans preuve. L'Université le protège. Le Conseil lui fait confiance. Une accusation prématurée se retourne contre les PJ.",proceder:[{etape:"Thade reste calme",detail:"Thade ne se défend pas avec agressivité. Il écoute, il acquiesce, il dit : « Je comprends votre suspicion. C'est exactement pourquoi j'ai besoin de vous. Si je suis le coupable, enquêter est le meilleur moyen de le prouver. » Il retourne l'accusation en mandat."},{etape:"L'Université protège Thade",detail:"Si les PJ vont au Conseil ou à l'Université sans preuve, on leur dit que Thade est l'Archimage, qu'il a sauvé la cité, et que des enquêteurs sans preuves ne sont pas crédibles. Pas par méchanceté — par confiance institutionnelle."},{etape:"Olane comme soupape",detail:"Si les PJ cherchent un allié pour leur suspicion, Olane est la bonne porte. Elle ne confirme pas, mais elle ne ferme pas. Elle dit : « Apportez-moi quelque chose. N'importe quoi. Et je vous écoute. »"},{etape:"Transformer l'accusation en enquête",detail:"Le MJ guide les PJ vers la collecte de preuves : la rune sur la nuque de Jaren, le dossier S-01, les caisses d'os dans les égouts. L'accusation n'est pas annulée — elle est transformée en projet d'enquête."}],a_ne_pas_faire:"Ne pas faire arrêter les PJ. Ne pas faire punir Thade par le MJ. Ne pas confirmer ni infirmer l'accusation sans preuve. Laisser les PJ formuler leur hypothèse et la tester."},{id:"enc_refusent_mission",titre:"Que faire si les PJ refusent la mission de Thade",situation:"Les PJ refusent l'ordre de mission de Thade dès la scène 1. Ils ne veulent pas travailler pour l'Université.",principe:"Le refus est un choix valide. Mais les profanations continuent. Le sceau cède. Le monde n'attend pas les PJ.",proceder:[{etape:"Thade accepte le refus",detail:"Thade ne insiste pas. Il dit : « Je comprends. Si vous changez d'avis, vous savez où me trouver. » Il trouve d'autres enquêteurs — moins compétents, plus dociles. Les profanations continuent."},{etape:"Le monde avance sans les PJ",detail:"Le MJ fait avancer les horloges. Une nouvelle tombe est touchée chaque semaine. Le froid s'étend. Les mineurs commencent à parler. Les symptômes apparaissent dans la Vieille Ville. Les PJ entendent les rumeurs."},{etape:"La Résistance comme porte d'entrée",detail:"Si les PJ refusent l'Université, ils peuvent rencontrer la Résistance par d'autres voies : un malade soigné par Ursula, un fugitif caché par Mara, un passage découvert par Sniv. La Résistance ne demande pas un ordre de mission — elle demande de l'aide."},{etape:"Thorgar comme alternative",detail:"Thorgar cherche de l'aide. Si les PJ descendent aux Terrasses par eux-mêmes, il les accueille. Il n'a pas besoin de l'ordre de mission de l'Université — il a besoin de quelqu'un qui écoute."},{etape:"Le retard a un prix",detail:"Si les PJ refusent et reviennent plus tard, le sceau a cédé davantage. Trois tombes touchées deviennent quatre ou cinq. Olane est plus isolée. La Résistance est plus désespérée. Le scénario se joue, mais dans des conditions plus difficiles."}],a_ne_pas_faire:"Ne pas forcer les PJ à accepter. Ne pas punir le refus. Ne pas annuler les conséquences du retard. Le monde avance, les PJ décident quand ils entrent."},{id:"enc_tuent_thorgar",titre:"Que faire si les PJ attaquent ou tuent Thorgar",situation:"Les PJ, par panique ou par erreur, attaquent Thorgar ou le tuent.",principe:"Thorgar est le seul à connaître les rites. Sans lui, le sceau perd son dernier gardien. Mais le scénario ne se termine pas.",proceder:[{etape:"Conséquences immédiates",detail:"Les gardes du Temple-Forgeron interviennent. Les PJ sont chassés des Terrasses. Les clans nains coupent tout contact. La réputation des PJ est entachée."},{etape:"Les rites s'arrêtent",detail:"Sans Thorgar, les rites d'Edhrek-Murn ne sont plus accomplis. L'horloge du front « Le Sceau qui cède » accélère — le MJ ajoute un segment par session."},{etape:"Alternative pour les rites",detail:"Les rites peuvent être retrouvés dans les archives du Temple-Forgeron, mais ils nécessitent Connaissances (religion) DD 18 et plusieurs sessions de recherche. Un autre prêtre nain peut être formé, mais il faut du temps — temps que les PJ n'ont pas."},{etape:"La Résistance comme voie",detail:"Mara peut envoyer quelqu'un qui connaît les rites partiels — un vieux nain de la Vieille Ville, ancien apprenti du maître de Thorgar. Mais il est fragile, et les rites qu'il connaît sont incomplets."}],a_ne_pas_faire:"Ne pas annuler l'impact de la mort de Thorgar. Ne pas rendre les rites trivialement retrouvables. Les PJ ont cassé quelque chose d'irremplaçable — le monde le leur rappelle."},{id:"enc_vont_au_conseil",titre:"Que faire si les PJ vont au Conseil trop tôt",situation:"Les PJ tentent d'alerter le Conseil de Valombre avant d'avoir des preuves solides.",principe:"Le Conseil traite les profanations comme du vandalisme. Sans preuve arcanique ou témoignage de poids, l'alerte est classée.",proceder:[{etape:"Le Conseil écoute poliment",detail:"Un conseiller reçoit les PJ. Il prend des notes. Il dit que le sujet sera examiné. Il ne ment pas — il examine. Mais l'examen est lent, procédurier, et Thade a plus de poids institutionnel que les PJ."},{etape:"Thade neutralise",detail:"Thade, informé par ses contacts au Conseil, intervient discrètement. Il ne discrédite pas les PJ — il reformule. Il dit : « J'ai déjà engagé ces enquêteurs. Ils font un excellent travail. Le Conseil n'a pas à s'inquiéter. » Il transforme l'alerte en confirmation de sa propre diligence."},{etape:"Olane comme voix au Conseil",detail:"Si les PJ ont gagné la confiance d'Olane, elle peut porter leur voix au Conseil. Mais elle a besoin de preuves — sans preuve, elle est isolée et le Conseil l'ignore."},{etape:"Le Conseil comme acteur tardif",detail:"Le Conseil n'agit que face à une preuve irréfutable ou à une crise visible. Si le sceau cède visiblement (froid, tremblements, anomalies), le Conseil réagit — mais tard, trop tard pour prévenir."}],a_ne_pas_faire:"Ne pas ridiculiser les PJ au Conseil. Ne pas bloquer la voie institutionnelle. Le Conseil est lent, pas hostile. Il protège Thade par confiance, pas par complicité."}],aides_jeu:{indices_recap:[{indice:"Ciselets d'Université",scene:"Première Descente aux Terrasses",jet:"Investigation DD 14",info:"Les passages sous les dalles ont été creusés avec des outils de précision d'Université, pas des outils de vandale.",pointeur:"Quelqu'un à l'Université est impliqué."},{indice:"Runes dans l'os",scene:"Première Descente aux Terrasses",jet:"Médecine DD 12 ou Connaissances (religion) DD 15",info:"Les ossements prélevés portent des runes d'ancrage gravées. Ce ne sont pas des décorations — ce sont des points de fixation rituelle.",pointeur:"Les tombes sont un système actif, pas des monuments."},{indice:"Notes de Jaren — cachet de Caldris",scene:"Première Descente aux Terrasses",jet:"Discrétion DD 12 ou Vol DD 14",info:"Le carnet de Jaren contient des pages en écriture inconnue et un cachet de Caldris. Certaines pages ont été arrachées après sa mort.",pointeur:"Jaren avait un contact extérieur. Piste pour Elian Voss (Scénario 2)."},{indice:"Rune de Dissection à Distance",scene:"La Mort de Jaren Velt",jet:"Connaissances (mystères) DD 16",info:"La rune sur la nuque de Jaren est une variante publiée par Thade Coren il y a six ans. Signature arcanique identifiable.",pointeur:"Thade a tué Jaren. Ou quelqu'un qui utilise ses méthodes."},{indice:"Parfum de lavande",scene:"Le Bureau de Thade Coren / La Mort de Jaren Velt",jet:"Perception DD 10",info:"Le même parfum de lavande alchimique dans le bureau de Thade et sur le lieu de la mort de Jaren.",pointeur:"Relie Thade à la mort de Jaren. Pas une preuve, mais un indice atmosphérique."},{indice:"Pages arrachées du carnet de Jaren",scene:"La Mort de Jaren Velt",jet:"Investigation DD 13",info:"Les pages écrites ont été arrachées proprement après la mort. Quelqu'un a pris les notes.",pointeur:"Les notes contenaient des informations sur S-01 et le cachet de Caldris."},{indice:"Protocole S-01",scene:"Les Archives Médicales Scellées",jet:"Médecine DD 15 ou Investigation DD 12",info:"Dossier médical de Sealine Vael (nom marital : Coren, S. — 12-VAEL). S-01 = Sealine, premier patient. Protocole établi 28 jours avant Nyx. Mention « littérature interdite ».",pointeur:"Thade explorait la littérature interdite avant la catastrophe. Nyx n'était pas un accident."},{indice:"Flux détournés vers la Tour",scene:"Le Bureau d'Olane",jet:"Fourni par Olane",info:"Les flux arcaniques de l'Université sont détournés vers la Tour Arcanique par quelqu'un qui a un accès de haut niveau.",pointeur:"Thade utilise les ressources de l'Université pour son rituel."},{indice:"Caisses d'os dans les égouts",scene:"La Rencontre avec la Résistance",jet:"Renseignements DD 14 ou Diplomatie DD 13 avec le Collecteur",info:"Des caisses d'os circulent dans les égouts. Cachet de Caldris et marquage d'Université. Convergent vers la Tour.",pointeur:"Circuit physique des ossements : Cimetière → égouts → Tour."},{indice:"Runes qui changent",scene:"Le Retour au Cimetière",jet:"Connaissances (mystères) DD 16",info:"Les runes d'ancrage sur les tombes touchées se transforment en runes d'ouverture. Quelqu'un remplace le sceau par un autre système.",pointeur:"Thade ne brise pas le sceau — il le remplace par un système d'ouverture."},{indice:"Empreinte planaire au Mausolée",scene:"Le Retour au Cimetière",jet:"Connaissances (mystères) DD 14",info:"Le froid du Puits de l'Abîme porte une texture planaire. La Spirale filtre par les fissures du sceau.",pointeur:"Le sceau cède. La Spirale est déjà là, partiellement."}],pnj_recap:[{id:"thade_coren",nom:"Thade Coren",faction:"Université",role_court:"Mandataire / Antagoniste caché",apparition:"Scène 1, puis en filigrane jusqu'à la fin",info_cle:"Engage les PJ pour enquêter sur ses propres profanations. S-01 est son motif. La lavande est sa signature.",dd_clés:"Connaissances (mystères) DD 16 pour identifier la rune de Dissection à Distance"},{id:"thorgar_pretre_nain",nom:"Thorgar",faction:"Temple-Forgeron",role_court:"Gardien des rites / Allié potentiel",apparition:"Scène 2, puis Acte II et III",info_cle:"Connaît les gestes d'Edhrek-Murn mais pas leur sens. Seul à pouvoir restaurer les rites.",dd_clés:"Diplomatie DD 14 pour qu'il montre les gestes"},{id:"jaren_velt",nom:"Jaren Velt",faction:"Université (agent de Thade)",role_court:"Surveillant / Victime",apparition:"Scène 2, mort scène 3",info_cle:"Transmet les découvertes des PJ à Thade. Son carnet contient le cachet de Caldris. Tué par Dissection à Distance.",dd_clés:"Discrétion DD 12 pour examiner le carnet"},{id:"maera_olane",nom:"Maëra Olane",faction:"Université (isolée)",role_court:"Alliée institutionnelle",apparition:"Acte II, scène 3",info_cle:"Sait que les flux sont détournés. Isolée par l'institution. Peut fournir accès, données et couverture.",dd_clés:"Pas de jet — elle s'ouvre si les PJ apportent des preuves"},{id:"mara_dirigeante",nom:"Mara",faction:"Résistance",role_court:"Dirigeante de la Résistance",apparition:"Acte III, scène 2",info_cle:"Cherche la vérité sur Nyx depuis huit ans. Offre une alternative à l'Université.",dd_clés:"Diplomatie DD 13 pour gagner sa confiance"},{id:"le_collecteur",nom:"Le Collecteur",faction:"Résistance",role_court:"Récupérateur d'informations",apparition:"Acte III, scène 2",info_cle:"Connaît le circuit des caisses d'os dans les égouts. Cachet de Caldris et marquage d'Université.",dd_clés:"Renseignements DD 14 ou Diplomatie DD 13"},{id:"sniv_kobold",nom:"Sniv",faction:"Résistance",role_court:"Guide des égouts",apparition:"Acte III, scène 2",info_cle:"Kobold qui connaît les passages souterrains. Peut montrer les passages creusés récents.",dd_clés:"Pas de jet — il propose son aide spontanément"},{id:"ursula_fraternite",nom:"Ursula",faction:"Résistance",role_court:"Soigneuse clandestine",apparition:"Acte III, scène 2 (ou scène optionnelle)",info_cle:"Soigne les malades que l'Université refuse. Les symptômes ressemblent à ceux de Sealine.",dd_clés:"Pas de jet — elle parle si les PJ cherchent des soins"}],lieux_recap:[{id:"bureau_thade_universite",nom:"Bureau de Thade Coren",zone:"Université — Pavillon Nord, dernier étage",ambiance:"Lavande, papier ancien, coffret plombé. Vue sur la Tour.",scenes:["Le Bureau de Thade Coren"]},{id:"cimetiere_thanes",nom:"Cimetière des Terrasses",zone:"Flanc nord de la colline",ambiance:"Gradins de pierre, lanternes funéraires, froid anormal. Mausolée au centre.",scenes:["Première Descente aux Terrasses","Le Retour au Cimetière"]},{id:"mausolee_seuil",nom:"Mausolée du Seuil",zone:"Centre du Cimetière",ambiance:"Dalle vibrante, bourdonnement du Puits de l'Abîme, froid planaire.",scenes:["Le Retour au Cimetière"]},{id:"temple_forgeron",nom:"Temple-Forgeron de Moradin",zone:"Sous les Terrasses",ambiance:"Martèlement de l'enclume, bas-reliefs usés, chapelle souterraine.",scenes:["Le Temple-Forgeron et les Rites Perdus"]},{id:"archives_scellees_universite",nom:"Archives Médicales Scellées",zone:"Université — Pavillon Sud, sous-sol",ambiance:"Cuir, produits de conservation, lampe alchimique bourdonnante.",scenes:["Les Archives Médicales Scellées"]},{id:"salle_4b",nom:"Bureau d'Olane",zone:"Université — Salle 4B",ambiance:"Dossiers, graphiques, fils de laine, café d'orge. Désordre organisé.",scenes:["Le Bureau d'Olane"]},{id:"maison_des_retours",nom:"Maison des Retours",zone:"Vieille Ville — derrière une blanchisserie",ambiance:"Savon, soupe, cire à briquet. Lits de malades, rideaux de vieux draps.",scenes:["La Rencontre avec la Résistance"]},{id:"qg_resistance",nom:"Salle de filtration (QG temporaire)",zone:"Égouts des Terrasses",ambiance:"Voûte basse, tuyaux rouillés, table de pierre, lampe alchimique.",scenes:["Le Choix"]}],chronologie:[{phase:"Avant le scénario",evenements:["Il y a 8 ans : catastrophe de Nyx. Sealine se sacrifie. Thade survit.","Il y a 8 ans : Thade devient Archimage de l'Université. L'Université est reconstruite.","Il y a 6 ans : Thade publie la variante de Dissection à Distance.","Depuis 8 ans : Thade prélève les ossements des Thanes par intermittence.","Depuis 8 ans : la Résistance se forme autour de Mara et Ursula.","Récemment : Thade accélère les prélèvements. Trois tombes touchées."]},{phase:"Acte I — L'Engagement (semaine 1)",evenements:["Jour 1 : Thade engage les PJ.","Jour 2-3 : Première descente aux Terrasses. Thorgar, Jaren, indices.","Jour 3-5 : Mort de Jaren Velt. Le scénario bascule."]},{phase:"Acte II — La Découverte du Verrou (semaines 2-3)",evenements:["Thorgar révèle les rites d'Edhrek-Murn.","Les PJ infiltrent les Archives. S-01 est découvert.","Olane devient une alliée. Les flux sont confirmés.","Une quatrième tombe est touchée si les PJ tardent."]},{phase:"Acte III — Le Tournant (semaine 4)",evenements:["Cinq tombes sur sept sont touchées. Le sceau cède visiblement.","La Résistance s'offre comme alternative.","Le Choix : Thade, la Résistance, ou une troisième voie.","Le scénario se termine sur la décision des PJ."]},{phase:"Transition vers le Scénario 2",evenements:["Si les PJ ont rejoint la Résistance : ils ont des alliés, des égouts, et des ennemis à l'Université.","Si les PJ restent avec Thade : ils ont un mandat, des ressources, et un doute qui grandit.","Si les PJ ont confronté Thade : la relation est tendue, mais pas rompue. Thade surveille.","Dans tous les cas : le déphasage commence à se manifester. Les routes mentent doucement."]}]},synopsis:"Valombre vit sur un verrou qu'elle ne nomme plus. Quand des tombes naines sont profanées au Cimetière des Terrasses, l'Archimage Thade Coren engage les PJ pour enquêter. Ce qu'ils découvrent dépasse de loin le simple vandalisme : les Sept Thanes ne sont pas des fondateurs honorés, ce sont les ancrages du sceau qui maintient la Spirale close. Et quelqu'un prélève leurs ossements.",evenements_mondiaux:{chronologie_inevitable:["Les profanations continuent au Cimetière. Une nouvelle tombe est touchée chaque semaine si les PJ n'interviennent pas.","Le froid et les vibrations s'étendent depuis le Cimetière vers les galeries de la mine.","Thade renforce ses prélèvements via l'Université. Des fragments d'os convergent vers la Tour Arcanique.","L'Université classe les anomalies comme incidents locaux. Olane est isolée professionnellement."],consequences_echecs:["Si les PJ ignorent les profanations : le Front 'Le Sceau qui cède' avance d'une étape.","Si les PJ servent Thade sans poser de questions : le Front 'Le Plan de Thade' avance.","Si les PJ détruisent des preuves pour protéger Thade : Olane perd ses derniers indices.","Si les PJ quittent Valombre sans conclure : le déphasage s'aggrave."]},actes:[{titre:"Acte I — L'Engagement",stake:"Les PJ acceptent une mission de Thade Coren sans savoir qu'ils servent l'antagoniste principal.",location:"Université Arcanique & Cimetière des Terrasses",scenes:[{id:"s1_bureau_thade",titre:"Le Bureau de Thade Coren",type:"Social",resume_mj:"Thade reçoit les PJ dans son bureau. Poli, précis, jamais pressé. Il leur demande d'enquêter sur des profanations au Cimetière. Il présente cela comme un service à la cité.",idLieu:"bureau_thade_universite",idsPnj:["thade_coren"],format_livre:{ambiance:`Le bureau de Thade Coren occupe le dernier étage du Pavillon Nord de l'Université. On y monte par un escalier en colimaçon dont les marches sont usées au centre — des décennies d'érudits ont gravé ce passage. La porte est en chêne massif, sans plaque, sans nom. On frappe, on attend. La lavande flotte dans l'air bien avant que la porte ne s'ouvre.

L'intérieur sent la lavande et le papier ancien. Des livres tapissent les murs du sol au plafond, rangés par couleur de reliure — un système de classification qui n'appartient qu'à Thade. Un coffret plombé repose sur une étagère, à hauteur d'épaule, sans serrure apparente. La fenêtre donne sur les toits de l'Université et, au loin, sur la Tour Arcanique.

Thade se lève quand les PJ entrent. Il est grand, mince, vêtu de gris. Son visage porte les traces d'un homme qui a survécu à quelque chose qu'il n'évoquera pas. Il propose du thé — un thé d'orge amer, pas une boisson de cérémonie. L'expression est celle d'un homme qui a déjà pleuré tout ce qu'il pouvait pleurer.`,deroulement_narratif:`Thade accueille les PJ avec une courtoisie précise, sans chaleur excessive. Il les installe, propose du thé, prend le temps de les regarder. Puis il va droit au fait.

Quelqu'un profane les tombes du Cimetière des Terrasses. Les clans nains ne parlent pas à l'Université. Le Conseil traite cela comme du vandalisme. Ce n'est pas du vandalisme. Thade le sait. Il ne dit pas pourquoi il le sait — il présente cela comme une intuition d'archimage, un sentiment de celui qui connaît sa cité.

Il offre un ordre de mission et une bourse. L'ordre donne aux PJ un accès officiel au Cimetière et aux Terrasses. La bourse est modeste — pas assez pour acheter des mercenaires, assez pour vivre. Il précise : enquêter discrètement. Ne pas alerter le Conseil. Ne pas effrayer les clans.

Si les PJ posent des questions sur l'Ordre de Nyx, Thade répond avec calme. Il se présente comme un survivant, pas comme un coupable. Il a perdu des collègues. Il a perdu quelqu'un qu'il aimait. Il a reconstruit. Ce qu'il ne dit pas : il a reconstruit pour rouvrir le seuil.

Le coffret plombé est visible sur l'étagère. Un œil attentif remarque les runes de conservation funéraire gravées sur le plomb. Un nez attentif remarque que la lavande n'est pas un parfum ordinaire — c'est un masque olfactif alchimique.

Thade ne ment jamais directement. Il omet, il cadre, il oriente. Il dit « patrimoine » et non « sépultures ». Il dit « matériel » et non « recherches ». Chaque mot est choisi. Si un PJ perçoit ce soin, c'est le premier indice : Thade construit son discours.`,notes_mj:"Cette scène est le piège. Les PJ doivent vouloir travailler pour Thade. Si le MJ joue Thade comme un méchant évident, tout le scénario s'effondre. Thade est charismatique, crédible, et sincère dans sa douleur. Ce qui le rend dangereux n'est pas le mensonge — c'est l'omission."},texte_a_lire:`Le bureau de Thade Coren sent la lavande et le papier ancien. Des livres tapissent les murs du sol au plafond. Un coffret plombé repose sur une étagère. Thade se lève quand vous entrez — l'expression d'un homme qui a déjà pleuré tout ce qu'il pouvait pleurer.

« Asseyez-vous. Je vais être direct. Quelqu'un profane les tombes du Cimetière des Terrasses. Les clans nains ne parlent pas à l'Université, et le Conseil traite cela comme du vandalisme. Ce n'est pas du vandalisme. »`,objectif:"Accepter la mission de Thade : enquêter sur les profanations et identifier les responsables.",contexte_mj:{situation:"Thade a besoin d'enquêteurs extérieurs. Il présente les profanations comme un crime ordinaire. Il ne mentionne ni la Spirale, ni les Thanes, ni la Larme de Vael.",secrets:["Thade sait qui profane les tombes : ses propres agents ou les Endeuillés d'Edran Morn qu'il a indirectement encouragés.","Le coffret plombé contient des fragments d'os des Thanes T-01 à T-04. Trois proviennent des profanations récentes (T-01, T-02, T-03). Le quatrième (T-04) est un prélèvement ancien, réalisé il y a plusieurs années avant que la crise ne soit visible — Thade avait déjà commencé.","Thade dit 'matériel' et jamais 'recherches'. Il choisit ses mots avec précision."],rappels:["Thade ne ment jamais directement. Il omet, il cadre, il oriente.","L'ordre de mission donne aux PJ un accès officiel au Cimetière et aux Terrasses."]},defis:[{competence:"Psychologie",dd:15,reussite:"Thade cache quelque chose. Pas un mensonge, une omission soigneusement construite. Il parle des tombes comme de 'patrimoine' et non de 'sépultures'.",echec:"Thade semble sincère. Un homme brillant qui a survécu à une catastrophe et veut protéger sa cité."},{competence:"Investigation",dd:13,reussite:"Le coffret plombé est marqué de runes de conservation funéraire. Son contenu ressemble à des fragments d'os.",echec:"Le bureau est impeccable. Rien de suspect, sauf un parfum de lavande un peu trop intense."}],indices:[{indice:"Le coffret plombé",localisation:"Étagère du bureau de Thade",detection:"Investigation DD 13 ou Détection de la magie",information:"Fragments d'os conservés dans un liquide alchimique. Runes de préservation funéraire naine.",usage:"Premier indice que Thade s'intéresse aux tombes pour plus que des raisons patrimoniales."},{indice:"Le choix de mots de Thade",localisation:"Conversation",detection:"Psychologie DD 15",information:"Thade dit 'matériel' et pas 'recherches'. Il évite tout mot reliant les sépultures à un fonctionnement.",usage:"Signal que Thade construit son discours. Pas une preuve, mais un motif de méfiance."}],guide_mj:{intention:"Établir Thade comme charismatique et crédible. Les PJ doivent vouloir travailler pour lui.",mise_en_place:"Thade reçoit les PJ seul, à la tombée du jour. Le moment est confidentiel.",deroulement:["Thade accueille les PJ, les met à l'aise, propose du thé.","Il expose le problème : profanations, clans méfiants, Conseil indifférent.","Il offre un ordre de mission et une bourse. Précise : enquêter discrètement.","Il répond aux questions avec calme. Se présente comme un survivant de Nyx, pas comme un coupable."],actions_utiles:["Accepter la mission et prendre l'ordre de mission.","Poser des questions sur l'Ordre de Nyx et la catastrophe.","Demander à voir le Cimetière de nuit."],fronts_heritiers:["Front 'Le Plan de Thade' — les PJ deviennent les yeux de Thade.","Front 'Le Sceau qui cède' — les profanations sont le symptôme visible."],jeu_des_pnj:"Thade est poli, précis, jamais cruel. L'atrocité est dans l'efficacité, pas dans le ton.",escalade:"Si les PJ refusent, Thade n'insiste pas. Mais le lendemain, le Conseil publie un avis — les PJ se retrouvent sans accès au Cimetière.",sortie:"Les PJ quittent le bureau avec une mission et l'impression d'avoir rencontré un homme bon."},reperes_de_jeu:{indice_indispensable:"Les PJ doivent savoir que Thade les envoie au Cimetière et que les profanations ciblent les tombes des Sept Thanes.",ne_pas_bloquer_sur_un_jet:"Même si les PJ échouent leur Psychologie, Thade leur donne la mission.",question_dramatique:"Les PJ peuvent-ils faire confiance à un homme qui ne ment jamais mais qui ne dit jamais toute la vérité ?"},transitions:{resume:"La scène se termine quand les PJ acceptent la mission et quittent le bureau.",reussite:"Les PJ partent avec la mission ET un doute.",echec:"Les PJ partent avec la mission et aucune méfiance. Ils sont des outils dociles."}},{id:"s1_premiere_descente",titre:"Première Descente aux Terrasses",type:"Investigation",resume_mj:"Les PJ examinent les tombes profanées. Thorgar les accueille avec réserve. Les dalles portent des traces de prélèvement. Jaren Velt, étudiant de l'Université, est présent pour 'assister' — en réalité pour surveiller.",idLieu:"cimetiere_thanes",idsPnj:["thorgar_pretre_nain","jaren_velt"],format_livre:{ambiance:`Le Cimetière des Terrasses descend en gradins sur le flanc nord de la colline, comme un amphithéâtre taillé pour les morts. Des allées de pierre grise séparent les terrasses, bordées de lanternes funéraires au verre épais. L'air est froid — plus froid qu'il ne devrait l'être en cette saison, plus froid que dans les rues de la ville à cent mètres en contrebas. Le froid vient d'en dessous. Il remonte des fondations comme une respiration lente.

Un prêtre nain attend près de l'allée centrale. Il porte un tablier de forge sous sa chasuble — un homme qui travaille le métal et la pierre avant de travailler l'âme. Thorgar. Il garde ces terrasses depuis que son maître est mort, et il accomplit les rites que son maître lui a transmis sans comprendre pourquoi.

Jaren Velt est déjà là. Il prend des notes sur un carnet relié cuir, accroupi près d'une dalle, l'air concentré d'un étudiant appliqué. Il est serviable, anxieux, et transmettra tout ce qu'il voit à Thade le soir même.`,deroulement_narratif:`Thorgar accueille les PJ avec une réserve polie. Il accepte l'ordre de mission parce qu'il est officiel, mais il ne fait pas confiance aux humains de l'Université. Il les mène aux tombes profanées — trois des sept terrasses ont été touchées.

Les dalles sont intactes. Les inscriptions sont lisibles. Mais les fondations ont été percées par en-dessous, avec des outils de précision. Des ciselets d'Université, pas des outils de vandale. Les passages sont étroits, nets, faits par quelqu'un qui connaît la pierre. Investigation DD 14 pour identifier les marques.

Les restes prélevés portent des marques de rites funéraires nains très anciens — des runes gravées dans l'os lui-même. Médecine DD 12 pour les remarquer. Ces runes ne sont pas décoratives : ce sont des ancrages rituels. Thorgar peut les identifier si les PJ lui montrent, mais il ne sait plus ce qu'elles ancrent.

Jaren observe tout. Il prend des notes dans deux écritures — la sienne et une autre, plus ancienne. Certaines pages portent un cachet de Caldris. Discrétion DD 12 ou Vol DD 14 pour examiner le carnet sans qu'il remarque. S'il remarque, il devient nerveux et range le carnet.

Si les PJ demandent à voir le Mausolée du Seuil, Thorgar hésite. Diplomatie DD 13 pour le convaincre. Le Mausolée est au centre du Cimetière, une construction basse en pierre sombre. La dalle centrale vibre. Les lanternes vacillent sans vent. Le courant d'air froid qui remonte du Puits de l'Abîme est perceptible à tous — pas besoin de jet.`,notes_mj:"Thorgar parle peu et lentement. Il connaît les gestes mais pas leur sens. Sa frustration est palpable : il sent que quelque chose ne va pas, mais il ne peut pas le relier à un cadre explicite. Jaren est serviable, anxieux, et transmet ses notes à Thade le soir même. Si les PJ accusent Jaren sans preuve, Thorgar les fait expulser par les gardes du Temple."},texte_a_lire:`Le Cimetière des Terrasses descend en gradins sur le flanc de la colline. L'air est froid, plus froid qu'il ne devrait l'être.

Un prêtre nain vous attend près de l'allée centrale. Il porte un tablier de forge sous sa chasuble. « Vous êtes les envoyés de l'Université ? Je suis Thorgar. Je garde ces terrasses. Venez. »`,objectif:"Examiner les tombes profanées, identifier la méthode des prélèvements et évaluer l'étendue des dégâts.",contexte_mj:{situation:"Trois des sept tombes ont été touchées. Les dalles sont intactes mais les fondations ont été percées avec des outils de précision. Jaren Velt prend des notes pour Thade.",secrets:["Les passages ont été creusés avec des ciselets d'Université, pas des outils de vandale.","Jaren travaille pour Thade. Il transmet tout ce que les PJ trouvent.","Le froid près du Mausolée est un signe que le sceau cède. Thorgar le sait mais ne le dit pas aux étrangers."],rappels:["Thorgar ne fait pas confiance aux humains de l'Université. Il accepte les PJ parce que l'ordre est officiel.","Jaren est nerveux. Il a des notes médicales dans une écriture qui n'est pas la sienne."]},defis:[{competence:"Investigation",dd:14,reussite:"Les passages ont été creusés avec des outils de précision — des ciselets d'Université. Quelqu'un qui connaît la pierre a fait ce travail.",echec:"Les tombes ont été forcées par en dessous. Difficile de dire avec quels outils."},{competence:"Médecine",dd:12,reussite:"Les restes prélevés portent des marques de rites funéraires nains très anciens — des runes gravées dans l'os.",echec:"Les ossements manquants étaient anciens. Rien de plus à dire."},{competence:"Diplomatie",dd:13,reussite:"Thorgar accepte de montrer le Mausolée du Seuil. Il ne dit pas pourquoi il est important, mais il les laisse ressentir le froid.",echec:"Thorgar refuse l'accès au Mausolée. « Ce n'est pas pour les étrangers. »"}],indices:[{indice:"Outils d'Université",localisation:"Passages sous les dalles",detection:"Investigation DD 14",information:"Ciselets et marques de forage correspondent à du matériel d'Université.",usage:"Premier lien entre les profanations et l'Université."},{indice:"Runes dans l'os",localisation:"Fragments d'os restants",detection:"Médecine DD 12 ou Connaissances (histoire) DD 14",information:"Les os portent des runes gravées dans le tissu osseux. Ce sont des ancrages rituels.",usage:"Comprendre que les Thanes ne sont pas des fondateurs ordinaires."},{indice:"Le froid du Mausolée",localisation:"Mausolée du Seuil",detection:"Perception passive ou Investigation DD 10",information:"Courant d'air froid. Les lanternes funéraires vacillent.",usage:"Signe que quelque chose d'anormal se passe sous le Cimetière."},{indice:"Les notes de Jaren",localisation:"Carnet de Jaren Velt",detection:"Discrétion DD 12 ou Vol DD 14",information:"Jaren prend des notes dans deux écritures. Certaines pages portent un cachet de Caldris.",usage:"Lien entre Jaren, l'Université et un commanditaire extérieur. Piste vers S-01 et Elian Voss."}],guide_mj:{intention:"Donner les premiers indices tangibles. Les PJ doivent sentir que les profanations ne sont pas ordinaires.",mise_en_place:"Fin d'après-midi. Thorgar attend. Jaren est déjà là, prenant des notes.",deroulement:["Thorgar accueille les PJ et les mène aux tombes profanées.","Les PJ examinent les dalles et les passages creusés.","Jaren observe et prend des notes. Serviable mais nerveux.","Si accès au Mausolée : les PJ ressentent le froid anormal.","Thorgar répond avec des formules rituelles — il connaît les gestes mais pas leur sens."],actions_utiles:["Examiner les outils utilisés.","Parler à Jaren et observer son comportement.","Demander à voir le Mausolée.","Demander ce que signifient les runes sur les os."],fronts_heritiers:["Front 'Le Sceau qui cède' — les PJ ont vu les dégâts de première main.","Front 'Le Plan de Thade' — Jaren est un agent de Thade."],jeu_des_pnj:"Thorgar parle peu et lentement. Jaren est serviable, anxieux, et transmet ses notes à Thade le soir même.",escalade:"Si les PJ accusent sans preuve, Thorgar les fait expulser par les gardes du Temple.",sortie:"Les PJ quittent le Cimetière avec des indices, des questions et peut-être l'amitié prudente de Thorgar."},reperes_de_jeu:{indice_indispensable:"Les PJ doivent comprendre que les profanations ciblent les Thanes et que les outils viennent de l'Université.",ne_pas_bloquer_sur_un_jet:"Même si Investigation échoue, Thorgar dit que trois tombes ont été touchées et les os prélevés.",question_dramatique:"Pourquoi quelqu'un volerait-il les os de fondateurs nains morts depuis des siècles ?"},transitions:{resume:"Les PJ quittent le Cimetière. Jaren se hâte vers l'Université pour faire son rapport.",reussite:"Les PJ ont identifié les outils, ressenti le froid et noté le comportement de Jaren.",echec:"Les PJ rapportent à Thade que le Cimetière a été vandalisé. Thade les envoie enquêter plus profondément."}},{id:"s1_mort_jaren",titre:"La Mort de Jaren Velt",type:"Twist",resume_mj:"Le lendemain ou le surlendemain, Jaren est retrouvé mort dans le couloir du Pavillon Nord. Mort discrète, médicale. Une rune est gravée sur sa nuque. Le parfum de lavande flotte dans l'air.",idLieu:"pavillon_nord_couloir",idsPnj:[],format_livre:{ambiance:`L'aube. Le couloir du troisième étage du Pavillon Nord est éclairé par des lampes alchimiques qui n'ont pas encore été ajustées pour la journée. La lumière est jaune, irrégulière, elle fait des ombres longues. Le couloir sent la lavande — pas le parfum d'un bureau, la concentration d'un masque alchimique.

Jaren Velt est assis contre le mur, près d'une fenêtre. Ses yeux sont ouverts. Son visage est paisible — pas de douleur, pas de surprise. Son carnet est à ses côtés, ouvert à une page blanche. Aucune trace de sang, aucune trace de lutte. Le corps d'un homme en parfaite santé qui s'est arrêté.

Le couloir est silencieux. Les autres étudiants ne sont pas encore levés. Les PJ ont été appelés — par qui ? Un message glissé sous leur porte, un mot anonyme : « Pavillon Nord. Troisième étage. Venez vite. »`,deroulement_narratif:`Les PJ arrivent avant la garde s'ils se dépêchent. C'est crucial : après le passage de la garde, le carnet sera confisqué et la scène sera nettoyée.

Le corps de Jaren est intact. Médecine DD 14 : mort instantanée par arrêt cardiaque. Aucun poison, aucune blessure. Le corps d'un homme en parfaite santé dont le cœur a simplement cessé. La rune est gravée sur sa nuque — petite, précise, faite après la mort ou pendant. Connaissances (mystères) DD 16 : c'est une variante de Dissection à Distance, publiée par Thade Coren il y a six ans. La signature arcanique est identifiable.

Le carnet est ouvert à une page blanche. Investigation DD 13 : les pages écrites ont été arrachées proprement. Quelqu'un a pris les notes après la mort. Les pages arrachées contenaient les notes sur S-01 et le cachet de Caldris. Qui a pris les notes ? Thade ? Elian Voss ? La réponse n'est pas immédiate — c'est une piste pour plus tard.

Le parfum de lavande est le même que dans le bureau de Thade. Perception DD 10. Ce n'est pas une preuve — la lavande est utilisée dans tout l'Université — mais c'est un indice atmosphérique qui relie la scène à Thade dans l'esprit des PJ.

Les PJ doivent décider : rapporter à Thade, cacher le carnet, ou chercher un autre allié. S'ils rapportent à Thade, il exprime sa tristesse avec une conviction parfaite. S'ils cachent le carnet, ils gardent un indice mais s'exposent à des soupçons. S'ils cherchent un autre allié, Olane est la meilleure option — mais ils ne la connaissent pas encore.`,notes_mj:"Cette scène fait basculer la campagne. Jusqu'ici, les PJ étaient des enquêteurs. Maintenant, quelqu'un élimine les témoins gênants. Le ton change : l'enquête devient une course contre un adversaire invisible. Si les PJ accusent Thade ouvertement sans preuve, l'Université les fait taire par procédure. Le MJ doit laisser les PJ formuler leurs soupçons sans les valider ni les infirmer — la vérité viendra plus tard."},texte_a_lire:`On vous trouve à l'aube. Jaren Velt est mort dans le couloir du troisième étage. Assis contre le mur, comme s'il s'était assoupi. Ses yeux sont ouverts. Son carnet est à ses côtés, ouvert à une page blanche. Aucune trace de sang, aucune trace de lutte.

L'air sent la lavande.`,objectif:"Déterminer la cause de la mort, récupérer les notes et décider quoi faire.",contexte_mj:{situation:"Jaren a été tué par Dissection à Distance — une variante publiée par Thade six ans plus tôt. Mort instantanée, médicale. Rune gravée sur la nuque.",secrets:["Thade a fait tuer Jaren parce qu'il posait des questions sur le protocole S-01.","La rune est la signature arcanique de Thade. Connaissances (mystères) DD 16.","Le carnet a été vidé de ses pages écrites. Quelqu'un a pris les notes."],rappels:["Le parfum de lavande est celui du bureau de Thade.","Jaren avait un cachet de Caldris dans ses notes — lien vers Elian Voss."]},defis:[{competence:"Médecine",dd:14,reussite:"Mort instantanée par arrêt cardiaque. Aucun poison, aucune blessure. Le corps d'un homme en parfaite santé qui s'est arrêté.",echec:"Mort naturelle, apparemment. Son cœur a lâché."},{competence:"Connaissances (mystères)",dd:16,reussite:"La rune est une variante de Dissection à Distance, publiée par Thade Coren il y a six ans. Sa signature arcanique.",echec:"Rune arcanique ancienne, difficile à déchiffrer. Ressemble à un glyphe de nécromancie."},{competence:"Investigation",dd:13,reussite:"Les pages écrites du carnet ont été arrachées proprement. Quelqu'un a pris les notes après la mort.",echec:"Le carnet est ouvert à une page blanche. Rien d'écrit."}],indices:[{indice:"La rune sur la nuque",localisation:"Nuque de Jaren",detection:"Connaissances (mystères) DD 16",information:"Variante de Dissection à Distance, publiée par Thade Corem. Signature identifiable.",usage:"Preuve que le meurtrier utilise les techniques de Thade."},{indice:"Le parfum de lavande",localisation:"Couloir du Pavillon Nord",detection:"Perception DD 10",information:"Même parfum que dans le bureau de Thade Coren.",usage:"Indice atmosphérique reliant la scène à Thade."},{indice:"Les pages arrachées",localisation:"Carnet de Jaren",detection:"Investigation DD 13",information:"Pages écrites arrachées après la mort. Les notes sur S-01 et le cachet de Caldris ont été prises.",usage:"Qui a pris les notes ? Thade ? Elian Voss ?"}],guide_mj:{intention:"Faire basculer la campagne. Quelqu'un élimine les témoins gênants.",mise_en_place:"Les PJ sont appelés à l'aube. S'ils arrivent vite, avant la garde. Sinon, le carnet est confisqué.",deroulement:["Les PJ arrivent et examinent le corps.","Médecine pour la cause. Connaissances pour la rune. Investigation pour le carnet.","Les PJ décident : rapporter à Thade, cacher, ou chercher un autre allié."],actions_utiles:["Examiner le corps avant la garde.","Cacher le carnet ou en copier les pages.","Chercher des témoins.","Comparer la rune avec les publications de Thade."],fronts_heritiers:["Front 'Le Plan de Thade' — Thade élimine les témoins.","Front 'Les Factions de la Crise' — la mort attire le Champion."],jeu_des_pnj:"Jaren est mort. Ses notes, contacts et cachet restent. Les PJ peuvent retrouver ses pas.",escalade:"Si les PJ accusent Thade ouvertement sans preuve, l'Université les fait taire par procédure.",sortie:"Les PJ quittent la scène avec un mort, une rune, un parfum et un carnet vide."},reperes_de_jeu:{indice_indispensable:"Les PJ doivent savoir que Jaren est mort, que ce n'est pas naturel et qu'une rune est sur sa nuque.",ne_pas_bloquer_sur_un_jet:"Même si tous les jets échouent, les PJ voient le corps, le carnet vide et sentent la lavande.",question_dramatique:"Qui tue un étudiant sans laisser de trace — et pourquoi sent-on la lavande ?"},transitions:{resume:"Le corps de Jaren sera déclaré 'mort naturelle' par l'Université avant midi.",reussite:"Les PJ ont identifié la rune, le parfum et les pages arrachées. Assez pour soupçonner Thade.",echec:"Les PJ rapportent à Thade que Jaren est décédé. Thade exprime sa tristesse avec une conviction parfaite."}}]},{titre:"Acte II — La Découverte du Verrou",stake:"Les PJ comprennent que les tombes des Thanes sont le verrou de la Spirale et que Thade prélève les ancrages.",location:"Temple-Forgeron, Archives de l'Université, Bureau d'Olane",scenes:[{id:"s1_temple_forgeron",titre:"Le Temple-Forgeron et les Rites Perdus",type:"Révélation",resume_mj:"Les PJ retournent voir Thorgar. S'ils ont gagné sa confiance, il parle des rites d'Edhrek-Murn — les gestes dont le sens s'est perdu. Les rites maintiennent le sceau. Personne ne sait plus pourquoi.",idLieu:"temple_forgeron",idsPnj:["thorgar_pretre_nain"],format_livre:{ambiance:`Le Temple-Forgeron de Moradin est creusé dans la roche sous les Terrasses. On y descend par un escalier en spirale dont les marches sont polies par des siècles de pas nains. L'air vibre du martèlement de l'enclume sacrée — un rythme lent, régulier, qui sert de battement de cœur à la chapelle. Les murs sont couverts de bas-reliefs représentant des nains en posture de prière devant des tombes. Les visages des figures sont usés, effacés par le temps. Les inscriptions qui les accompagnaient sont illisibles.

Thorgar attend dans la chapelle souterraine, debout devant l'enclume. Il porte son tablier de forge. Ses mains sont posées à plat sur le métal, comme s'il puisait quelque chose dans la chaleur résiduelle. Quand les PJ entrent, il ne lève pas la tête immédiatement. Il finit un geste — un geste qui ressemble à une bénédiction mais qui n'en est pas une.`,deroulement_narratif:`Thorgar parle lentement, comme un homme qui déroule quelque chose qu'il n'a jamais formulé à voix haute. Ses maîtres lui ont transmis les gestes d'Edhrek-Murn. Sept gestes, un par Thane. Il les accomplit chaque nuit au Cimetière, sans comprendre ce qu'ils font. Il sait seulement que les nuits où il les accomplit, le froid recule. Les nuits où il ne les accomplit pas, le froid avance.

Diplomatie DD 14 ou Persuasion DD 13 pour qu'il montre les gestes. Il les exécute devant les PJ — des postures de prière naine, mais avec des variations que Thorgar ne peut pas expliquer. Chaque geste correspond à une tombe. Chaque geste inclut le placement d'un fragment d'os — un fragment qui n'est plus là, parce que les profanations les ont pris.

Connaissances (religion) DD 15 : les gestes sont des rites d'ancrage. Les os ne sont pas des restes — ce sont des supports rituels. Les runes dans l'os ne sont pas décoratives, ce sont des points de fixation. Les rites maintiennent le sceau en gardant les ancrages actifs. Sans les os, les rites sont vides. Sans les rites, les os sont inertes. Les deux ensemble maintiennent le verrou.

Thorgar ne connaît pas le mot « Spirale ». Il connaît le froid, les vibrations, le bourdonnement du Mausolée. Il sait que quelque chose remonte d'en-dessous. Il sait que les rites le repoussent. Il ne sait pas ce que c'est. Si les PJ lui disent, il ne réagit pas avec peur — il réagit avec colère. Pas contre les PJ. Contre l'idée que ses maîtres savaient et ne lui ont pas dit.

Si les PJ proposent de restaurer les rites, Thorgar explique ce qu'il faut : les ossements, les gestes complets, et un prêtre qui connaît les sept postures. Il est le seul à connaître les sept postures. Sans lui, les rites meurent.`,notes_mj:"Thorgar est le gardien d'un savoir qu'il ne comprend pas. Sa frustration est le cœur émotionnel de cette scène. Il accomplit des gestes chaque nuit sans savoir pourquoi, et le savoir qu'il protège est en train de s'effondrer sous ses pieds. Si les PJ le traitent avec respect, il devient un allié loyal. S'ils le méprisent ou le pressent, il se ferme et les rites restent un mystère."},texte_a_lire:`Le Temple-Forgeron de Moradin est creusé dans la roche. Le martèlement de l'enclume accompagne les prières. Thorgar vous attend dans la chapelle souterraine, sous la forge.

« Je vais vous dire ce que je sais. Mais je ne sais pas grand-chose. Mes maîtres m'ont transmis les gestes. Pas le sens. Les gestes maintiennent quelque chose. Les gestes oublés laissent quelque chose passer. »`,objectif:"Apprendre ce que Thorgar sait des rites d'Edhrek-Murn et comprendre que les tombes servent à un système actif.",contexte_mj:{situation:"Thorgar connaît les gestes rituels mais pas leur fonction. Il sait que les rites d'Edhrek-Murn accompagnent les morts naines et que les Sept Thanes reçoivent des rites spéciaux. Les rites ont été simplifiés au fil des siècles.",secrets:["Les rites d'Edhrek-Murn maintiennent le sceau. Chaque geste accomplit un ancrage. Chaque geste oublié affaiblit le verrou.","Thorgar sent que quelque chose ne va pas. Le froid au Mausolée l'inquiète. Mais il ne peut pas relier ses sensations à un cadre explicite.","Si les PJ ont vu les runes dans les os, Thorgar peut les identifier comme des runes d'ancrage."],rappels:["Thorgar ne parlera qu'aux PJ qui ont fait preuve de respect au Cimetière.","La chapelle souterraine est un lieu privé. Ce qui s'y dit ne sort pas."]},defis:[{competence:"Diplomatie",dd:14,reussite:"Thorgar montre les gestes d'Edhrek-Murn lentement, en nommant chaque étape. Il ne sait pas ce que chaque geste fait, mais il sait l'ordre et la forme.",echec:"Thorgar parle de rites et de traditions, mais refuse de montrer les gestes à des non-nains."},{competence:"Connaissances (religion)",dd:15,reussite:"Les gestes ressemblent à des rites de fondation, pas des rites funéraires. On les accomplit pour maintenir une fonction que les morts assurent encore.",echec:"Les rites sont anciens et nains. Signification religieuse : honorer les défunts et maintenir la mémoire."}],indices:[{indice:"Les gestes d'Edhrek-Murn",localisation:"Chapelle sous la Forge",detection:"Diplomatie DD 14",information:"Rites de fondation, pas funéraires. Accomplis sur les tombes pour maintenir une fonction que les défunts assurent après la mort.",usage:"Comprendre que les Thanes sont utilisés, pas honorés. Leurs corps sont des ancrages actifs."},{indice:"Les runes dans l'os",localisation:"Comparaison avec les fragments du Cimetière",detection:"Connaissances (religion) DD 15 ou Thorgar",information:"Les runes gravées dans les os correspondent aux runes d'ancrage d'Edhrek-Murn. Les os sont des composants d'un système.",usage:"Relier les profanations au sceau. Qui prend les os prend le verrou."}],guide_mj:{intention:"Révéler que les tombes sont un système fonctionnel, pas un monument.",mise_en_place:"Chapelle souterraine, lieu privé sous la forge. Ambiance intime et sombre.",deroulement:["Thorgar parle des rites, de leur transmission et de leur dégradation.","Si les PJ sont respectueux, il montre les gestes.","Les PJ comparent les gestes avec les runes vues dans les os.","Thorgar avoue qu'il ne comprend pas pourquoi le froid augmente."],actions_utiles:["Demander à voir les gestes complets.","Comparer les runes des os avec les runes des rites.","Demander qui d'autre connaît ces rites.","Proposer de restaurer les rites sur les tombes profanées."],fronts_heritiers:["Front 'Le Sceau qui cède' — les PJ comprennent ce qu'est le sceau.","Front 'La Cité sous pression' — la mémoire perdue est un enjeu direct."],jeu_des_pnj:"Thorgar parle lentement, avec des pauses. Sa frustration de prêtre qui accomplit des gestes sans comprendre est palpable.",escalade:"Si les PJ demandent de restaurer les rites, Thorgar accepte — mais il a besoin des ossements. Et les ossements ont été pris.",sortie:"Les PJ quittent le Temple avec un cadre : les tombes sont un verrou, les rites le maintiennent, les profanations le démontent."},reperes_de_jeu:{indice_indispensable:"Les PJ doivent comprendre que les tombes sont un système d'ancrage actif.",ne_pas_bloquer_sur_un_jet:"Même si Diplomatie échoue, Thorgar dit que les rites existent et que les profanations les brisent.",question_dramatique:"Que se passe-t-il quand une cité oublie pourquoi elle enterre ses fondateurs ?"},transitions:{resume:"Thorgar raccompagne les PJ à la forge. Le bruit de l'enclume reprend.",reussite:"Les PJ ont vu les gestes, compris les runes et identifié le système.",echec:"Thorgar met les PJ sur la piste d'autres détenteurs de savoir : Brogar, les archives."}},{id:"s1_archives_scellees",titre:"Les Archives Médicales Scellées",type:"Investigation",resume_mj:"Les PJ infiltrent ou obtiennent l'accès aux Archives Médicales Scellées. Ils y trouvent le dossier 'Coren, S. — 12-VAEL — Médical' qui révèle le protocole S-01 et son lien avec Sealine.",idLieu:"archives_scellees_universite",idsPnj:[],format_livre:{ambiance:`Les Archives Médicales Scellées occupent un sous-sol bas et voûté du Pavillon Sud de l'Université. On y accède par un escalier de service que les étudiants ignorent. L'air est sec, froid, saturé de l'odeur de cuir et de produits de conservation. Des armoires métalliques alignées par décennie, étiquetées au pochoir. Une lampe alchimique bourdonne au plafond, projetant une lumière blafarde qui ne rend justice à aucune couleur.

Le registre des scellés est un cahier relié cuir, posé sur un pupitre à l'entrée. Les pages sont jaunies, l'écriture est celle d'un archiviste méthodique. Les entrées récentes sont rares — l'Université ne scelle plus beaucoup de dossiers. Les entrées de l'année de la catastrophe de Nyx sont nombreuses. L'une d'elles porte la mention : « Coren, S. — 12-VAEL — Médical — Scellé par ordre du Recteur. »`,deroulement_narratif:`Les PJ peuvent obtenir l'accès de trois façons : par Olane (s'ils l'ont déjà rencontrée), par Crochetage DD 15 sur la porte du sous-sol, ou par Discrétion DD 14 pour entrer par le réseau de service. Une fois à l'intérieur, le registre est accessible sans jet.

Le dossier de Sealine est dans l'armoire de la décennie correspondante. Il est scellé par un sigil mineur — pas un sort de combat, juste un verrou arcanique. Connaissances (mystères) DD 12 ou Crochetage DD 13 pour l'ouvrir. Le sigil est de conception standard, pas la signature de Thade.

Le dossier contient des notes médicales, des relevés de symptômes, et un document séparé : le protocole S-01. Médecine DD 15 pour comprendre les notes médicales : Sealine présentait des symptômes d'exposition planaire chronique — fatigue, vertiges, perceptions augmentées, sensibilité au froid. Le protocole S-01 est établi 28 jours avant la catastrophe de Nyx. Il porte la mention « littérature interdite » et « approche expérimentale ».

Le nom S-01 n'est pas expliqué dans le dossier. Mais les PJ peuvent déduire : S pour Sealine, 01 pour premier patient. Le protocole décrit une méthode pour « stabiliser l'ancrage d'un sujet exposé à des flux planaires continus ». Le langage est clinique, détaché, mais l'auteur est clairement Thade — la signature arcanique sur le document correspond à celle de ses publications.

Si les PJ ont vu la rune sur la nuque de Jaren, ils peuvent faire le lien : Thade a exploré la littérature interdite avant Nyx. Nyx n'était pas un accident — c'était une tentative de sauver Sealine qui a mal tourné. Le protocole S-01 est le point d'origine de tout.

Olane peut confirmer si les PJ lui apportent le dossier. Elle dira : « Il n'a jamais cessé. Huit ans. Il n'a jamais cessé de chercher. »`,notes_mj:"Le dossier S-01 est la révélation qui transforme Thade d'antagoniste abstrait en antagoniste tragique. Les PJ comprennent que tout ce qu'il fait — les profanations, la manipulation, le mensonge par omission — est motivé par l'amour pour Sealine et la culpabilité de Nyx. Cette compréhension ne l'excuse pas, mais elle complique le choix des PJ pour la suite."},texte_a_lire:`Les Archives Médicales Scellées occupent un sous-sol bas et voûté. Des armoires métalliques alignées par décennie. Une lampe alchimique bourdonne au plafond.

Le registre indique : « Coren, S. — 12-VAEL — Médical — Scellé par ordre du Recteur, année de la catastrophe de Nyx. »`,objectif:"Trouver le dossier médical de Sealine Vael (inscrit sous Coren, S.) et comprendre ce qu'est le protocole S-01.",contexte_mj:{situation:"Les archives sont accessibles aux Maîtres et aux enquêteurs mandatés. L'ordre de Thade donne accès, mais le dossier de Sealine est scellé par le Recteur. Investigation ou Effraction pour le consulter.",secrets:["Le dossier contient les notes de Thade sur la maladie de Sealine, puis le protocole S-01. Dernière entrée : 'Méthodes conventionnelles épuisées. Explorer la littérature interdite.' Plus tard : 'S-01 : protocole établi. Premier essai dans 28 jours.'","S-01 = Sealine. Le protocole porte le nom de la patiente.","Le dossier a été scellé par le Recteur, pas par Thade. Thade n'en a pas besoin — il a tout dans ses cahiers personnels."],rappels:["Si les PJ ont vu le cachet de Caldris chez Jaren, ils peuvent relier S-01, Elian Voss et Caldris.","Effraction DD 12 pour entrer de nuit sans autorisation."]},defis:[{competence:"Investigation",dd:12,reussite:"Le dossier est dans l'armoire, derrière un sceau administratif ancien, facile à briser.",echec:"Le dossier est introuvable. Peut-être déplacé. Les PJ doivent chercher ailleurs."},{competence:"Médecine",dd:15,reussite:"La chronologie raconte une histoire : Sealine malade, Thade cherchant un remède, méthodes échouant, puis S-01 apparaît. Le protocole n'est pas un traitement — c'est un rituel.",echec:"Notes médicales techniques. La maladie est réelle, mais S-01 n'est pas clair."}],indices:[{indice:"Le protocole S-01",localisation:"Dossier médical de Sealine, dernière page",detection:"Médecine DD 15 ou Investigation DD 12",information:"S-01 = Sealine. Protocole établi 28 jours avant la catastrophe de Nyx.",usage:"La catastrophe n'était pas un accident — c'était une tentative de sauver Sealine qui a mal tourné."},{indice:"La littérature interdite",localisation:"Note de Thade dans le dossier",detection:"Lecture directe",information:"'Méthodes conventionnelles épuisées. Explorer la littérature interdite.' Note antérieure à la catastrophe.",usage:"Thade n'a pas dérapé par accident — il a choisi de franchir la ligne."}],guide_mj:{intention:"Révéler le lien entre Thade, Sealine et la catastrophe de Nyx.",mise_en_place:"Archives de jour (ordre de mission) ou de nuit (effraction). Silencieux, poussiéreux.",deroulement:["Localiser le dossier dans les armoires.","Briser le sceau et lire le contenu.","Médecine pour la chronologie.","La dernière page révèle S-01 et la littérature interdite."],actions_utiles:["Copier ou mémoriser le dossier.","Chercher d'autres dossiers scellés de la même époque.","Vérifier qui a demandé le scellement.","Comparer S-01 avec le cachet de Caldris."],fronts_heritiers:["Front 'Le Plan de Thade' — Thade cherche à rouvrir le seuil pour Sealine.","Front 'Les Factions de la Crise' — le cachet mène à Elian Voss et Maelric."],jeu_des_pnj:"Aucun PNJ. Les archives parlent par elles-mêmes.",escalade:"Si les PJ sont surpris de nuit, l'Université ouvre une procédure. Olane peut couvrir.",sortie:"Les PJ quittent les archives avec le nom de Sealine, le protocole S-01 et la certitude que Nyx n'était pas un accident."},reperes_de_jeu:{indice_indispensable:"Les PJ doivent savoir que S-01 = Sealine et que Thade a établi ce protocole avant Nyx.",ne_pas_bloquer_sur_un_jet:"Le nom 'S-01' et la référence à la 'littérature interdite' sont lisibles sans compétence médicale.",question_dramatique:"Jusqu'où irait un homme brillant pour sauver la personne qu'il aime ?"},transitions:{resume:"Les PJ referment le dossier et quittent les archives.",reussite:"Les PJ ont le protocole S-01, le nom de Sealine et le motif de Thade.",echec:"Les PJ ont trouvé un dossier scellé sans le déchiffrer. Olane peut les aider."}},{id:"s1_bureau_olane",titre:"Le Bureau d'Olane",type:"Social",resume_mj:"Les PJ rencontrent Maëra Olane. Elle se doute de quelque chose depuis longtemps. Si les PJ viennent avec les indices des archives, elle s'ouvre et devient leur alliée.",idLieu:"salle_4b",idsPnj:["maera_olane"],format_livre:{ambiance:`Le bureau d'Olane est à l'opposé de celui de Thade. Petit, modeste, encombré de dossiers annotés et de tasses de café d'orge vides. Les murs sont couverts de graphiques, de cartes de flux arcaniques, de notes manuscrites reliées par des fils de laine. Une fenêtre étroite donne sur la cour intérieure de l'Université, pas sur la Tour. Le bureau est en désordre organisé — Olane sait où est chaque chose, mais personne d'autre ne le saurait.

Olane est assise derrière son bureau, un stylo dans une main, une tasse fumante dans l'autre. Elle est petite, nerveuse, les cheveux tirés en arrière. Des cernes profondes. Le regard de quelqu'un qui n'a pas dormi depuis des semaines — pas par insomnie, par inquiétude. Elle porte les vêtements d'un fonctionnaire de l'Université, mais le regard d'une femme qui ne croit plus en l'institution qu'elle sert.`,deroulement_narratif:`Olane ne perd pas de temps. Si les PJ viennent avec des indices — la rune de Jaren, le dossier S-01, les outils d'Université — elle les écoute, elle vérifie, puis elle s'ouvre. Si les PJ viennent sans preuve, elle reste prudente : elle pose des questions, elle teste leur sérieux, elle ne révèle rien sans contrepartie.

Ce qu'Olane sait : les flux arcaniques de l'Université sont détournés. Pas par un étudiant, pas par un membre du Conseil. Par quelqu'un qui a un accès de haut niveau. Les relevés montrent une déviation vers la Tour Arcanique. Elle a essayé d'alerter le Conseil. Le Conseil a classé sa note comme « préoccupation technique ». Elle a essayé d'alerter le Recteur. Le Recteur lui a dit de se concentrer sur son travail.

Si les PJ lui montrent le dossier S-01, Olane fait le lien. Elle dit : « Il n'a jamais cessé. Huit ans. Il n'a jamais cessé de chercher. » Elle ne dit pas le nom de Thade immédiatement — elle laisse les PJ le déduire. Puis elle confirme.

Olane offre ce qu'elle peut : un accès institutionnel, une couverture légale, des données sur les flux. Elle ne peut pas affronter Thade publiquement — elle n'a pas de preuve directe, seulement des indices. Mais elle peut protéger les PJ s'ils agissent discrètement. Elle peut ralentir les procédures. Elle peut acheter du temps.

Si les PJ la protègent — en gardant son nom hors de leurs rapports, en ne révélant pas leur source — elle devient une alliée durable. S'ils la compromettent, Thade la fait muter ou réduire au silence en moins d'une semaine.`,notes_mj:"Olane est le pont entre l'institution et la vérité. Sans elle, les PJ sont seuls contre l'Université. Avec elle, ils ont un pied dans le système. Le MJ doit jouer Olane comme une femme fatiguée mais lucide — pas une héroïne, pas une victime, mais une fonctionnaire qui a choisi son camp en silence depuis des mois."},texte_a_lire:`Le bureau d'Olane est petit, modeste, encombré de dossiers annotés. Une tasse de café d'orge fume sur le coin du bureau.

« Je sais pourquoi vous êtes là. Vous avez trouvé quelque chose. Ou vous soupçonnez quelque chose. Dans les deux cas, je veux l'entendre. »`,objectif:"Gagner la confiance d'Olane, partager les indices et obtenir son aide.",contexte_mj:{situation:"Olane est rectrice et conseillère. Elle a remarqué les anomalies, les salles scellées, le comportement de Thade. Mais l'Université fait confiance à son membre le plus brillant. Olane est isolée.",secrets:["Olane a essayé de lancer une enquête interne. L'Université l'a enterrée par procédure.","Elle sait que les flux arcaniques sont détournés vers la Tour. Elle a les chiffres mais pas les preuves publiques.","Olane ne sait pas ce qu'est S-01. Si les PJ lui montrent le dossier, elle fait le lien en quelques secondes."],rappels:["Olane est un allié institutionnel, pas une combattante. Elle fournit accès, données et couverture légale.","Si les PJ n'ont aucun indice, Olane ne s'ouvre pas. Trop à perdre."]},defis:[{competence:"Diplomatie",dd:14,reussite:"Olane partage ses soupçons : flux détournés vers la Tour, salles scellées, Thade a restreint ses accès.",echec:"Olane reste prudente. 'Anomalies temporaires.' Elle ne confirme rien."},{competence:"Persuasion",dd:15,reussite:"Si les PJ montrent le dossier S-01, Olane le lit en silence puis dit : 'Il n'a jamais renoncé. Huit ans.' Elle devient une alliée déterminée.",echec:"Olane lit le dossier avec gravité mais demande du temps pour vérifier. Elle ne s'engage pas immédiatement."}],indices:[{indice:"Les flux détournés",localisation:"Chiffres d'Olane",detection:"Diplomatie DD 14",information:"Flux arcaniques de plusieurs bâtiments détournés vers la Tour. Salles scellées = zones de prélèvement.",usage:"La Tour devient un dispositif actif, pas juste un bâtiment de recherche."},{indice:"L'isolement d'Olane",localisation:"Conversation",detection:"Perception DD 10",information:"Olane n'a plus accès à ses données. Ses collègues l'évitent. L'Université a enterré son enquête.",usage:"Thade ne tue pas tous ceux qui le gênent — il les neutralise institutionnellement."}],guide_mj:{intention:"Transformer Olane en alliée. Premier PNJ institutionnel qui aide de l'intérieur.",mise_en_place:"Olane reçoit les PJ dans son bureau, ferme la porte à clé. Confidentiel.",deroulement:["Olane demande ce que les PJ ont trouvé.","Si les PJ partagent, elle partage ses propres indices.","Si les PJ montrent S-01, elle fait le lien avec Thade et Nyx.","Olane propose son aide : accès, couverture, contacts au Conseil."],actions_utiles:["Partager les indices des archives.","Demander ce qu'elle sait sur la Tour.","Demander une couverture institutionnelle.","Proposer de rassembler des preuves publiques."],fronts_heritiers:["Front 'Le Plan de Thade' — Olane est un obstacle pour Thade.","Front 'La Cité sous pression' — Olane est le pont entre l'Université et le Conseil."],jeu_des_pnj:"Olane parle bas, vite, avec précision. Elle a peur pour l'Université, pas pour elle.",escalade:"Si les PJ mettent Olane en danger, Thade accélère son isolement. Les PJ doivent la protéger.",sortie:"Olane murmure : 'La Tour. Regardez la Tour.'"},reperes_de_jeu:{indice_indispensable:"Les PJ doivent savoir qu'Olane peut être une alliée si on lui apporte des preuves.",ne_pas_bloquer_sur_un_jet:"Même si Diplomatie échoue, Olane dit que les flux sont anormaux et ses accès restreints.",question_dramatique:"Que fait un homme brillant quand une institution entière lui fait confiance aveuglément ?"},transitions:{resume:"Olane raccompagne les PJ. Avant de les laisser partir : 'La Tour. Regardez la Tour.'",reussite:"Les PJ ont une alliée, des données et un objectif : la Tour Arcanique.",echec:"Les PJ ont rencontré Olane sans obtenir sa confiance. Ils doivent trouver d'autres alliés."}}]},{titre:"Acte III — Le Tournant",stake:"Les PJ doivent choisir : servir Thade, le confronter, ou chercher la vérité ailleurs.",location:"Cimetière des Terrasses, Vieille Ville",scenes:[{id:"s1_retour_cimetiere",titre:"Le Retour au Cimetière",type:"Exploration",resume_mj:"Les PJ retournent au Cimetière de nuit. De nouvelles tombes ont été profanées. Cinq des sept Thanes sont touchés. Le Mausolée vibre. Le Puits de l'Abîme pulse d'un froid planaire.",idLieu:"mausolee_seuil",idsPnj:["thorgar_pretre_nain"],format_livre:{ambiance:`Le Cimetière des Terrasses à la nuit tombée n'est plus le même lieu. Les lanternes funéraires vacillent sans vent — certaines sont éteintes, et les terrasses où elles manquent sont plongées dans une obscurité que les torches peinent à percer. Le froid a gagné. On voit sa souffle à chaque respiration. Les gradins de pierre sont couverts de givre par endroits, comme si le froid remontait non pas de l'air, mais de la pierre elle-même.

Le Mausolée du Seuil est au centre, bas et sombre. La dalle centrale vibre — pas un tremblement, une pulsation lente, régulière, comme un cœur qui bat dans la fondation. Le bourdonnement du Puits de l'Abîme est audible à vingt mètres. Il n'est pas fort, mais il est partout. Il passe par les pieds, par les os, par les dents.

Thorgar attend au Mausolée. Il est épuisé. Les cernes d'un homme qui n'a pas dormi depuis des nuits. Il accomplit les rites chaque nuit, mais les gestes sont vides — les os ne sont plus là. Il dit : « C'est pire. Les runes changent. Les lanternes s'éteignent. Et le son... écoutez. »`,deroulement_narratif:`Cinq des sept tombes sont touchées. Les deux dernières — T-06 et T-07 — sont intactes mais les passages creusés par en-dessous se rapprochent. Investigation DD 13 pour évaluer le rythme : un ou deux jours avant que les deux dernières tombes soient atteintes.

Le Mausolée vibre. Perception DD 10 pour sentir la pulsation. Le Puits de l'Abîme pulse d'un froid planaire — le froid n'est plus naturel, il porte une texture, une épaisseur, comme si l'air était partiellement solide. Connaissances (mystères) DD 14 : c'est une empreinte planaire. La Spirale filtre. Pas une invasion, pas une rupture — une filtration lente, comme de l'eau qui s'infiltre par les fissures.

Thorgar montre les runes qui changent. Sur les tombes touchées, les runes d'ancrage se transforment — elles ne disparaissent pas, elles se réécrivent. Le nouveau motif est inconnu de Thorgar. Connaissances (mystères) DD 16 : les nouvelles runes sont des runes d'ouverture, pas d'ancrage. Quelqu'un ne se contente pas de briser le sceau — il le remplace par un autre système.

Si les PJ proposent de protéger les deux dernières tombes, Thorgar explique ce qu'il faut : une garde permanente, la restauration des rites complets (qui nécessite les ossements), et un moyen de bloquer les passages par en-dessous. Les PJ peuvent se poster en sentinelles, mais le temps joue contre eux.

Si les PJ interceptent des profanateurs sur place — voir la scène optionnelle « Interception de profanateurs ».`,notes_mj:"Cette scène doit transmettre l'urgence. Le sceau n'est plus une abstraction — il est en train de céder sous les pieds des PJ. Le bourdonnement, le froid, les runes qui changent : tout est sensoriel, tout est immédiat. Les PJ doivent sentir que chaque jour compte. Le MJ peut faire avancer l'horloge du front « Le Sceau qui cède » d'un segment pendant cette scène pour souligner la pression."},texte_a_lire:`Le Cimetière est silencieux à la nuit tombée. Les lanternes funéraires vacillent sans vent. Le froid gagne les gradins, les allées, les marches. Vous voyez votre souffle.

Thorgar vous attend au Mausolée. « C'est pire. Les runes changent. Les lanternes s'éteignent. Et le son... écoutez. »

Un bourdonnement sourd remonte de la dalle centrale.`,objectif:"Évaluer l'état du sceau, identifier les nouvelles profanations et comprendre que le verrou cède.",contexte_mj:{situation:"Cinq des sept tombes sont touchées. Le sceau ne tient plus que par deux ancrages. Le Puits de l'Abîme vibre — un bourdonnement sourd remonte des profondeurs.",secrets:["Le bourdonnement est la Spirale qui presse le sceau. Plus le sceau cède, plus la Spirale filtre.","Si les PJ descendent dans le Puits, ils sentent un froid planaire. Connaissances (mystères) DD 14 pour identifier une empreinte planaire.","Thorgar accomplit les rites incomplets chaque nuit. Sans les ossements, les rites ne restaurent pas l'ancrage."],rappels:["Les PJ peuvent croiser des agents de Thade ou des Endeuillés d'Edran Morn au Cimetière la nuit.","Si les PJ ont restauré des rites avec Thorgar, le MJ retire un segment de l'horloge du Front 'Le Sceau qui cède'."]},defis:[{competence:"Investigation",dd:14,reussite:"Cinq des sept tombes sont touchées. Les passages sont plus larges, plus récents. Toujours des outils d'Université.",echec:"Plus de tombes profanées. Difficile de dire combien dans l'obscurité."},{competence:"Connaissances (mystères)",dd:14,reussite:"Le bourdonnement est une empreinte planaire. La Spirale presse le sceau. Une force ancienne qui cherche à revenir.",echec:"Bourdonnement étrange et inquiétant. Peut-être un écho des anciens rites."},{competence:"Athlétisme",dd:12,reussite:"Les PJ descendent dans le Puits. Le froid augmente. À mi-chemin, un courant d'air planaire remonte des profondeurs.",echec:"La descente est trop difficile sans équipement. Les encoches sont trop éloignées."}],indices:[{indice:"Cinq tombes sur sept",localisation:"Terrasses des Sept Thanes",detection:"Investigation DD 14",information:"Le sceau ne tient plus que par deux ancrages. Le verrou est proche de la rupture.",usage:"Urgence : si les deux dernières tombes tombent, le sceau cède entièrement."},{indice:"L'empreinte planaire",localisation:"Puits de l'Abîme",detection:"Connaissances (mystères) DD 14",information:"La Spirale n'envahit pas — elle filtre, lentement, par les fissures du verrou.",usage:"Comprendre la nature de la menace : pas une armée, une pression constante."}],guide_mj:{intention:"Faire sentir l'urgence. Le sceau cède. Les PJ doivent agir maintenant.",mise_en_place:"Nuit. Cimetière silencieux. Thorgar attend. Le froid et le bourdonnement font le travail atmosphérique.",deroulement:["Thorgar mène les PJ aux nouvelles profanations.","Les PJ examinent les tombes et constatent l'ampleur.","Ils entrent dans le Mausolée et entendent le bourdonnement.","S'ils descendent dans le Puits, ils sentent la Spirale.","Thorgar demande de l'aide : il faut les ossements pour restaurer les rites."],actions_utiles:["Compter les tombes touchées et évaluer l'état du sceau.","Descendre dans le Puits de l'Abîme.","Proposer à Thorgar de protéger les deux dernières tombes.","Demander où les ossements pourraient avoir été emmenés."],fronts_heritiers:["Front 'Le Sceau qui cède' — l'horloge est à l'étape 3 ou 4.","Front 'Le Plan de Thade' — les ossements convergent vers la Tour."],jeu_des_pnj:"Thorgar est épuisé, inquiet, mais déterminé. Il accomplit les rites incomplets chaque nuit.",escalade:"Si les PJ rencontrent des agents de Thade ou des Endeuillés, la scène devient un conflit.",sortie:"Les PJ quittent le Cimetière avec une certitude : le sceau cède, le temps presse."},reperes_de_jeu:{indice_indispensable:"Les PJ doivent comprendre que cinq tombes sur sept sont touchées et que le sceau est proche de la rupture.",ne_pas_bloquer_sur_un_jet:"Même si Investigation échoue, Thorgar dit que de nouvelles tombes ont été touchées et que le bourdonnement augmente.",question_dramatique:"Combien de temps avant que les deux derniers ancrages cèdent ?"},transitions:{resume:"Les PJ quittent le Cimetière. Le bourdonnement les suit jusqu'à la porte.",reussite:"Les PJ ont mesuré l'urgence. La prochaine étape : retrouver les ossements ou confronter Thade.",echec:"Les PJ ont senti le froid sans comprendre. Thorgar les met sur la piste de la Tour ou des égouts."}},{id:"s1_rencontre_resistance",titre:"La Rencontre avec la Résistance",type:"Rencontre",resume_mj:"Les PJ découvrent la Résistance de la Vieille Ville — Mara, Ursula, le Collecteur et Sniv. Un réseau clandestin qui soigne les malades, cache les fugitifs et cherche la vérité sur Thade. Ils offrent aux PJ une alternative à l'Université.",idLieu:"maison_des_retours",idsPnj:["mara_dirigeante","ursula_fraternite","le_collecteur","sniv_kobold"],format_livre:{ambiance:`La Maison des Retours est cachée derrière une blanchisserie de la Vieille Ville. On y accède par une cour étroite, puis par un escalier qui descend sous le niveau de la rue. L'intérieur sent le savon, la soupe et la cire à briquet. Des lits alignés contre les murs, séparés par des rideaux faits de vieux draps. Des malades — pas des blessés, des malades. Les symptômes varient : fatigue, tremblements, perceptions augmentées, sensibilité au froid. Les mêmes symptômes que Sealine, huit ans plus tôt.

Mara attend au centre de la pièce, debout, les bras croisés. Elle est grande, mince, les cheveux courts. Le regard fatigué mais net d'une femme qui a choisi son camp il y a longtemps et qui n'en a jamais changé. Elle porte les vêtements d'une travailleuse de la Vieille Ville — pas une rebelle, pas une soldate, une femme qui soigne et qui cache.

Ursula est près d'un lit, en train de changer un pansement. Le Collecteur est dans un coin, assis sur une caisse, un carnet sur les genoux. Sniv est invisible — un kobold qui se fond dans les ombres, mais dont les yeux brillent dans la pénombre.`,deroulement_narratif:`Mara accueille les PJ avec une question : « Vous êtes les envoyés de l'Université ? Ou les envoyés de quelqu'un d'autre ? » La réponse détermine le ton de la conversation. Si les PJ disent qu'ils travaillent pour Thade, Mara ne les chasse pas — elle leur offre un repas et dit : « Mangez. Vous avez faim. Et pendant que vous mangez, écoutez. »

Mara explique ce qu'elle sait. La Résistance existe depuis la catastrophe de Nyx. Elle a commencé comme un réseau de soins — des soigneurs qui traitaient les malades que l'Université refusait. Puis elle est devenue un réseau d'information. Mara cherche la vérité sur Nyx depuis huit ans. Elle ne sait pas tout, mais elle sait que Thade n'a jamais accepté la mort de Sealine.

Le Collecteur intervient si les PJ demandent des preuves. Il ouvre son carnet : des caisses d'os circulent dans les égouts. Elles portent un cachet de Caldris et un marquage d'Université. Elles convergent vers la Tour Arcanique par un réseau de passages sous les Terrasses. Renseignements DD 14 ou Diplomatie DD 13 pour qu'il donne les détails : les caisses passent la nuit, transportées par des agents que personne ne reconnaît.

Sniv propose de montrer les passages. Il parle peu, mais il connaît les égouts mieux que personne. Il a trouvé des passages récents — creusés dans la roche, pas dans la terre, avec des outils de précision. Les mêmes outils qu'au Cimetière.

Ursula parle des malades. Elle dit : « Ce ne sont pas des malades ordinaires. Leurs symptômes ressemblent à ceux de l'année de Nyx. L'Université les ignore. Nous les soignons. » Si les PJ ont lu le dossier S-01, ils font le lien : les symptômes de Sealine, les symptômes des malades de la Vieille Ville, les symptômes de l'exposition planaire chronique.

Mara ne demande pas aux PJ de trahir Thade immédiatement. Elle dit : « Vous n'avez pas à choisir maintenant. Mais sachez que l'Université ne vous donnera pas la vérité. Nous, oui. »`,notes_mj:"La Résistance n'est pas un groupe de rebelles romantiques. C'est un réseau de survie — des gens qui soignent, qui cachent, qui observent. Mara n'est pas une chef de guerre, c'est une organisatrice. Le Collecteur n'est pas un espion, c'est un récupérateur d'informations. Sniv n'est pas un scout, c'est un kobold qui connaît les tunnels. Chacun a un rôle, aucun n'est interchangeable. Le MJ doit jouer la Résistance comme une alternative crédible à l'Université — pas meilleure, différente."},texte_a_lire:`La Maison des Retours est cachée derrière une blanchisserie de la Vieille Ville. Des lits alignés contre les murs, séparés par des rideaux faits de vieux draps. L'air sent le savon, la soupe et la cire à briquet.

Une femme au regard fatigué mais net vous accueille. « Mara. Vous êtes les envoyés de l'Université ? Ou les envoyés de quelqu'un d'autre ? Dans les deux cas, asseyez-vous. Nous avons des choses à dire. »`,objectif:"Rencontrer la Résistance, comprendre leur rôle et décider si les PJ s'allient avec eux.",contexte_mj:{situation:"La Résistance est un réseau clandestin : Mara dirige, Ursula soigne, le Collecteur renseigne, Sniv explore les égouts. Ils cachent les malades, les fugitifs et ceux que Thade a rendus invisibles. Ils savent que Thade est dangereux mais n'ont pas les preuves ni le pouvoir institutionnel pour agir.",secrets:["Mara a perdu des gens dans la catastrophe de Nyx. Elle cherche la vérité depuis huit ans.","Le Collecteur a des contacts dans les égouts et dans la pègre. Il sait que des fragments d'os circulent dans les réseaux clandestins — mais il ne sait pas d'où ils viennent.","Sniv a exploré les égouts sous les Terrasses et a trouvé des passages récemment creusés entre le Cimetière et la Vieille Ville."],rappels:["La Résistance ne fait pas confiance à l'Université. Si les PJ se présentent comme envoyés de Thade, ils seront éconduits.","Si les PJ ont des indices (S-01, runes, cachet de Caldris), la Résistance peut les recouper avec ses propres informations."]},defis:[{competence:"Diplomatie",dd:13,reussite:"Mara accepte de partager ce que la Résistance sait : des passages creusés sous le Cimetière, des fragments d'os qui circulent, des malades que l'Université refuse de soigner.",echec:"Mara reste méfiante. Elle offre un repas mais ne partage aucune information. « Revenez quand vous saurez de quel côté vous êtes. »"},{competence:"Renseignements",dd:14,reussite:"Le Collecteur confirme que des fragments d'os ont été vus dans les égouts, transportés par des hommes de main de la pègre vers un destinataire inconnu. Le cachet de Caldris apparaît sur certaines caisses.",echec:"Le Collecteur a entendu des rumeurs sur des mouvements dans les égouts, mais rien de précis."}],indices:[{indice:"Les passages des égouts",localisation:"Témoignage de Sniv",detection:"Diplomatie DD 13 ou Discrétion DD 12",information:"Des passages récents relient le Cimetière aux égouts de la Vieille Ville. Quelqu'un transporte des ossements par ce réseau.",usage:"Piste concrète pour suivre les ossements depuis le Cimetière jusqu'à leur destinataire."},{indice:"Le cachet de Caldris dans les égouts",localisation:"Témoignage du Collecteur",detection:"Renseignements DD 14",information:"Des caisses marquées du cachet de Caldris circulent dans les égouts. Elles contiennent des fragments d'os.",usage:"Relier les ossements des Thanes au protocole S-01 et à Elian Voss via Caldris."}],guide_mj:{intention:"Offrir aux PJ une alternative à l'Université. La Résistance donne accès aux égouts, à la pègre et aux malades — des pistes que l'Université ne peut pas fournir.",mise_en_place:"Les PJ sont amenés à la Maison des Retours par un contact (Ursula, Tibbet, ou un malade qu'ils ont aidé). Ambiance chaleureuse mais tendue.",deroulement:["Mara accueille les PJ et leur demande de quel côté ils sont.","Si les PJ partagent leurs indices, Mara partage les siens.","Le Collecteur parle des caisses dans les égouts.","Sniv propose de montrer les passages creusés sous le Cimetière."],actions_utiles:["Partager les indices avec Mara.","Demander au Collecteur ce qu'il sait des caisses de Caldris.","Demander à Sniv de guider les PJ dans les égouts.","Proposer une alliance entre les PJ et la Résistance."],fronts_heritiers:["Front 'Les Factions de la Crise' — la Résistance est un acteur de la crise.","Front 'Le Plan de Thade' — les égouts sont le chemin des ossements."],jeu_des_pnj:"Mara parle bas, avec l'autorité de quelqu'un qui a perdu et qui ne lâche pas. Le Collecteur est précis, transactionnel. Sniv est excité, nerveux, intelligent.",escalade:"Si les PJ trahissent la Résistance à Thade, Mara disparaît. Le réseau se replie. Les PJ perdent accès aux égouts et à la pègre.",sortie:"Les PJ quittent la Maison des Retours avec un guide (Sniv), une piste (les égouts) et un choix : allié de la Résistance ou agent de Thade."},reperes_de_jeu:{indice_indispensable:"Les PJ doivent savoir que la Résistance existe et qu'elle a des informations sur les ossements.",ne_pas_bloquer_sur_un_jet:"Même si Diplomatie échoue, Mara offre un repas et dit que la Résistance existe. Les PJ peuvent revenir.",question_dramatique:"De quel côté êtes-vous ?"},transitions:{resume:"Les PJ quittent la Maison des Retours. Sniv les attend à la sortie, prêt à les guider dans les égouts.",reussite:"Les PJ ont un guide, une piste et un allié. Ils peuvent maintenant suivre les ossements depuis le Cimetière jusqu'à leur destinataire.",echec:"Les PJ ont rencontré la Résistance sans obtenir sa confiance. Ils savent que le réseau existe mais n'ont pas accès à ses ressources."}},{id:"s1_choix",titre:"Le Choix",type:"Dilemme",resume_mj:"Les PJ ont assez d'indices pour comprendre : Thade prélève les ossements des Thanes pour ouvrir le seuil de la Spirale. Il le fait pour Sealine. Le sceau cède. Ils doivent choisir : rapporter leurs découvertes à Thade, le confronter, ou rejoindre la Résistance et protéger le sceau. Ce choix définit la suite de la campagne.",idLieu:"qg_resistance",idsPnj:["mara_dirigeante","thorgar_pretre_nain"],format_livre:{ambiance:`L'ancienne salle de filtration sous les égouts des Terrasses est sèche, voûtée, silencieuse. Un espace qui n'appartient ni à l'Université ni à la Résistance — un lieu neutre, choisi pour cette rencontre. La voûte est basse, les murs sont couverts de tuyaux rouillés qui ne servent plus. Une table de pierre occupe le centre. Deux chaises de chaque côté. Une lampe alchimique pose sur la table, projetant une lumière stable pour la première fois depuis des jours.

Mara et Thorgar se font face de chaque côté de la table. C'est la première fois qu'ils se rencontrent. Mara porte les vêtements de la Vieille Ville. Thorgar porte son tablier de forge. Ils n'ont rien en commun sauf ce qu'ils savent. Et ce qu'ils savent, c'est que le sceau cède et que quelqu'un doit agir.

Les PJ entrent. La salle se tait. Tout le monde regarde les PJ. Parce que les PJ sont les seuls qui ont vu à la fois l'intérieur de l'Université et l'intérieur de la Résistance. Les seuls qui ont les preuves. Les seuls qui peuvent choisir.`,deroulement_narratif:`Mara parle la première : « Nous savons maintenant. Thade prend les os. Thade ouvre le seuil. La question est : qu'allez-vous faire ? »

Thorgar prend le relais : « Les rites peuvent encore être restaurés. Si nous récupérons les os. Si nous protégeons les deux dernières tombes. Mais si vous choisissez le mauvais côté, tout est perdu. »

Les PJ ont trois options principales :

1. Rapporter à Thade. Les PJ retournent à l'Université et remettent leurs découvertes. Thade les remercie, confirme que les profanations sont l'œuvre de vandales ou d'un culte, et leur demande de protéger les deux dernières tombes. En réalité, il accélère ses prélèvements. Les PJ restent ses outils. Cette voie mène au Scénario 2 avec un retard critique et une compréhension incomplète.

2. Confronter Thade. Les PJ vont voir Thade et lui présentent ce qu'ils savent. Thade ne nie pas. Il explique. Il parle de Sealine, de Nyx, de la littérature interdite, de l'amour qui a tout détruit. Il demande aux PJ de l'aider — pas par mensonge, par vérité. Il dit : « Je peux refermer le seuil. Je peux sauver Valombre. Mais il me faut les os. » Cette voie mène à un dilemme moral direct et à une confrontation qui peut être violente ou négociée.

3. Rejoindre la Résistance. Les PJ choisissent de protéger le sceau avec Thorgar et la Résistance. Ils coupent les ponts avec l'Université. Thade devient un adversaire actif. Cette voie mène au Scénario 2 avec la Résistance comme alliée principale et l'Université comme terrain hostile.

Le MJ ne doit pas pousser les PJ vers une option. Chaque choix est valide et ouvre une voie différente. Le choix peut être différé — les PJ peuvent demander du temps — mais pas évité. Si les PJ refusent de choisir, le temps passe, le sceau cède davantage, et le choix devient plus urgent à chaque session.`,notes_mj:"C'est le moment pivot de la campagne. Tout ce qui suit dépend de ce choix. Le MJ doit laisser les PJ débattre entre eux, peser les options, formuler leurs doutes. Ne pas précipiter. Ne pas orienter. Si les PJ choisissent une quatrième voie — par exemple, tenter de parler à Thade ET protéger les tombes — c'est possible, mais difficile. Le MJ peut le permettre en créant une scène de négociation tendue où Thade accepte un compromis temporaire tout en continuant ses prélèvements en secret."},texte_a_lire:`L'ancienne salle de filtration sous les égouts des Terrasses est sèche, voûtée, silencieuse. Mara et Thorgar se font face de chaque côté d'une table de pierre. C'est la première fois qu'ils se rencontrent.

Mara parle la première : « Nous savons maintenant. Thade prend les os. Thade ouvre le seuil. La question est : qu'allez-vous faire ? »

Thorgar regarde les PJ. « Les rites peuvent encore être restaurés. Si nous récupérons les os. Si nous protégeons les deux dernières tombes. Mais si vous choisissez le mauvais côté, tout est perdu. »`,objectif:"Choisir le camp des PJ : servir Thade, le confronter, ou protéger le sceau avec la Résistance.",contexte_mj:{situation:"Les PJ ont les indices : S-01, les outils d'Université, les passages des égouts, les caisses de Caldris, le bourdonnement du Puits. Ils savent que Thade prélève les os pour ouvrir le seuil. Maintenant, ils doivent choisir.",secrets:["Thade ne sait pas encore que les PJ ont rencontré la Résistance. Si les PJ rapportent tout à Thade, il saura et agira contre la Résistance.","Thorgar peut restaurer les rites si les PJ récupèrent les ossements. Mais il faut agir avant que les deux dernières tombes tombent.","Mara propose un plan : infiltrer les égouts, intercepter les caisses de Caldris, récupérer les os et les ramener au Cimetière."],rappels:["Ce choix n'est pas définitif — les PJ peuvent changer de camp plus tard. Mais chaque choix a des conséquences immédiates.","Si les PJ choisissent Thade, le Front 'Le Plan de Thade' avance. S'ils choisissent la Résistance, le Front 'Le Sceau qui cède' peut être ralenti."]},defis:[{competence:"Perspicacité",dd:15,reussite:"Les PJ sentent que Mara et Thorgar disent la vérité. Pas toute la vérité — mais ce qu'ils savent, ils le disent honnêtement.",echec:"Difficile de savoir qui croire. Tout le monde a un agenda. L'Université, la Résistance, les nains. Les PJ doivent suivre leur instinct."}],guide_mj:{intention:"Forcer le choix. C'est le moment pivot de la campagne. Les PJ ne peuvent plus rester neutres.",mise_en_place:"QG de la Résistance dans les égouts. Mara et Thorgar face à face. Les PJ au centre.",deroulement:["Mara expose la situation : Thade prend les os, le seuil s'ouvre.","Thorgar confirme : les rites peuvent être restaurés si les os reviennent.","Mara propose un plan : infiltrer les égouts, intercepter les caisses.","Les PJ choisissent : Thade, la Résistance, ou une troisième voie."],actions_utiles:["Accepter le plan de Mara et rejoindre la Résistance.","Refuser et retourner à Thade avec les informations.","Proposer une troisième voie : confronter Thade directement.","Demander plus de temps pour réfléchir (avec conséquences : le sceau cède davantage)."],fronts_heritiers:["Tous les fronts sont concernés. Le choix des PJ détermine quelles horloges avancent et lesquelles ralentissent."],jeu_des_pnj:"Mara est directe, pragmatique. Thorgar est solennel, rituel. Les deux ont besoin des PJ.",escalade:"Si les PJ refusent de choisir, Mara les laisse partir mais prévient : « Le temps n'est pas votre allié. Chaque jour qui passe, une tombe de plus. »",sortie:"Les PJ quittent la salle avec un choix. Ce choix ouvre la porte du Scénario 2 — Les Masques de Nyx."},reperes_de_jeu:{indice_indispensable:"Les PJ doivent comprendre que Thade prélève les os pour ouvrir le seuil et qu'ils doivent choisir leur camp.",ne_pas_bloquer_sur_un_jet:"Aucun jet ne peut empêcher le choix. Les PJ peuvent le reporter, mais pas l'éviter.",question_dramatique:"Allez-vous servir un homme qui ne ment jamais, ou combattre un homme que personne ne veut arrêter ?"},transitions:{resume:"Les PJ quittent la salle. Derrière eux, Mara et Thorgar restent silencieux. Le bruit de l'eau dans les égouts est le seul son.",reussite:"Les PJ ont choisi. La campagne bascule vers le Scénario 2.",echec:"Les PJ ont refusé de choisir. Le temps passe. Le sceau cède. La campagne bascule avec plus de pression et moins d'alliés."}}]}]},l={id:"scenario2",titre:"Les Masques de Nyx",niveau:"Niveaux 5-8 · 8-10 séances · Acte II de la trilogie",vue_ensemble:{ton:"Thriller conspirationniste et horreur urbaine. La cité se déchire pendant que la réalité se plisse. Le ton est plus sombre, plus urgent que le Scénario 1 — les PJ ne découvrent plus, ils agissent. Mais chaque action a un coût politique, humain ou cosmique.",themes:["La crise politique — la peur exploite le vide laissé par la vérité.","La crise clandestine — des relais involontaires manipulés accomplissent le travail de Thade sans le savoir.","La crise cosmique — la réalité de Valombre commence à mentir. La Spirale filtre.","Le coût de l'action — chaque choix a des victimes collatérales. Le décompte compte pour l'épilogue."],question_dramatique:"Les PJ peuvent-ils naviguer trois crises simultanées — politique, clandestine, cosmique — sans perdre la cité, leurs alliés, ni eux-mêmes ?",axes_de_crise:[{axe:"Public",description:"Le Champion de la Bannière Pure exploite la peur. L'émeute, la loi martiale, l'expulsion des nains. La garde est divisée. Le Conseil tergiverse. La crise politique est visible, bruyante, et elle masque les deux autres.",scenes_cles:["L'Émeute de la Place de la Fondation"]},{axe:"Clandestin",description:"Les Endeuillés d'Edran Morn recrutent parmi les brisés. Le rite de deuil fissure le sceau. Elian Voss cache les expériences de Thade. La Réserve Interdite contient la trace écrite. La crise clandestine est invisible, silencieuse, et elle nourrit la crise cosmique.",scenes_cles:["Les Endeuillés d'Edran Morn","La Réserve de Recherche Interdite","Le Laboratoire d'Elian Voss"]},{axe:"Cosmique",description:"Le déphasage devient visible. Les routes mentent, le ciel change, les distances fluctuent. La Spirale filtre par les fissures du sceau. La Tour Arcanique s'éveille. La crise cosmique est l'horloge maîtresse — si elle avance trop loin, Valombre est perdue.",scenes_cles:["Le Déphasage Visible","L'Assaut de la Tour","Le Laboratoire de Verre"]}],ce_que_les_pj_savent:["Thade Coren orchestre les prélèvements d'ossements pour ouvrir le seuil de la Spirale.","Les Sept Thanes sont les ancrages du sceau. Le sceau cède.","Le protocole S-01 relie Thade à Nyx et à Sealine Vael.","La Résistance existe dans la Vieille Ville. Olane est une alliée institutionnelle.","Le choix du Scénario 1 détermine leur position : avec Thade, avec la Résistance, ou entre les deux."],ce_que_les_pj_doivent_decouvrir:["Thade utilise des relais involontaires : les Endeuillés d'Edran Morn affaiblissent le sceau par le deuil, sans le savoir.","Le Champion de la Bannière Pure reçoit un soutien logistique de marchands qui veulent affaiblir les clans nains — la crise politique est instrumentalisée sans faire de lui un simple pantin.","Le déphasage est la preuve visible que la Spirale filtre. Les zones déphasées s'étendront.","Elian Voss, médecin de Caldris, a reproduit S-01 sur des vivants après Sealine. La Larme de Vael est le catalyseur du rituel.","Thade a consulté la Réserve Interdite 142 fois en 8 ans. Les premières recherches de Thade sur les seuils précèdent la disparition de Sealine ; le rituel actuel, lui, naît de sa perte.","Le corps de Thade est dans une cuve au 7e étage de la Tour. Son esprit est au sommet, dans le vortex."],structure_narrative:[{acte:"Acte I — La Crise s'Étend",resume:"Les PJ affrontent les trois axes simultanément : l'émeute publique, les Endeuillés clandestins, le déphasage cosmique. Chaque scène interagit avec les autres — ignorer un axe le laisse avancer."},{acte:"Acte II — La Tour s'Éveille",resume:"Les PJ infiltrent l'Université pour trouver les preuves : la Réserve Interdite, le laboratoire d'Elian Voss. La trace écrite de Thade est là. La Larme de Vael est nommée."},{acte:"Acte III — La Confrontation",resume:"Les PJ montent la Tour. Chaque étage est un choix : libérer ou tuer, négocier ou combattre. Le décompte des victimes compte pour l'épilogue. Au 7e étage : le corps de Thade, les cahiers, et la porte du sommet. Le Scénario 2 s'arrête au seuil du vortex — les PJ n'affrontent pas encore Thade. Ils comprennent que le Scénario 3 commence de l'autre côté de cette porte."}],pnj_cles:[{id:"champion_banniere_pure",nom:"Le Champion de la Bannière Pure",role:"Fanatique charismatique. Exploite la peur pour prendre le contrôle de la garde. Accepte un soutien logistique de marchands qui veulent affaiblir les clans nains."},{id:"edran_morn",nom:"Edran Morn",role:"Chef des Endeuillés. Homme brisé qui croit ouvrir une porte vers les morts. Proxy involontaire de Thade."},{id:"elian_voss",nom:"Elian Voss",role:"Médecin de Caldris. A reproduit S-01 sur des vivants après Sealine. Témoin clé, effrayé, retournable."},{id:"maera_olane",nom:"Maëra Olane",role:"Alliée institutionnelle. Peut fournir accès, couverture et données. Sa protection dépend des PJ."},{id:"magi_tuteur_loyal",nom:"Le Magi-Tuteur loyal",role:"Allié caché dans la Tour. Peut guider les PJ s'ils ne l'attaquent pas."}],lieux_cles:[{id:"place_fondation",nom:"Place de la Fondation",role:"Centre civique. Lieu de l'émeute. Le Champion y harangue la foule."},{id:"cave_des_endeuilles",nom:"Cave des Endeuillés",role:"Vieille Ville. Repaire d'Edran Morn. Le rite de deuil y est accompli."},{id:"bibliotheque_recherche_interdite",nom:"Réserve de Recherche Interdite",role:"Sous-sol de la bibliothèque. 142 consultations de Thade. La trace écrite."},{id:"laboratoire_elian_voss",nom:"Laboratoire d'Elian Voss",role:"Sous un amphithéâtre médical. Dossiers, bocaux, schéma de la Larme de Vael."},{id:"tour_arcanique",nom:"Tour Arcanique",role:"Dispositif rituel. 7 étages modifiés. Le corps de Thade au 7e. Le vortex au sommet."}]},revelations_indispensables:[{id:"rev_proxies_thade",titre:"Thade utilise des relais involontaires",resume:"Les Endeuillés d'Edran Morn affaiblissent le sceau par un rite de deuil inversé, sans le savoir. Les textes qu'ils utilisent ont été laissés circuler délibérément par Thade. Le Champion de la Bannière Pure, lui, reçoit un soutien logistique de marchands qui veulent affaiblir les clans nains et prendre influence sur la Mine — mais le chaos qu'il crée masque aussi les opérations de Thade.",sources:["Cave des Endeuillés : textes volés portant le tampon de la Réserve Interdite (Acte I, scène 2).","Place de la Fondation : rumeurs sur le soutien logistique du Champion (Acte I, scène 1)."],declencheur:"Investigation DD 13 dans la cave + Renseignements DD 14 sur le Champion.",plan_b:"Le tampon de la Réserve est visible sans jet. Mara ou Olane peuvent faire le lien entre les textes et Thade. Le soutien logistique du Champion peut être révélé par un contact dans la pègre ou par le Collecteur.",consequence_si_ratee:"Les PJ ne comprennent pas que Thade a armé les Endeuillés. Le rite continue. Le déphasage s'accélère sans que les PJ puissent l'arrêter à la source."},{id:"rev_rite_inverse",titre:"Le rite d'Edran Morn est un Edhrek-Murn inversé",resume:"Edran accomplit les gestes d'Edhrek-Murn à l'envers. Au lieu de maintenir le sceau, il le fissure. Il croit ouvrir une porte vers les morts — en réalité, il ouvre le seuil de la Spirale.",sources:["Cave des Endeuillés : observation du rite (Acte I, scène 2).","Thorgar ou un prêtre nain : comparaison avec les gestes d'Edhrek-Murn."],declencheur:"Religion DD 14 pour identifier l'inversion.",plan_b:"Si Religion échoue, Thorgar (s'il accompagne les PJ) reconnaît les gestes et dit : « C'est Edhrek-Murn... mais à l'envers. C'est une profanation. » Les textes de l'Université portent le tampon — le lien est visuel.",consequence_si_ratee:"Les PJ ne comprennent pas que le rite attaque le sceau. Ils peuvent disperser les Endeuillés sans détruire les textes, et le rite reprendra avec un nouveau gourou."},{id:"rev_dephasage_source",titre:"Le déphasage vient du Puits de l'Abîme",resume:"Les zones déphasées contiennent des filaments planaires violets qui pointent vers le Puits de l'Abîme, sous le Mausolée du Cimetière. Le déphasage est la Spirale qui filtre par les fissures du sceau.",sources:["Zone déphasée dans la Vieille Ville (Acte I, scène 3)."],declencheur:"Connaissances (mystères) DD 15 ou Détection de la magie.",plan_b:"Les filaments sont visibles avec Détection de la magie sans jet. Leur direction (vers le sous-sol) est observable. Le troisième écho (Perception DD 13) confirme que le son vient d'ailleurs.",consequence_si_ratee:"Les PJ ne relient pas le déphasage au sceau. Ils le traitent comme un phénomène inexplicable. La crise cosmique reste abstraite, et les PJ ne savent pas où frapper."},{id:"rev_registre_142",titre:"Thade a consulté la Réserve 142 fois en 8 ans",resume:"Le registre de la Réserve de Recherche Interdite montre 142 séances de Thade sur 8 ans, portant sur la résonance planaire, les seuils et les ancrages rituels. La fréquentation s'effondre après la mort de Sealine — il a trouvé ce qu'il cherchait.",sources:["Réserve de Recherche Interdite : registre sur le lutrin (Acte II, scène 1)."],declencheur:"Investigation DD 13 pour lire le registre. Connaissances (mystères) DD 17 pour déchiffrer les ouvrages.",plan_b:"Le registre est visible sans jet. Le nom de Thade et le nombre 142 sont lisibles. Olane peut interpréter les ouvrages si les PJ lui apportent des notes.",consequence_si_ratee:"Les PJ n'ont pas la preuve écrite de la préparation de Thade. Sans le registre, la confrontation avec Thade manque de fondement documentaire. Le Conseil ne peut pas être convaincu."},{id:"rev_larme_vael",titre:"La Larme de Vael est le catalyseur du rituel",resume:"Le laboratoire d'Elian Voss contient un schéma qui nomme la Larme de Vael — l'objet au cœur du rituel de seuil. L'annotation de Sealine dit : « Ne jamais alimenter cela avec des vivants. » Sealine savait. Thade l'a fait quand même.",sources:["Laboratoire d'Elian Voss : schéma caché sous une plaque (Acte II, scène 2).","Elian Voss lui-même : interrogation ou intimidation."],declencheur:"Investigation DD 12 pour trouver le schéma. Décryptage DD 17 pour lire l'annotation.",plan_b:"Le schéma est visible sans jet. Le nom « Larme de Vael » et le cachet de Caldris sont lisibles. Elian Voss, intimidé (DD 14), révèle tout. L'annotation peut être lue par Olane ou Mara.",consequence_si_ratee:"Les PJ ne savent pas ce qu'est la Larme de Vael. Au Scénario 3, la confrontation au sommet perd sa dimension tragique — les PJ ne savent pas que Sealine a essayé d'empêcher Thade."},{id:"rev_corps_thade_cuve",titre:"Le corps de Thade est dans la cuve, son esprit au sommet",resume:"Au 7e étage de la Tour, le corps de Thade flotte dans une cuve de cristal. Son esprit est au sommet, dans le vortex. Détruire le corps affaiblit Thade au sommet. Les cahiers bordeaux sont huit ans de lettres à Sealine.",sources:["Laboratoire de Verre : cuve centrale et mur de cahiers (Acte III, scène 2).","Magi-Tuteur loyal : explication si les PJ ne l'attaquent pas."],declencheur:"Aucun jet requis. La cuve et les cahiers sont visibles.",plan_b:"Le magi-tuteur peut expliquer la connexion cuve-sommet. Les cahiers parlent d'eux-mêmes. Investigation DD 12 pour comprendre le système de la cuve.",consequence_si_ratee:"Les PJ montent au sommet sans affaiblir Thade. La confrontation du Scénario 3 est plus difficile — Thade a toutes ses phases. Les PJ n'ont pas lu les cahiers, et la dimension humaine de Thade reste invisible."}],fronts_actifs:[{id_front:"front_plan_thade",nom:"Le Plan de Thade",etat_initial:"Thade a déplacé ses opérations vers la Tour Arcanique. Les prélèvements d'ossements continuent via les égouts. Les Endeuillés d'Edran Morn affaiblissent le sceau par procuration. Elian Voss maintient le laboratoire caché. Thade prépare le rituel de seuil avec la Larme de Vael. L'horloge est à l'étape 2-3.",manifestation_scenarios:"La Tour se verrouille. Les flux détournés s'intensifient. Les Endeuillés reçoivent des textes de l'Université. Le laboratoire d'Elian Voss est actif.",interactions_scenes:[{scene:"Les Endeuillés d'Edran Morn",interaction:"Les textes volés portent le tampon de la Réserve Interdite. Thade a laissé les textes circuler. Si les PJ détruisent les textes, le rite s'arrête — mais les Endeuillés chercheront un nouveau gourou."},{scene:"La Réserve de Recherche Interdite",interaction:"Le registre montre 142 séances. La preuve écrite de la préparation. Si les PJ copient le registre, le front ralentit — Thade sait que sa trace est exposée."},{scene:"Le Laboratoire d'Elian Voss",interaction:"Le schéma de la Larme et les bocaux des échecs. Si les PJ récupèrent le schéma ou retournent Elian, Thade perd un agent clé et un composant du rituel."},{scene:"L'Assaut de la Tour",interaction:"La Tour est le dispositif rituel. Chaque étage canalise l'énergie vers le sommet. Si les PJ montent, Thade accélère le rituel en représailles."},{scene:"Le Laboratoire de Verre",interaction:"Le corps de Thade dans la cuve. Si les PJ détruisent le corps, Thade au sommet perd une phase. Mais il peut accélérer le rituel."}],leviers_pj_scenario:"Les PJ peuvent ralentir ce front en : détruisant les textes des Endeuillés, copiant le registre, retournant Elian Voss, détruisant le corps de Thade dans la cuve, ou en empêchant les flux d'atteindre la Tour."},{id_front:"front_factions_crise",nom:"Les Factions de la Crise",etat_initial:"Le Champion de la Bannière Pure monte en influence. Des patrouilles civiques harcèlent les nains et les étrangers. Les Endeuillés recrutent parmi les malades. La garde est divisée. Le Conseil tergiverse. L'horloge est à l'étape 2.",manifestation_scenarios:"L'émeute de la Place de la Fondation. Les disparitions dans la Vieille Ville. La loi martiale partielle. L'expulsion des nains du Centre Civique.",interactions_scenes:[{scene:"L'Émeute de la Place de la Fondation",interaction:"Le Champion harangue la foule. Si l'émeute tourne à la violence, le front avance de deux étapes. Si les PJ calment la foule, le front ralentit. Si les PJ démasquent le soutien logistique du Champion, le front recule."},{scene:"Les Endeuillés d'Edran Morn",interaction:"Si les PJ tuent Edran, les Endeuillés rejoignent le Champion. La violence nourrit la crise. Si les PJ convainquent Edran d'arrêter, les Endeuillés se dispersent pacifiquement."},{scene:"Le Déphasage Visible",interaction:"Le déphasage alimente la peur. Les habitants paniquent. Le Champion exploite la peur pour recruter. Si les PJ expliquent la cause du déphasage, la peur diminue."}],leviers_pj_scenario:"Les PJ peuvent ralentir ce front en : calmant l'émeute, démasquant le soutien logistique du Champion, retournant Edran Morn, protégeant les nains, ou en fournissant au Conseil une preuve présentable qui justifie une action."},{id_front:"front_sceau_qui_cede",nom:"Le Sceau qui cède",etat_initial:"Cinq à six tombes sur sept sont touchées. Le rite d'Edran Morn fissure le sceau par le deuil. Les prélèvements de Thade continuent. Le déphasage devient visible. L'horloge est à l'étape 3-4.",manifestation_scenarios:"Les zones déphasées s'étendent. Les routes mentent. Le ciel change. Le Puits de l'Abîme pulse. Les filaments planaires sont visibles.",interactions_scenes:[{scene:"Les Endeuillés d'Edran Morn",interaction:"Le rite inversé fissure le sceau. Si les PJ arrêtent le rite, le front ralentit d'une étape. Si le rite continue, le front avance d'une étape par session."},{scene:"Le Déphasage Visible",interaction:"Les filaments planaires pointent vers le Puits de l'Abîme. Le déphasage est la preuve visible que le sceau cède. Si les PJ identifient la source, ils savent où frapper."},{scene:"L'Assaut de la Tour",interaction:"Le rituel au sommet accélère la fissuration. Si les PJ désorganisent la Tour, ils retardent l'ouverture complète du vortex. S'ils tardent, le sceau cède entièrement."}],leviers_pj_scenario:"Les PJ peuvent ralentir ce front en : arrêtant le rite d'Edran, détruisant les textes, restaurant les rites d'Edhrek-Murn avec Thorgar, ou en désorganisant la Tour avant l'ouverture complète du vortex."},{id_front:"front_cite_sous_pression",nom:"La Cité sous pression",etat_initial:"Valombre est en crise. Les marchands paniquent. L'approvisionnement en argent vacille. Les nains sont menacés. Olane est isolée. Le Conseil vote une loi martiale partielle. L'horloge est à l'étape 2.",manifestation_scenarios:"La loi martiale suspend les droits des communautés clandestines. Les Terrasses sont placées sous tutelle civile. Les routes vers la Mine deviennent impraticables.",interactions_scenes:[{scene:"L'Émeute de la Place de la Fondation",interaction:"L'émeute justifie la loi martiale. Si les PJ calment la foule, le Conseil n'a pas de prétexte. Si l'émeute tourne à la violence, le Conseil vote la loi martiale le lendemain."},{scene:"Le Déphasage Visible",interaction:"Le déphasage rend les routes impraticables. L'approvisionnement en argent s'effondre. Les marchands paniquent. Si les PJ expliquent la cause, la panique diminue."},{scene:"La Réserve de Recherche Interdite",interaction:"Si les PJ sont surpris dans la Réserve sans couverture, Olane est arrêtée. Les PJ perdent leurs alliés institutionnels. Si Olane couvre, le front ralentit."}],leviers_pj_scenario:"Les PJ peuvent ralentir ce front en : calmant l'émeute, protégeant Olane, fournissant au Conseil une preuve présentable, ou en gardant les Terrasses ouvertes aux humains."}],scenes_structure:{legende:{obligatoire:"La scène doit être jouée. Le scénario ne peut pas se terminer sans elle.",obligatoire_flexible:"La scène doit être jouée, mais son contenu peut être adapté ou déplacé.",optionnel:"La scène peut être ignorée, mais elle enrichit l'expérience et peut fournir des indices ou alliés."},scenes:[{titre:"L'Émeute de la Place de la Fondation",acte:"Acte I",statut:"obligatoire_flexible",axe:"Public",dependances:[],revele:["Le Champion exploite la peur","Edran recrute dans l'ombre","La garde est divisée"],note:"Peut être déclenchée par une rumeur, une invitation du Conseil, ou par les PJ qui passent par la Place. Le contenu s'adapte au choix du Scénario 1."},{titre:"Le Conseil en Crise",acte:"Acte I",statut:"obligatoire_flexible",axe:"Public",dependances:["L'Émeute de la Place de la Fondation (le Conseil réagit à l'émeute)"],revele:["Avel Ronce est paralysé par la procédure","Hessa Brunefer défend les Terrasses","Maelric presse le Conseil d'agir ou de subir la quarantaine","Olane peut apporter des preuves si les PJ la soutiennent"],note:"Peut se jouer au Conseil de Valombre ou dans un lieu institutionnel équivalent. Le contenu s'adapte aux relations des PJ avec le Conseil et l'Université."},{titre:"Les Endeuillés d'Edran Morn",acte:"Acte I",statut:"obligatoire",axe:"Clandestin",dependances:["L'Émeute de la Place de la Fondation (optionnel — Edran peut être suivi depuis l'émeute)"],revele:["Le rite inversé fissure le sceau","Les textes viennent de l'Université","Thade utilise des relais involontaires"],note:"Si les PJ n'ont pas suivi Edran depuis l'émeute, la cave peut être trouvée par Renseignements DD 14 ou via Ursula."},{titre:"Le Déphasage Visible",acte:"Acte I",statut:"obligatoire_flexible",axe:"Cosmique",dependances:[],revele:["Le déphasage vient du Puits de l'Abîme","La Spirale filtre par les fissures","Les zones déphasées s'étendront"],note:"Peut se produire n'importe quand pendant l'Acte I. Le MJ déclenche la zone déphasée quand les PJ traversent la Vieille Ville."},{titre:"La Réserve de Recherche Interdite",acte:"Acte II",statut:"obligatoire",axe:"Clandestin",dependances:["Les Endeuillés d'Edran Morn (les textes pointent vers la Réserve)"],revele:["142 consultations de Thade","Les premières recherches sur les seuils précèdent la disparition de Sealine ; le rituel actuel naît de sa perte","La théorie des seuils planaires"],note:"L'accès dépend du choix du Scénario 1 : Olane peut fournir un accès si les PJ sont ses alliés. Sinon, Effraction DD 15."},{titre:"Le Laboratoire d'Elian Voss",acte:"Acte II",statut:"obligatoire",axe:"Clandestin",dependances:["La Réserve de Recherche Interdite (l'ardoise du 6e étage est mentionnée)"],revele:["La Larme de Vael est le catalyseur","Sealine savait et a essayé d'empêcher","Thade et Elian ont reproduit S-01 sur des vivants après Sealine"],note:"Elian Voss est présent de jour, absent de nuit. Sa réaction dépend de la réputation des PJ."},{titre:"L'Assaut de la Tour",acte:"Acte III",statut:"obligatoire",axe:"Cosmique",dependances:["La Réserve de Recherche Interdite","Le Laboratoire d'Elian Voss"],revele:["La Tour est un dispositif rituel","Le décompte des victimes compte pour l'épilogue","Le sommet contient le vortex"],note:"5-6 rencontres tactiques. Chaque rencontre a une option non-létale. Le MJ doit tenir le décompte du nombre de victimes."},{titre:"Le Laboratoire de Verre",acte:"Acte III",statut:"obligatoire",axe:"Cosmique",dependances:["L'Assaut de la Tour"],revele:["Le corps de Thade est dans la cuve","Les cahiers : 8 ans de lettres à Sealine","Détruire le corps affaiblit Thade au sommet"],note:"Aucun jet requis pour voir la cuve et les cahiers. La décision de détruire le corps est morale, pas mécanique."}],scenes_optionnelles:[{titre:"La Loi Martiale",description:"Le Conseil vote une loi martiale partielle. Les patrouilles civiques ferment les Terrasses. Les PJ doivent négocier avec Avel Ronce ou Hessa Brunefer pour garder l'accès.",declencheur:"Si l'émeute tourne à la violence ou si les PJ ignorent le Champion.",apport:"Comprendre la paralysie institutionnelle. Avel Ronce peut devenir un allié si les PJ lui apportent une preuve présentable."},{titre:"Le Marchand et la Mine",description:"Les PJ enquêtent sur le soutien logistique du Champion. Ils remontent jusqu'aux marchands qui veulent affaiblir les clans nains et prendre influence sur la Mine. Confrontation politique ou économique.",declencheur:"Si les PJ cherchent qui soutient logistiquement le Champion (Renseignements DD 14).",apport:"Démasquer l'instrumentalisation de la crise. Le Champion perd sa crédibilité si le soutien logistique est révélé publiquement."},{titre:"Les Malades de la Vieille Ville",description:"Ursula soigne les malades dans la Maison des Retours. Les symptômes s'aggravent. Certains malades entrent en zone déphasée et ne reviennent pas.",declencheur:"Si les PJ retournent voir Ursula ou Mara après le déphasage visible.",apport:"Comprendre l'impact humain du déphasage. Ursula peut identifier les premiers cas d'assimilation par la Spirale."}]},encadres_mj:[{id:"enc_pj_tuent_tour",titre:"Que faire si les PJ tuent tout dans la Tour",situation:"Les PJ montent la Tour en force. Ils tuent les étudiants charmés, les gardes piégés, la créature de la Spirale. Le décompte de victimes est élevé.",principe:"Le scénario ne punit pas — il consigne. Chaque victime est comptée. L'épilogue du Scénario 3 en tiendra compte. Le MJ ne dit pas « vous ne devriez pas faire ça » — il décrit les conséquences.",proceder:[{etape:"Tenir le décompte de chaque victime",detail:"Noter le nom, l'étage et les circonstances. Étudiant charmé tué au lieu d'être libéré. Garde piégé tué au lieu d'être évité. Créature de la Spirale tuée au lieu d'être retournée."},{etape:"Décrire les conséquences immédiates",detail:"Les étudiants charmés meurent avec les yeux vides. Les gardes explosent avec les runes. La créature de la Spirale se dissout en gémissant. Le MJ décrit — il ne juge pas."},{etape:"Le magi-tuteur réagit",detail:"Si le magi-tuteur est encore vivant, il dit : « Vous avez tué des étudiants. Des enfants. Ils étaient prisonniers. » Il ne combat pas — il pleure. Si les PJ l'ont aussi tué, personne ne pleure."},{etape:"L'épilogue en tiendra compte",detail:"Au Scénario 3, le décompte de victimes détermine le ton de l'épilogue. Un décompte élevé donne un épilogue sombre — Valombre se souvient de ce que les PJ ont fait dans la Tour."}],a_ne_pas_faire:["Ne pas empêcher les PJ de tuer. C'est leur choix.","Ne pas rendre les rencontres impossibles à résoudre sans violence — chaque rencontre a une option non-létale.","Ne pas moraliser en jeu. Les conséquences parlent d'elles-mêmes."]},{id:"enc_pj_attaquent_thade_prematurement",titre:"Que faire si les PJ attaquent Thade prématurément",situation:"Les PJ décident d'attaquer Thade avant d'avoir les preuves de la Réserve, du laboratoire d'Elian Voss ou des cahiers. Ils veulent frapper dès l'Acte I ou au début de l'Acte II.",principe:"Thade est protégé par l'institution. Une attaque prématurée se retourne contre les PJ — pas par la force de Thade, mais par le système qui le protège.",proceder:[{etape:"Thade n'est pas accessible",detail:"Thade est dans la Tour, qui est verrouillée. La Tour est gardée. L'accès est limité aux Maîtres. Les PJ ne peuvent pas entrer sans plan."},{etape:"L'Université protège Thade",detail:"Si les PJ attaquent publiquement, l'Université se ferme. Olane est arrêtée. Les PJ perdent leurs alliés institutionnels. Le Conseil les déclare ennemis de la cité."},{etape:"Thade ne se défend pas directement",detail:"Thade ne combat pas les PJ. Il les ignore, ou il les fait arrêter par la garde. Il dit : « Je comprends votre colère. Mais vous attaquez l'Université, pas moi. »"},{etape:"Orienter vers la collecte de preuves",detail:"Le MJ guide les PJ vers la Réserve, le laboratoire d'Elian, les Endeuillés. Sans preuve, l'attaque est un crime. Avec preuve, c'est une enquête légitime."}],a_ne_pas_faire:["Ne pas faire de Thade un boss combattable dès l'Acte I. Il est protégé par le système.","Ne pas punir les PJ avec un TPK. Les conséquences sont politiques, pas mortelles.","Ne pas fermer le scénario. L'attaque prématurée complique les choses, mais le scénario continue."]},{id:"enc_pj_ignorent_un_axe",titre:"Que faire si les PJ ignorent un axe de crise",situation:"Les PJ se concentrent sur un seul axe (public, clandestin ou cosmique) et ignorent les deux autres. Par exemple, ils passent tout l'Acte I sur le Champion et ignorent les Endeuillés et le déphasage.",principe:"Les trois axes avancent en parallèle. Ignorer un axe ne le met pas en pause — il avance sans les PJ. Les conséquences s'accumulent.",proceder:[{etape:"L'axe ignoré avance",detail:"Si les PJ ignorent le Champion : la Bannière Pure prend le contrôle de la garde. Les nains sont expulsés. S'ils ignorent les Endeuillés : le rite continue, le déphasage s'aggrave. S'ils ignorent le déphasage : les routes deviennent impraticables, l'approvisionnement s'effondre."},{etape:"Les PNJ signalent la crise ignorée",detail:"Mara ou Ursula parle des disparitions. Olane mentionne les flux. Thorgar signale de nouvelles fissures. Les PJ entendent que ça va mal ailleurs."},{etape:"Les axes interagissent",detail:"Le déphasage alimente la peur, qui alimente le Champion. Les Endeuillés fissurent le sceau, qui accélère le déphasage. Ignorer un axe accélère les autres."},{etape:"Le scénario s'adapte",detail:"Les PJ peuvent rattraper — mais dans des conditions plus difficiles. Le scénario ne se bloque pas. Il devient plus dur."}],a_ne_pas_faire:["Ne pas forcer les PJ à jouer les trois axes simultanément. C'est leur choix.","Ne pas annuler les conséquences de l'ignorance. Les axes avancent.","Ne pas rendre le scénario impossible. Plus difficile, oui. Impossible, non."]},{id:"enc_pj_negocient_champion",titre:"Que faire si les PJ veulent négocier avec le Champion",situation:"Les PJ veulent parler au Champion de la Bannière Pure au lieu de le combattre ou de le démasquer. Ils pensent pouvoir le raisonner ou l'utiliser.",principe:"Le Champion est charismatique, froid et précis. Il ne crie pas — il projette. Il peut être raisonné sur les faits, mais pas sur les causes. Sa croisade reçoit un soutien logistique de marchands qui veulent affaiblir les clans nains — il n'est pas nécessairement acheté ; il accepte des soutiens qu'il juge utiles à sa mission.",proceder:[{etape:"Le Champion écoute",detail:"Il reçoit les PJ en privé. Il est courtois, mesuré, presque amical. Il dit : « Vous voyez les mêmes choses que moi. Les maladies. Le froid. Les disparitions. »"},{etape:"Il ne cède pas sur les causes",detail:"Si les PJ disent que les nains ne sont pas responsables, il répond : « Alors qui ? L'Université ? Le Conseil ? Quelqu'un doit porter la responsabilité. Les nains sont les plus visibles. »"},{etape:"Révéler le soutien logistique",detail:"Si les PJ révèlent qu'il reçoit un soutien logistique de marchands qui veulent affaiblir les clans nains, le Champion réagit — soit avec colère (il ne savait pas), soit avec pragmatisme (il savait et accepte car ces soutiens servent sa croisade). Dans les deux cas, il ne s'arrête pas. Mais il perd sa crédibilité si l'information est rendue publique."},{etape:"Une alliance fragile est possible",detail:"Si les PJ lui apportent une preuve que Thade est responsable du déphasage, le Champion peut détourner sa croisade vers l'Université. C'est utile mais dangereux — le Champion reste un fanatique."}],a_ne_pas_faire:["Ne pas rendre le Champion facilement raisonnable. Il croit en sa mission.","Ne pas transformer le Champion en allié fiable. C'est un outil instable.","Ne pas bloquer la négociation. Le Champion parle — c'est sa méthode."]}],aides_jeu:{indices_recap:[{scene:"L'Émeute de la Place de la Fondation",jet:"Renseignements DD 14",info:"Le Champion reçoit un soutien logistique de marchands qui veulent affaiblir les clans nains et prendre influence sur la Mine. Il n'est pas acheté — il accepte des soutiens utiles à sa croisade."},{scene:"L'Émeute de la Place de la Fondation",jet:"Discrétion DD 13",info:"Edran Morn observe la manifestation depuis les ruelles. Il recrute parmi les plus désespérés après la foule."},{scene:"Les Endeuillés d'Edran Morn",jet:"Religion DD 14",info:"Le rite d'Edran est un Edhrek-Murn inversé. Au lieu de maintenir le sceau, il le fissure."},{scene:"Les Endeuillés d'Edran Morn",jet:"Investigation DD 13",info:"Les textes portent le tampon de la Réserve de Recherche Interdite de l'Université. Thade a laissé les textes circuler."},{scene:"Le Déphasage Visible",jet:"Connaissances (mystères) DD 15 ou Détection de la magie",info:"Des filaments violets relient la zone à un point souterrain — le Puits de l'Abîme. Le déphasage vient du sceau."},{scene:"Le Déphasage Visible",jet:"Perception DD 13",info:"Le troisième écho d'un son n'est pas une répétition — c'est un son de la Spirale qui filtre."},{scene:"La Réserve de Recherche Interdite",jet:"Investigation DD 13",info:"142 séances de Thade sur 8 ans. Sujets : résonance planaire, seuils, ancrages. Effondrement après la mort de Sealine."},{scene:"La Réserve de Recherche Interdite",jet:"Connaissances (mystères) DD 17",info:"Les ouvrages décrivent un rituel de seuil avec ancrages physiques. Le protocole S-01 est une application de ce rituel."},{scene:"Le Laboratoire d'Elian Voss",jet:"Investigation DD 12",info:"Schéma de la Larme de Vael. Cachet de Caldris. La Larme est le catalyseur du rituel."},{scene:"Le Laboratoire d'Elian Voss",jet:"Décryptage DD 17",info:"Annotation de Sealine : « Ne jamais alimenter cela avec des vivants. » Elle savait. Thade l'a fait quand même."},{scene:"Le Laboratoire d'Elian Voss",jet:"Intimidation DD 14",info:"Elian Voss révèle tout : Thade a commandé le protocole, Caldris fournit le matériel, la Larme est le catalyseur."},{scene:"L'Assaut de la Tour",jet:"Investigation DD 10",info:"Ardoise du 6e étage : équation préliminaire de S-01 datée de sept ans. Les premières recherches de Thade sur les seuils précèdent la disparition de Sealine."},{scene:"Le Laboratoire de Verre",jet:"Aucun jet requis",info:"Le corps de Thade est dans la cuve. Les cahiers bordeaux sont 8 ans de lettres à Sealine. La plume écrit en temps réel."}],pnj_recap:[{id:"champion_banniere_pure",nom:"Le Champion de la Bannière Pure",faction:"Bannière Pure (soutenu logistiquement par des marchands)",role_court:"Fanatique charismatique / Crise publique",apparition:"Acte I, scène 1",info_cle:"Exploite la peur. Soutenu logistiquement par des marchands qui veulent affaiblir les clans nains. Peut être démasqué ou détourné vers l'Université.",dd_clés:"Diplomatie DD 15 pour calmer l'émeute. Renseignements DD 14 pour le soutien logistique."},{id:"edran_morn",nom:"Edran Morn",faction:"Endeuillés (proxy involontaire de Thade)",role_court:"Gourou du deuil / Crise clandestine",apparition:"Acte I, scène 2",info_cle:"Rite inversé d'Edhrek-Murn qui fissure le sceau. Textes volés de l'Université. Sincère dans son deuil.",dd_clés:"Religion DD 14 pour identifier l'inversion. Diplomatie DD 16 pour le convaincre d'arrêter."},{id:"elian_voss",nom:"Elian Voss",faction:"Caldris / Université (agent de Thade)",role_court:"Médecin brisé / Témoin clé",apparition:"Acte II, scène 2",info_cle:"A mené les expériences sur des vivants. Schéma de la Larme de Vael. Retournable. Témoin le plus précieux.",dd_clés:"Intimidation DD 14 pour le retourner. Art de la magie DD 17 pour les bocaux."},{id:"maera_olane",nom:"Maëra Olane",faction:"Université (isolée)",role_court:"Alliée institutionnelle",apparition:"Acte II (accès à la Réserve)",info_cle:"Peut fournir accès, couverture et données. Sa protection dépend des PJ. Si elle est arrêtée, les PJ perdent tout soutien institutionnel.",dd_clés:"Pas de jet — elle s'ouvre si les PJ apportent des preuves."},{id:"magi_tuteur_loyal",nom:"Le Magi-Tuteur loyal",faction:"Université (loyal à Thade mais désillusionné)",role_court:"Allié caché dans la Tour",apparition:"Acte III, scène 1 (4e étage)",info_cle:"Peut expliquer la Tour, la cuve et le rituel. Guide les PJ s'ils ne l'attaquent pas.",dd_clés:"Pas de jet — il se présente si les PJ ne l'agressent pas."}],lieux_recap:[{id:"place_fondation",nom:"Place de la Fondation",scenes:["L'Émeute de la Place de la Fondation"],ambiance:"Cœur civique. Statue des Fondateurs. Foule dense. Tension."},{id:"cave_des_endeuilles",nom:"Cave des Endeuillés",scenes:["Les Endeuillés d'Edran Morn"],ambiance:"Sous-sol humide. Cire brûlée. Portraits des morts. Chaises dépareillées."},{id:"vieille_ville_ruelles",nom:"Ruelles déphasées de la Vieille Ville",scenes:["Le Déphasage Visible"],ambiance:"Distances trompeuses. Ciel laiteux. Odeurs absentes. Échos répétés."},{id:"bibliotheque_recherche_interdite",nom:"Réserve de Recherche Interdite",scenes:["La Réserve de Recherche Interdite"],ambiance:"Sous-sol. Froid sec. Lampes à mana bleutées. Cire blanche. Silence absolu."},{id:"laboratoire_elian_voss",nom:"Laboratoire d'Elian Voss",scenes:["Le Laboratoire d'Elian Voss"],ambiance:"Sous amphithéâtre. Formol, cire. Lampes vertes. Dossiers, bocaux, schémas."},{id:"tour_arcanique",nom:"Tour Arcanique",scenes:["L'Assaut de la Tour","Le Laboratoire de Verre"],ambiance:"Lavande et ozone. Cristal qui pousse. Runes bleues. Objets en lévitation. Bourdonnement du vortex."}],chronologie:[{phase:"Avant le scénario",evenements:["Il y a 8 ans : catastrophe de Nyx. Sealine se sacrifie. Thade survit.","Il y a 8 ans : Thade devient Archimage de l'Université. L'Université est reconstruite.","Depuis 8 ans : Thade consulte la Réserve Interdite (142 séances).","Depuis 8 ans : Thade écrit à Sealine tous les jours (cahiers bordeaux).","Depuis plusieurs années : Thade laisse circuler des textes de la Réserve vers la Vieille Ville.","Depuis plusieurs années : Elian Voss mène les expériences sur des vivants à Caldris.","Récemment : le déphasage devient visible. Les zones déphasées apparaissent.","Récemment : le Champion de la Bannière Pure monte en influence."]},{phase:"Acte I — La Crise s'Étend (semaines 1-2)",evenements:["L'émeute de la Place de la Fondation. Le Champion harangue la foule.","Les PJ infiltrent les Endeuillés. Le rite inversé est découvert.","Le déphasage devient visible dans la Vieille Ville.","Si l'émeute tourne à la violence : le Conseil vote la loi martiale."]},{phase:"Acte II — La Tour s'Éveille (semaines 2-4)",evenements:["Les PJ accèdent à la Réserve Interdite. 142 séances. La trace écrite.","Les PJ trouvent le laboratoire d'Elian Voss. La Larme de Vael. L'annotation de Sealine.","Thade verrouille la Tour. Les flux détournés s'intensifient.","Si les PJ ont retourné Elian : il peut témoigner au Conseil."]},{phase:"Acte III — La Confrontation (semaine 4-5)",evenements:["Les PJ montent la Tour. Chaque étage est un choix.","Le décompte des victimes est établi.","Les PJ atteignent le Laboratoire de Verre. Le corps de Thade. Les cahiers.","Les PJ se tournent vers la porte du sommet. Le bourdonnement du vortex les appelle."]}]},synopsis:"Le choix est fait. Les PJ connaissent la vérité sur Thade et le sceau. Mais connaître n'est pas arrêter. Les factions de Valombre se déchirent : le Champion de la Bannière Pure exploite la peur, les Endeuillés d'Edran Morn recrutent parmi les malades, la Résistance s'organise dans l'ombre. Le déphasage devient visible — les routes mentent, le ciel change, la Spirale filtre. Thade accélère ses prélèvements. La Tour Arcanique s'éveille.",evenements_mondiaux:{chronologie_inevitable:["Le déphasage s'aggrave : les routes de Valombre deviennent trompeuses, les distances fluctuent.","Le Champion de la Bannière Pure monte en influence. Des patrouilles civiques harcèlent les nains et les étrangers.","Les Endeuillés d'Edran Morn grandissent. Des disparitions dans la Vieille Ville.","Thade verrouille la Tour Arcanique. Les flux détournés s'intensifient."],consequences_echecs:["Si les PJ ignorent le Champion : la Bannière Pure prend le contrôle de la garde. Les nains sont expulsés du Centre Civique.","Si les PJ ignorent les Endeuillés : Edran Morn accomplit un rite qui accélère le déphasage.","Si les PJ ignorent le déphasage : les routes vers la Mine deviennent impraticables. L'approvisionnement en argent s'effondre.","Si les PJ attaquent Thade prématurément : l'Université se ferme. Olane est arrêtée. Les PJ perdent leurs alliés institutionnels."]},actes:[{titre:"Acte I — La Crise s'Étend",stake:"Les PJ doivent naviguer entre les factions qui s'affrontent pendant que le déphasage s'aggrave.",location:"Centre Civique, Vieille Ville, Terrasses Naines",scenes:[{id:"s2_emeute_place",titre:"L'Émeute de la Place de la Fondation",type:"Action",resume_mj:"Le Champion de la Bannière Pure organise une manifestation sur la Place de la Fondation. Il accuse les nains et les étrangers d'être responsables des maladies et des anomalies. La garde hésite à intervenir. Les PJ doivent choisir : calmer la foule, protéger les nains, ou exploiter le chaos.",idLieu:"place_fondation",idsPnj:["champion_banniere_pure","patrouille_mixte_conseil"],format_livre:{ambiance:"La Place de la Fondation est le cœur civique de Valombre. Un espace pavé, bordé de bâtiments administratifs aux façades de pierre grise. Au centre, la statue des Fondateurs — sept silhouettes naines, usées par le temps. La place est noire de monde. Des badauds, des curieux, des habitants en colère. L'air porte une tension qu'on pourrait couper au couteau. Le ciel est couvert, bas, d'un gris qui n'a pas décidé s'il allait pleuvoir ou s'abaisser encore.",deroulement_narratif:`Le Champion de la Bannière Pure se tient sur l'estrade, en robe blanche, le visage masqué. Sa voix porte sans effort. Il ne crie pas — il projette. Chaque phrase est calibrée. Il accuse les nains et les étrangers d'être responsables des maladies et du froid. Il ne ment pas sur les faits — les maladies et le froid sont réels. Il ment sur les causes. La foule boit ses mots. Des huées montent. Des nains du Centre Civique reculent vers les ruelles adjacentes. La garde mixte hésite au pied de l'estrade — Géraud Veyre, leur commandant, regarde les PJ d'un air qui dit : « Si vous avez une idée, c'est le moment. »

Dans les ruelles, un homme en robe sombre observe. Edran Morn. Il ne participe pas à l'émeute — il la récolte. Il parle aux plus désespérés, ceux qui ont perdu quelqu'un, ceux qui pleurent encore. Il leur murmure que les morts peuvent revenir. Si un PJ est attentif (Discrétion DD 13), il repère Edran et peut le suivre après la manifestation.

Les PJ ont trois options : calmer la foule (Diplomatie DD 15), intimider les meneurs (Intimidation DD 14), ou exploiter le chaos. Chaque choix a un coût. Calmer la foule protège les nains mais laisse le Champion libre. Intimider disperse la foule mais marque les PJ comme ennemis. Exploiter le chaos avance le front « Les Factions de la Crise » de deux étapes.`,notes_mj:"Le Champion reçoit un soutien logistique de marchands qui veulent affaiblir les clans nains et prendre influence sur la Mine. Il n'est pas acheté — il accepte des soutiens qu'il juge utiles à sa croisade. Le MJ peut révéler ce soutien par Renseignements DD 14 ou via le Collecteur. Si l'émeute tourne à la violence, le Conseil vote la loi martiale le lendemain. Edran Morn recrute parmi les plus désespérés après la manifestation — c'est la porte d'entrée vers la scène suivante."},texte_a_lire:`La Place de la Fondation est noire de monde. Le Champion de la Bannière Pure se tient sur l'estrade, en robe blanche, le visage masqué. Sa voix porte sans effort : « Valombre souffre. La maladie ronge nos quartiers. Le froid gagne nos rues. Et pendant ce temps, l'Université ferme les yeux, le Conseil tergiverse, et les étrangers profitent de notre faiblesse ! »

Des huées montent de la foule. Des nains du Centre Civique reculent vers les ruelles adjacentes. La garde mixte hésite au pied de l'estrade.`,objectif:"Gérer l'émeute : calmer, protéger, ou exploiter.",contexte_mj:{situation:"Le Champion exploite la peur grandissante. La garde mixte (humains et nains) est divisée. Le Conseil n'a pas donné d'ordres clairs. Les nains présents sont en danger.",secrets:["Le Champion reçoit un soutien logistique de marchands qui veulent affaiblir les clans nains et prendre influence sur la Mine. Il n'est pas acheté — il accepte des soutiens utiles à sa croisade.","Edran Morn observe la manifestation depuis les ruelles. Il recrute parmi les plus désespérés.","Si l'émeute tourne à la violence, le Front 'Les Factions de la Crise' avance de deux étapes."],rappels:["Le Champion ne ment pas sur les faits — les maladies et le froid sont réels. Il ment sur les causes.","La patrouille mixte est commandée par Géraud Veyre, qui respecte les PJ s'ils ont aidé le Conseil auparavant."]},defis:[{competence:"Diplomatie",dd:15,reussite:"Les PJ calment la foule en rappelant que les nains sont les fondateurs de Valombre. Le Champion perd sa dynamique.",echec:"La foule ignore les PJ. L'émeute continue."},{competence:"Intimidation",dd:14,reussite:"Les PJ intimident les meneurs. La foule se disperse, mais le Champion les note comme ennemis.",echec:"Les PJ sont hués. La tension augmente."},{competence:"Discrétion",dd:13,reussite:"Les PJ repèrent Edran Morn dans la foule et peuvent le suivre après la manifestation.",echec:"Impossible de distinguer les visages dans la masse."}],indices:[{indice:"Le soutien logistique du Champion",localisation:"Rumeurs et contacts",detection:"Renseignements DD 14",information:"Le Champion reçoit un soutien logistique de marchands qui veulent affaiblir les clans nains et prendre influence sur la Mine.",usage:"Le Champion n'est pas qu'un fanatique — il accepte des soutiens qu'il juge utiles à sa croisade."},{indice:"Edran Morn dans la foule",localisation:"Ruelles de la Place",detection:"Discrétion DD 13",information:"Edran observe et recrute. Il parle aux plus désespérés après la manifestation.",usage:"Piste vers les Endeuillés et le rite de déphasage."}],guide_mj:{intention:"Montrer que la crise n'est pas que mystique — elle est politique et sociale.",mise_en_place:"Place de la Fondation, milieu de journée. Foule dense. Champion sur l'estrade.",deroulement:["Le Champion harangue la foule.","Les PJ interviennent ou observent.","La garde hésite.","Edran recrute dans les ruelles."],actions_utiles:["Calmer la foule.","Protéger les nains.","Suivre Edran Morn.","Parler au Champion directement."],fronts_heritiers:["Front 'Les Factions de la Crise'","Front 'La Cité sous pression'"],jeu_des_pnj:"Le Champion est charismatique, froid, précis. Il ne crie pas — il projette. Géraud Veyre est un soldat fatigué qui veut des ordres clairs.",escalade:"Si l'émeute tourne à la violence, des nains sont blessés. Les Terrasses se ferment aux humains.",sortie:"La foule se disperse ou tourne à la violence. Les PJ ont vu le Champion, Edran et l'état de la garde."},reperes_de_jeu:{indice_indispensable:"Les PJ doivent savoir que le Champion exploite la crise et qu'Edran recrute dans l'ombre.",ne_pas_bloquer_sur_un_jet:"Même si tous les jets échouent, l'émeute se produit. Les PJ voient le Champion et la tension.",question_dramatique:"Qui profite du chaos ?"},transitions:{resume:"La Place se vide. Les nains regagnent les Terrasses. Le Champion disparaît dans un carrosse fermé.",reussite:"Les PJ ont calmé la foule ou identifié les acteurs cachés.",echec:"L'émeute a tourné à la violence. Les Terrasses se ferment. La crise s'aggrave."}},{id:"s2_conseil_crise",titre:"Le Conseil en Crise",type:"Social",resume_mj:"Après l'émeute, le Conseil de Valombre convoque une session extraordinaire. Avel Ronce tente de produire du consensus sans trancher. Hessa Brunefer exige que les Terrasses ne soient pas placées sous tutelle. L'Émissaire Maelric de Caldris rappelle son ultimatum : si Valombre ne prouve pas qu'elle tient le verrou, Caldris imposera la quarantaine. Maera Olane, si les PJ la soutiennent, peut apporter des preuves sur les irrégularités de Thade. Les PJ doivent naviguer entre pression politique, preuves scientifiques et intérêts nains pour obtenir une décision — ou constater que le Conseil ne décidera rien.",idLieu:"conseil_valombre",idsPnj:["avel_ronce","hessa_brunefer","envoye_caldris","patrouille_mixte_conseil","maera_olane"],format_livre:{ambiance:"La salle du Conseil est vaste, voûtée, éclairée par des lampes d'ambre qui ne tremblent pas. Des bancs de pierre en demi-cercle font face à une table surélevée. Avel Ronce est assis derrière la table, un dossier ouvert devant lui, l'ordre du jour sous les doigts. Hessa Brunefer se tient debout à sa droite, les bras croisés, l'étole de délégation sur les épaules. Maelric de Caldris se tient à gauche, pâle, un peu raide, un carnet à la main. La patrouille mixte surveille les portes. Maera Olane est assise au fond de la salle, un dossier sous le bras, prête à parler si on lui donne la parole — et si on la protège.",deroulement_narratif:`Avel Ronce ouvre la session en annonçant que le Conseil doit « répondre aux événements de la Place de la Fondation et aux inquiétudes de nos partenaires extérieurs ». Il ne nomme ni le Champion, ni Maelric, ni les malades. Il parle de « tensions » et de « mesures appropriées ».

Hessa Brunefer prend la parole la première. Elle rappelle quel article de quelle charte protège les Terrasses, exige que les clans ne soient pas punis pour les actes du Champion, et menace de fermer l'accès commercial à la mine si le Conseil place les Terrasses sous tutelle.

Maelric parle ensuite. Courtois, froid, il pose une carte sur la table : Valombre n'est plus atteignable par les routes normales depuis trois semaines. Les marchands ne reviennent pas. Les messagers n'arrivent plus. Si le Conseil ne peut pas prouver qu'il contrôle la situation, Caldris imposera la quarantaine dans dix jours.

Avel Ronce tente de renvoyer chaque point à « la commission compétente ». Hessa s'y oppose. Maelric s'impatiente. La salle s'enlise.

Si les PJ sont présents (convocation officielle, invitation d'un membre du Conseil, ou parce qu'ils se sont invités), ils peuvent :

1. Appuyer Hessa : les Terrasses ne sont pas le problème. La crise vient d'ailleurs. Persuasion DD 14. Si réussi, Avel recule sur la tutelle.

2. Présenter les preuves d'Olane : si Olane est là et que les PJ la soutiennent, elle expose les irrégularités de Thade (142 consultations, les outils d'Université sur les tombes, le protocole S-01). Avel Ronce veut renvoyer ça à « la commission disciplinaire de l'Université ». Olane répond que l'Université étouffe l'affaire depuis des mois. Persuasion DD 15. Si réussi, le Conseil ouvre une enquête officielle.

3. Négocier avec Maelric : les PJ proposent une preuve concrète que Valombre tient le verrou (les rites de Thorgar, les os des Thanes, le sceau). Diplomatie DD 15. Si réussi, Maelric accorde un délai supplémentaire. Si échoué, il maintient l'ultimatum.

4. Demander la loi martiale : les PJ poussent le Conseil à voter des mesures d'exception pour protéger les Terrasses et interdire les rassemblements du Champion. Avel accepte avec soulagement — ça lui donne l'illusion d'agir. Mais la loi martiale avance aussi le Front « Le Conseil, la Machine à Retarder ».

Si les PJ ne font rien, le Conseil ne décide rien. Avel renvoie tout en commission. Hessa repart furieuse. Maelric note l'incapacité de Valombre dans son carnet.`,notes_mj:"Cette scène donne aux PJ un accès direct aux trois forces politiques : Avel (paralysie), Hessa (défense naine), Maelric (pression extérieure). Olane est présente seulement si les PJ l'ont rencontrée dans le Scénario 1 et qu'ils la soutiennent. Si Olane n'est pas disponible, les PJ perdent l'option 2 mais peuvent encore présenter les preuves eux-mêmes avec un DD plus élevé (16 au lieu de 15). La scène peut être jouée avant ou après le Déphasage Visible — si après, Maelric peut témoigner avoir vu une rue se déformer."},texte_a_lire:`La salle du Conseil est voûtée, éclairée par des lampes d'ambre. Avel Ronce est assis derrière la table surélevée, l'ordre du jour sous les doigts. Hessa Brunefer se tient à sa droite, les bras croisés. L'Émissaire Maelric de Caldris est à gauche, pâle, un carnet à la main.

Avel Ronce ouvre la session : « Le Conseil doit répondre aux tensions récentes et aux inquiétudes de nos partenaires extérieurs. »

Hessa Brunefer parle la première : « Les Terrasses ne seront pas placées sous tutelle. Les clans ne paieront pas pour les actes d'un étranger. »

Maelric pose une carte sur la table : « Valombre n'est plus atteignable par les routes normales. Si le Conseil ne prouve pas qu'il contrôle la situation, Caldris imposera la quarantaine dans dix jours. »

Avel Ronce regarde ses notes. « Nous allons examiner ces questions en commission. »`,objectif:"Obtenir une décision du Conseil — ou constater sa paralysie et trouver une autre voie.",contexte_mj:{situation:"Le Conseil réagit à l'émeute et à la pression caldrisienne. Avel Ronce veut éviter toute décision qui l'expose. Hessa Brunefer protège les Terrasses. Maelric presse avec un délai. Olane, si elle est là, apporte des preuves sur Thade.",secrets:["Avel Ronce n'est pas corrompu — il est dépassé. Il peut devenir un allié si les PJ lui apportent une vérité simple et présentable qui le couvre politiquement.","Hessa Brunefer sait que les nains possèdent une part du verrou, mais elle ne révélera rien devant Maelric sans garantie.","Maelric a vu le déphasage de ses propres yeux si la scène se joue après Le Déphasage Visible. Il peut en témoigner, ce qui crédibilise la crise.","Olane a été découragée de témoigner par l'Université. Si les PJ ne la protègent pas, elle se tait."],rappels:["Le Conseil ne décidera rien sans preuve présentable et sans quelqu'un pour assumer la décision politiquement.","La patrouille mixte est présente mais neutre — elle exécute les ordres du Conseil, elle ne prend pas parti."]},defis:[{competence:"Persuasion",dd:14,reussite:"Les PJ appuient Hessa : Avel recule sur la tutelle des Terrasses.",echec:"Avel renvoie la question en commission. Hessa repart sans garantie."},{competence:"Diplomatie",dd:15,reussite:"Les PJ négocient avec Maelric : il accorde un délai supplémentaire de cinq jours.",echec:"Maelric maintient l'ultimatum. Dix jours, pas un de plus."},{competence:"Persuasion",dd:15,reussite:"Olane (ou les PJ) présentent les preuves sur Thade : le Conseil ouvre une enquête officielle.",echec:"Avel renvoie à la commission disciplinaire de l'Université. L'affaire reste interne."}],indices:[{indice:"L'ultimatum de Caldris",localisation:"Témoignage de Maelric",detection:"Automatique",information:"Valombre n'est plus atteignable par les routes normales. Caldris imposera la quarantaine dans dix jours si le Conseil ne prouve pas qu'il tient le verrou.",usage:"Presser le Conseil d'agir ou chercher une preuve de stabilité crédible."},{indice:"Les irrégularités de Thade",localisation:"Dossier d'Olane",detection:"Olane doit être présente et soutenue",information:"142 consultations, outils d'Université sur les tombes, protocole S-01. L'Université étouffe l'affaire.",usage:"Forcer le Conseil à ouvrir une enquête officielle ou à agir sans l'Université."}],guide_mj:{intention:"Rendre les forces politiques jouables et concrètes. Les PJ voient que la crise n'est pas que mystique — elle est institutionnelle.",mise_en_place:"Salle du Conseil de Valombre. Session extraordinaire. Avel, Hessa, Maelric, patrouille mixte. Olane si les PJ la soutiennent.",deroulement:["Avel ouvre et tente de renvoyer en commission.","Hessa exige que les Terrasses ne soient pas punies.","Maelric pose son ultimatum.","Les PJ interviennent (ou non).","Le Conseil décide — ou ne décide pas."],actions_utiles:["Appuyer Hessa sur les Terrasses.","Soutenir Olane pour exposer Thade.","Négocier un délai avec Maelric.","Pousser à la loi martiale.","Constater la paralysie et chercher une autre voie."],fronts_heritiers:["Front 'Le Conseil, la Machine à Retarder'","Front 'La Réputation de Valombre'","Front 'La Révélation par étapes'"],jeu_des_pnj:"Avel est courtois, lent, incapable de trancher. Hessa est directe, sèche, intraitable sur les coutumes. Maelric est froid, précis, sincèrement inquiet. Olane parle vite quand elle tient une preuve, mais se tait si elle se sent exposée.",escalade:"Si les PJ échouent ou ne font rien : Avel renvoie tout en commission, Hessa ferme un accès commercial, Maelric note l'incapacité de Valombre. Le Front 'Le Conseil' avance d'une étape.",sortie:"Le Conseil a décidé quelque chose — ou n'a rien décidé. Les PJ savent maintenant qui pèse quoi dans la crise politique."},reperes_de_jeu:{indice_indispensable:"Les PJ doivent comprendre que le Conseil est paralysé et que la pression extérieure (Caldris) est réelle.",ne_pas_bloquer_sur_un_jet:"Même si tous les jets échouent, la scène se joue. Les PJ voient la paralysie du Conseil et l'ultimatum de Maelric.",question_dramatique:"Le Conseil peut-il agir — ou faut-il contourner le Conseil ?"},transitions:{resume:"La session se lève. Avel range ses dossiers. Hessa repart vers les Terrasses. Maelric note quelque chose dans son carnet.",reussite:"Les PJ ont obtenu une décision du Conseil — enquête, délai, ou protection des Terrasses.",echec:"Le Conseil n'a rien décidé. La paralysie est visible. Les PJ doivent trouver une autre voie."}},{id:"s2_endeuilles_edran",titre:"Les Endeuillés d'Edran Morn",type:"Investigation",resume_mj:"Les PJ infiltrent ou confrontent les Endeuillés dans la Cave des Endeuillés de la Vieille Ville. Edran Morn prêche un rite de deuil qui accélère le déphasage. Il croit ouvrir une porte vers les morts. En réalité, il ouvre le seuil de la Spirale.",idLieu:"cave_des_endeuilles",idsPnj:["edran_morn"],format_livre:{ambiance:"La Cave des Endeuillés est un sous-sol humide sous un immeuble abandonné de la Vieille Ville. On y descend par un escalier étroit, marche après marche, jusqu'à une pièce voûtée qui sent la cire brûlée et la pierre humide. Des chaises dépareillées autour d'une table couverte de coulures de cire. Des portraits, des bougies, des objets des morts occupent les niches creusées dans les murs — un ruban, une pipe, une lettre pliée. L'air est lourd, chaud, presque suffocant. On parle bas ici. On pleure bas.",deroulement_narratif:`Edran Morn se tient au fond de la cave. Robe sombre, visage marqué, mains ouvertes. Il ne prêche pas — il accueille. « Vous avez perdu quelqu'un », dit-il. « Tout le monde a perdu quelqu'un. Ici, nous ne pleurons pas. Nous ouvrons. »

Les Endeuillés sont assis, une vingtaine, silencieux. Certains tiennent des photos. D'autres ont les yeux fermés. Edran accomplit les gestes du rite : il trace des runes dans l'air, lentement, avec une précision de cérémonie. Les gestes ressemblent à quelque chose — si un PJ a vu les rites d'Edhrek-Murn au Temple-Forgeron, il reconnaît les mouvements. Mais à l'envers. Religion DD 14 pour identifier l'inversion : Edran accomplit Edhrek-Murn à l'envers. Au lieu de maintenir le sceau, il le fissure.

Sur la table, des textes. Des pages arrachées, photocopiées, recopiées à la main. Le tampon de la Réserve de Recherche Interdite de l'Université est visible sur l'une des pages. Investigation DD 13 pour examiner les textes : ils décrivent un rite de seuil, pas un rite de deuil. Edran a trouvé ces textes — il croit qu'ils ouvrent une porte vers les morts. En réalité, ils ouvrent le seuil de la Spirale.

Les PJ peuvent : convaincre Edran d'arrêter (Diplomatie DD 16 — difficile car Edran croit voir sa fille), disperser les Endeuillés par la force (Intimidation DD 13 — mais la violence les radicalise), ou détruire les textes (ce qui arrête le rite mais pousse les Endeuillés à chercher un nouveau gourou). La meilleure option est de convaincre Edran que son rite ne ramène pas les morts — il ouvre une porte vers quelque chose de pire.`,notes_mj:"Edran est sincère dans son deuil. Il n'est pas un agent de Thade — il est une victime indirecte. Thade a laissé les textes circuler délibérément pour affaiblir le sceau par procuration. Si les PJ tuent Edran, les Endeuillés rejoignent le Champion. La violence nourrit la crise. Si les PJ ont rencontré Ursula, elle peut les aider à approcher les Endeuillés avec compassion plutôt qu'avec force."},texte_a_lire:`La Cave des Endeuillés est une cave humide sous un immeuble abandonné. Des chaises dépareillées autour d'une table couverte de cire. Des portraits, des bougies et des objets des morts occupent les niches. L'air lourd sent la cire brûlée et la pierre humide.

Un homme en robe sombre se tient au fond. Son visage est marqué. « Vous avez perdu quelqu'un », dit-il. « Tout le monde a perdu quelqu'un. Ici, nous ne pleurons pas. Nous ouvrons. »`,objectif:"Comprendre le rite d'Edran, stopper les Endeuillés ou les retourner contre Thade.",contexte_mj:{situation:"Edran Morn a transformé le deuil en rite. Il croit que les morts peuvent revenir par le seuil. En réalité, le rite affaiblit le sceau et accélère le déphasage. Les Endeuillés sont des victimes, pas des ennemis — mais leur rite est dangereux.",secrets:["Edran a trouvé le rite dans des textes volés à l'Université — des textes que Thade a laissés circuler délibérément.","Le rite d'Edran et les prélèvements de Thade visent le même sceau. Edran affaiblit le verrou par le deuil, Thade par le vol d'os.","Si les PJ détruisent les textes d'Edran, le rite s'arrête. Mais les Endeuillés chercheront un nouveau gourou."],rappels:["Les Endeuillés sont des citoyens brisés, pas des fanatiques violents. La violence les radicalise.","Si les PJ ont rencontré Ursula, elle peut les aider à approcher les Endeuillés avec compassion."]},defis:[{competence:"Religion",dd:14,reussite:"Le rite d'Edran est une distorsion du rite d'Edhrek-Murn. Il accomplit les gestes à l'envers — au lieu de maintenir le sceau, il le fissure.",echec:"Le rite est étrange et funéraire. Difficile d'en comprendre la mécanique."},{competence:"Diplomatie",dd:16,reussite:"Les PJ convainquent Edran que son rite ne ramène pas les morts — il ouvre une porte vers quelque chose de pire. Edran, brisé, accepte d'arrêter.",echec:"Edran refuse. « Vous ne comprenez pas. J'ai vu ma fille. Elle m'attend. »"},{competence:"Intimidation",dd:13,reussite:"Les PJ dispersent les Endeuillés par la force. Le rite s'arrête, mais les Endeuillés se radicalisent.",echec:"Les Endeuillés se défendent. La cave devient un champ de bataille."}],indices:[{indice:"Les textes volés",localisation:"Cave des Endeuillés",detection:"Investigation DD 13",information:"Les textes d'Edran portent le tampon de la Réserve de Recherche Interdite de l'Université.",usage:"Preuve que Thade a laissé les textes circuler pour affaiblir le sceau par procuration."},{indice:"Le rite inversé",localisation:"Gestes d'Edran",detection:"Religion DD 14",information:"Edran accomplit les gestes d'Edhrek-Murn à l'envers. Au lieu de maintenir, il fissure.",usage:"Comprendre que le rite est une arme contre le sceau, pas un rite de deuil."}],guide_mj:{intention:"Montrer que Thade utilise des relais involontaires. Les Endeuillés sont des outils involontaires.",mise_en_place:"Cave humide, nocturne. Edran au fond. Endeuillés assis.",deroulement:["Les PJ entrent et observent le rite.","Religion pour comprendre.","Diplomatie ou intimidation pour arrêter.","Investigation pour trouver les textes."],actions_utiles:["Convaincre Edran d'arrêter.","Détruire les textes.","Retourner les Endeuillés contre Thade.","Capturer Edran pour interrogatoire."],fronts_heritiers:["Front 'Le Sceau qui cède' — le rite d'Edran accélère la fissure.","Front 'Le Plan de Thade' — les textes prouvent la manipulation."],jeu_des_pnj:"Edran est sincère dans son deuil. Il n'est pas un agent de Thade — il est une victime indirecte. Le tuer renforce la Bannière Pure.",escalade:"Si les PJ tuent Edran, les Endeuillés rejoignent le Champion. La violence nourrit la crise.",sortie:"Les PJ quittent la cave avec ou sans Edran. Les textes de l'Université sont la clé : Thade a armé les Endeuillés."},reperes_de_jeu:{indice_indispensable:"Les PJ doivent comprendre que le rite d'Edran fissure le sceau et que les textes viennent de l'Université.",ne_pas_bloquer_sur_un_jet:"Même si Religion échoue, les PJ voient les textes de l'Université. Le lien est visuel.",question_dramatique:"Un homme de bonne foi peut-il faire le mal sans le savoir ?"},transitions:{resume:"La cave se vide. Les bougies s'éteignent. L'air redevient froid et humide.",reussite:"Les PJ ont arrêté le rite et récupéré les textes. Piste vers la Réserve Interdite.",echec:"Le rite continue. Le déphasage s'aggrave. Les Endeuillés se radicalisent."}},{id:"s2_dephasage_visible",titre:"Le Déphasage Visible",type:"Horreur",resume_mj:"Les PJ expérimentent le déphasage en direct. Une route qu'ils connaissent se déforme. Les distances changent. Le ciel prend une teinte violette. Un écho de la Spirale filtre dans Valombre. Ils doivent traverser la zone déphasée pour atteindre leur objectif.",idLieu:"vieille_ville_ruelles",idsPnj:[],format_livre:{ambiance:"Les ruelles de la Vieille Ville sont étroites, pavées de pierres inégales, bordées de maisons penchées dont les étages se rapprochent au fil des siècles. Normalement, on y sent le pain, la fumée, l'humidité de la rivière. Mais aujourd'hui, l'air ne porte plus d'odeur. Le ciel, visible entre les toits, a pris une teinte laiteuse — pas grise, pas violette, quelque chose entre les deux. Les murs ne sont pas à la même distance. Le sol semble souple sous les pieds, comme s'il y avait une couche d'air entre la semelle et la pierre.",deroulement_narratif:`Les PJ entrent dans la zone sans avertissement. Une rue qu'ils connaissent, qu'ils ont parcourue dix fois, se déforme. Les distances changent. Le bout de la ruelle n'est pas plus proche après cinq minutes de marche. Un son familier — le bruit d'une charrette, le cri d'un marchand — se répète trois fois, identique, puis s'arrête. Le troisième écho est légèrement différent. Perception DD 13 : c'est un son de la Spirale, pas de Valombre. La Spirale filtre par les fissures du sceau.

Si les PJ utilisent Détection de la magie, ils voient des filaments violets dans l'air — des lignes fines, presque invisibles, qui descendent vers le sous-sol. Direction : le Puits de l'Abîme. Connaissances (mystères) DD 15 : le déphasage est causé par la fissuration du sceau. Plus le sceau cède, plus ces zones s'étendront.

La zone est limitée — quelques rues — mais à l'intérieur, les repères habituels ne fonctionnent plus. Survie DD 14 pour trouver un chemin stable. Si les PJ échouent, ils tournent en rond et ressortent au point de départ après 20 minutes. La zone n'est pas un piège mortel — c'est un avertissement. Les habitants de la Vieille Ville ont commencé à éviter ces rues. Ceux qui y entrent en ressortent désorientés, parfois changés.

Si les PJ ont des liens avec la Spirale (objets, rêves, contacts avec Sealine), ils sont plus sensibles au déphasage. S'ils restent trop longtemps, ils subissent un effet de confusion ou entendent la voix de Sealine.`,notes_mj:"Le déphasage n'est pas une information — c'est une expérience. Le MJ doit le faire vivre sensoriellement : l'absence d'odeur, la souplesse du sol, les échos répétés, la distance qui ne diminue pas. C'est la première fois que les PJ expérimentent directement la Spirale qui filtre. Cette scène transforme la crise cosmique d'un concept abstrait en une réalité corporelle."},texte_a_lire:`Vous connaissez ces ruelles. Vous les avez parcourues dix fois. Mais aujourd'hui, les murs ne sont pas à la même distance. Le sol semble souple sous vos pieds. Le ciel, visible entre les toits penchés, a pris une teinte laiteuse qui n'a rien à voir avec l'heure.

Un son que vous connaissez — le bruit d'une charrette, le cri d'un marchand — se répète trois fois, identique, puis s'arrête. L'air ne porte plus d'odeur. Vous marchez depuis cinq minutes et le bout de la ruelle n'est pas plus proche.`,objectif:"Traverser la zone déphasée et atteindre l'autre côté sans perdre de membres du groupe.",contexte_mj:{situation:"Le déphasage est localisé mais intense. La réalité se plisse. Les PJ doivent naviguer dans un espace qui ne suit plus les règles normales. La zone est limitée — quelques rues — mais à l'intérieur, les repères habituels ne fonctionnent plus.",secrets:["Le déphasage est causé par la fissuration du sceau. Plus le sceau cède, plus ces zones s'étendent.","Si les PJ utilisent Détection de la magie, ils voient des filaments violets qui relient la zone à un point souterrain — la direction du Puits de l'Abîme.","Les habitants de la Vieille Ville ont commencé à éviter ces rues. Ceux qui y entrent en ressortent désorientés, parfois changés."],rappels:["Le déphasage n'est pas mortel par lui-même, mais il peut séparer le groupe, désorienter, ou révéler des choses que les PJ ne devraient pas voir.","Si les PJ ont des liens avec la Spirale (objets, rêves, contacts avec Sealine), ils sont plus sensibles au déphasage."]},defis:[{competence:"Survie",dd:14,reussite:"Les PJ trouvent un chemin stable à travers la zone. Ils sentent les variations et évitent les pièges spatiaux.",echec:"Les PJ tournent en rond. Ils ressortent au point de départ après 20 minutes."},{competence:"Connaissances (mystères)",dd:15,reussite:"Les PJ identifient les filaments planaires et peuvent les suivre jusqu'à leur source — le Puits de l'Abîme.",echec:"Les filaments sont visibles mais incompréhensibles. Des lignes violettes dans l'air qui ne mènent nulle part."},{competence:"Perception",dd:13,reussite:"Les PJ remarquent que les échos sonores se répètent par trois. Le troisième écho est légèrement différent — c'est un son de la Spirale, pas de Valombre.",echec:"Les sons sont étranges mais sans signification claire."}],indices:[{indice:"Les filaments planaires",localisation:"Zone déphasée",detection:"Détection de la magie ou Connaissances (mystères) DD 15",information:"Des filaments violets relient la zone à un point souterrain. Direction : Puits de l'Abîme.",usage:"Preuve visuelle que le déphasage vient du sceau."},{indice:"Le troisième écho",localisation:"Sons de la zone",detection:"Perception DD 13",information:"Le troisième écho d'un son n'est pas une répétition — c'est un son de la Spirale qui filtre.",usage:"Comprendre que la Spirale n'est pas un autre monde lointain. Elle est là, qui filtre par les fissures."}],guide_mj:{intention:"Faire vivre le déphasage. Ce n'est pas une information — c'est une expérience.",mise_en_place:"Les PJ traversent la Vieille Ville et entrent dans une zone déphasée sans avertissement.",deroulement:["Les PJ entrent dans la zone.","Les repères spatiaux et temporels se déforment.","Survie pour naviguer.","Connaissances pour comprendre.","Les PJ ressortent de l'autre côté (ou au point de départ)."],actions_utiles:["Suivre les filaments vers le Puits.","Marquer le sol pour ne pas tourner en rond.","Utiliser Détection de la magie.","Fermer les yeux et avancer au son."],fronts_heritiers:["Front 'Le Sceau qui cède' — le déphasage est la preuve visible.","Front 'La Cité sous pression' — les habitants paniquent."],jeu_des_pnj:"Aucun PNJ. La zone est vide. Les habitants ont fui.",escalade:"Si les PJ restent trop longtemps dans la zone, ils subissent un effet de confusion ou entendent la voix de Sealine.",sortie:"Les PJ ressortent de la zone, secoués. Ils savent maintenant ce qu'est le déphasage : la Spirale qui filtre."},reperes_de_jeu:{indice_indispensable:"Les PJ doivent avoir vécu le déphasage et compris qu'il vient du sceau.",ne_pas_bloquer_sur_un_jet:"Même si Survie échoue, les PJ finissent par ressortir. La zone n'est pas un piège mortel — c'est un avertissement.",question_dramatique:"Que se passe-t-il quand la réalité de votre ville commence à mentir ?"},transitions:{resume:"Les PJ ressortent de la zone. L'air reprend ses odeurs. Le ciel redevient normal. Mais ils savent que ça s'étendra.",reussite:"Les PJ ont traversé et identifié la source. Ils peuvent agir.",echec:"Les PJ ont tourné en rond et ressorti au point de départ. Le temps est perdu."}}]},{titre:"Acte II — La Tour s'Éveille",stake:"Les PJ doivent infiltrer la Tour Arcanique ou la Réserve Interdite pour comprendre ce que Thade construit.",location:"Tour Arcanique, Réserve de Recherche Interdite",scenes:[{id:"s2_reserve_interdite",titre:"La Réserve de Recherche Interdite",type:"Investigation",resume_mj:"Les PJ accèdent à la Réserve de Recherche Interdite de la bibliothèque. Ils y trouvent le registre des consultations de Thade : 142 séances sur huit ans, avec un effondrement après la mort de Sealine. La trace écrite de la préparation de Thade.",idLieu:"bibliotheque_recherche_interdite",idsPnj:[],format_livre:{ambiance:"La Réserve de Recherche Interdite est un niveau souterrain de la bibliothèque centrale de l'Université. On y accède par un escalier en colimaçon derrière une porte de chêne renforcée de fer. L'air est froid et sec — un froid de conservation, pas d'hiver. Des lampes à mana brûlent bas, projetant une lumière bleutée sur les étagères. Les livres ont des couvertures scellées de cire blanche — chaque ouvrage est verrouillé jusqu'à ce qu'un Maître de département le demande. L'air sent le papier ancien et la cire. Le silence est absolu, presque physique.",deroulement_narratif:`Un registre est posé sur le lutrin à l'entrée. Grand, relié de cuir, les pages jaunies. Les noms des Maîtres qui ont consulté les ouvrages, par date et par sujet. Investigation DD 13 pour le lire : le nom de Thade Coren apparaît 142 fois sur huit ans. Les sujets : résonance planaire, seuils dimensionnels, ancrages rituels, théorie des sceaux. La fréquentation est dense la première année — 60 séances — puis s'effondre après la catastrophe de Nyx. Il a trouvé ce qu'il cherchait. Il n'a plus besoin de la bibliothèque.

Connaissances (mystères) DD 17 pour déchiffrer les ouvrages : ils décrivent un rituel de seuil — ouvrir un passage vers un plan adjacent en utilisant des ancrages physiques. Le protocole S-01 est une application de ce rituel. Les textes sont arcaniques, obscurs, mais la théorie est claire : on peut ouvrir une porte si on a assez d'ancrages et un catalyseur.

Si les PJ ont les textes des Endeuillés, ils peuvent les comparer avec les ouvrages de la Réserve. Les textes d'Edran sont des copies dégradées des mêmes pages. Thade a laissé les textes circuler — il a armé les Endeuillés avec des fragments de la théorie qu'il maîtrise depuis des années.

Une note dans la marge du registre mentionne une ardoise non effacée au 6e étage de la Tour Arcanique. Équation préliminaire de S-01, datée de sept ans — avant la mort de Sealine. Thade travaillait déjà sur la théorie des seuils avant la disparition de Sealine. Mais le rituel actuel — celui qui vise à la ramener — naît après Nyx, quand la recherche devient obsession.`,notes_mj:"L'accès dépend du choix du Scénario 1. Olane peut fournir un accès si les PJ sont ses alliés. Sinon, Effraction DD 15. Sous la loi martiale, l'accès non autorisé est un crime — Olane peut couvrir, mais si les PJ sont surpris sans couverture, elle est arrêtée. Le registre est visible sans jet — le nom de Thade et le nombre 142 sont lisibles dès l'entrée. Les ouvrages nécessitent Connaissances DD 17, mais Olane peut les interpréter si les PJ lui apportent des notes."},texte_a_lire:`La Réserve de Recherche Interdite est un niveau souterrain de la bibliothèque centrale. Froid sec, lampes à mana basses, livres aux couvertures scellées de cire blanche. L'air sent le papier ancien et la cire.

Un registre est posé sur le lutrin. Les noms des Maîtres qui ont consulté les ouvrages. Celui de Thade apparaît 142 fois sur huit ans.`,objectif:"Trouver la trace des recherches de Thade et comprendre ce qu'il prépare.",contexte_mj:{situation:"La Réserve est accessible aux Maîtres de département. Olane peut fournir un accès si les PJ sont ses alliés. Sinon, Effraction DD 15. Le registre montre 142 séances de Thade, avec un effondrement après la mort de Sealine.",secrets:["Les ouvrages consultés par Thade portent sur la résonance planaire, les seuils et les ancrages rituels. Connaissances (mystères) DD 17 pour les déchiffrer.","La fréquentation de Thade s'effondre après la mort de Sealine — il a trouvé ce qu'il cherchait et n'a plus besoin de la bibliothèque.","Une ardoise non effacée au 6e étage de la Tour contient l'équation préliminaire de S-01, datée de sept ans — avant la mort de Sealine."],rappels:["Sous la loi martiale du Conseil, l'accès non autorisé est un crime. Olane peut couvrir les PJ.","Si les PJ ont les textes des Endeuillés, ils peuvent les comparer avec les ouvrages de la Réserve."]},defis:[{competence:"Investigation",dd:13,reussite:"Le registre montre 142 séances. Les sujets : résonance planaire, seuils, ancrages. La fréquentation s'effondre après la mort de Sealine.",echec:"Le registre est illisible ou endommagé. Les PJ ne trouvent que le nom de Thade."},{competence:"Connaissances (mystères)",dd:17,reussite:"Les ouvrages décrivent un rituel de seuil : ouvrir un passage vers un plan adjacent en utilisant des ancrages physiques. Le protocole S-01 est une application de ce rituel.",echec:"Les textes sont arcaniques et obscurs. La théorie est claire mais l'application reste floue."}],indices:[{indice:"Le registre de Thade",localisation:"Lutrin de la Réserve",detection:"Investigation DD 13",information:"142 séances sur 8 ans. Sujets : résonance planaire, seuils, ancrages. Effondrement après la mort de Sealine.",usage:"Les premières recherches précèdent la perte ; le rituel actuel la transforme en objectif."},{indice:"L'ardoise du 6e étage",localisation:"Tour Arcanique, 6e étage",detection:"Mention dans les notes de la Réserve",information:"Équation préliminaire de S-01 datée de sept ans — avant la mort de Sealine.",usage:"Thade travaillait déjà sur la théorie des seuils avant la disparition de Sealine. Mais le rituel actuel — celui qui vise à la ramener — naît après Nyx, quand la recherche devient obsession."}],guide_mj:{intention:"Donner aux PJ la preuve écrite que Thade a préparé le rituel pendant des années.",mise_en_place:"Réserve souterraine. Froid, sec, silencieux. Lampes basses.",deroulement:["Les PJ accèdent à la Réserve.","Ils trouvent le registre.","Ils déchiffrent les ouvrages.","Ils comprennent : Thade a tout préparé."],actions_utiles:["Copier le registre.","Relever les passages essentiels.","Faire un croquis des diagrammes.","Comparer avec les textes des Endeuillés.","Chercher l'ardoise du 6e étage."],fronts_heritiers:["Front 'Le Plan de Thade' — les PJ ont maintenant la preuve écrite.","Front 'La Cité sous pression' — l'Université est complice par ignorance."],jeu_des_pnj:"Aucun PNJ. Les livres parlent.",escalade:"Si les PJ sont surpris, Olane peut couvrir. Sinon, procédure interne.",sortie:"Les PJ quittent la Réserve avec 142 séances, des ouvrages sur les seuils et la certitude que Thade a préparé le rituel pendant des années."},reperes_de_jeu:{indice_indispensable:"Les PJ doivent savoir que Thade a consulté 142 fois la Réserve et que ses recherches portaient sur les seuils planaires.",ne_pas_bloquer_sur_un_jet:"Le registre est visible sans jet. Le nom de Thade et le nombre 142 sont lisibles.",question_dramatique:"Quand un homme brillant prépare quelque chose pendant huit ans, qui peut l'arrêter ?"},transitions:{resume:"Les PJ referment les ouvrages et quittent la Réserve. La cire blanche des couvertures brille dans l'obscurité.",reussite:"Les PJ ont la trace écrite et la théorie. Prochaine étape : la Tour.",echec:"Les PJ ont trouvé le registre sans déchiffrer les ouvrages. Olane peut les aider à interpréter."}},{id:"s2_laboratoire_elian",titre:"Le Laboratoire d'Elian Voss",type:"Révélation",resume_mj:"Les PJ trouvent le laboratoire caché d'Elian Voss sous un amphithéâtre médical. Des dossiers, des bocaux, un schéma qui nomme la Larme de Vael. Le cachet de Caldris confirme le lien avec l'extérieur. Le protocole S-01 est là, complet.",idLieu:"laboratoire_elian_voss",idsPnj:["elian_voss"],format_livre:{ambiance:"Sous un ancien amphithéâtre médical de l'Université, une porte métallique dissimulée derrière un panneau de bois pourri. La porte grince sur un couloir court qui descend vers une pièce basse, voûtée, éclairée par des lampes alchimiques vertes. L'odeur frappe d'abord : formol, cire, et quelque chose de doux en dessous — quelque chose d'organique qui ne devrait pas être là. Des colonnes de dossiers s'élèvent jusqu'au plafond. Des bocaux opaques alignés sur des étagères de fer. Une table de travail couverte de notes, de schémas, d'instruments de précision.",deroulement_narratif:`À gauche, cinquante dossiers étiquetés « stabilisés ». Lecture directe : cinquante patients stabilisés par des dérivés du protocole S-01, menés après la catastrophe de Nyx. Des noms, des dates, des dosages. Les patients viennent de Caldris — le cachet de Caldris est sur chaque dossier. Sealine est S-01, la première tentative consciente de stabilisation planaire. Les patients d'Elian sont postérieurs : des reproductions et adaptations du protocole S-01. À droite, sept bocaux sans étiquette. Art de la magie DD 17 : le sérum dans les bocaux est une préparation planaire. Il stabilise le corps pendant le transit vers la Spirale. Les sept bocaux contiennent les restes des sept échecs d'Elian après S-01. Toutes ont échoué.

Sous une plaque amovible de la table de travail, deux dossiers cachés. Investigation DD 12 pour trouver la plaque. Le premier dossier porte un schéma ancien — un dispositif en forme de larme, avec des annotations en écriture fine et précise. Le schéma nomme la Larme de Vael. Cachet de Caldris sur le schéma. Décryptage DD 17 pour lire l'annotation : « Ne jamais alimenter cela avec des vivants. » L'écriture est celle de Sealine. Sa main. Elle savait. Elle a essayé d'empêcher Thade. Il l'a fait quand même.

Elian Voss est présent si les PJ arrivent de jour. Il est effrayé — un homme brisé qui sait ce qu'il a fait. Intimidation DD 14 : il révèle tout. Thade a commandé les reproductions du protocole après Nyx, Caldris fournit le matériel, la Larme est le catalyseur. Elian n'est pas un fanatique — c'est un médecin qui a franchi la ligne par peur de Thade. Si les PJ le retournent, il peut témoigner au Conseil. S'ils le tuent, ils perdent un témoin clé.`,notes_mj:"Le schéma de la Larme est visible sans jet — le nom et le cachet sont lisibles. L'annotation de Sealine nécessite Décryptage DD 17, mais Olane ou Mara peuvent la lire si les PJ leur apportent le schéma. Si les PJ ont le cachet de Caldris des notes de Jaren (Scénario 1), la confirmation est immédiate. Elian Voss est le témoin le plus précieux du scénario — le tuer ferme la porte du Conseil."},texte_a_lire:`Sous un ancien amphithéâtre médical, une porte métallique. Derrière : des colonnes de dossiers, des bocaux opaques, une odeur de formol et de cire.

À gauche, cinquante dossiers étiquetés 'stabilisés'. À droite, sept bocaux sans étiquette. Sous une plaque amovible, deux dossiers cachés. L'un porte un schéma ancien. Le schéma nomme la Larme de Vael.`,objectif:"Récupérer le protocole S-01 complet et la liste des patients d'Elian Voss.",contexte_mj:{situation:"Elian Voss est un médecin de Caldris qui travaille avec Thade. Son laboratoire contient les dossiers des patients stabilisés par le protocole, les bocaux des échecs, et le schéma de la Larme de Vael — l'objet au cœur du rituel.",secrets:["Le schéma de la Larme porte une note barrée : 'Ne jamais alimenter cela avec des vivants.' Sealine a été la première — et la seule à avoir survécu au transit, avant de se sacrifier à Nyx.","Les sept bocaux contiennent les restes des sept échecs d'Elian après S-01 — des reproductions du protocole qui n'ont pas survécu au transit. Toutes ont échoué.","Elian Voss est présent si les PJ arrivent de jour. Il est effrayé et peut être retourné."],rappels:["Si les PJ ont le cachet de Caldris des notes de Jaren, la confirmation est immédiate.","Elian Voss n'est pas un fanatique. C'est un médecin qui a franchi la ligne par peur de Thade."]},defis:[{competence:"Art de la magie",dd:17,reussite:"Le sérum dans les bocaux est une préparation planaire. Il stabilise le corps pendant le transit vers la Spirale. Le protocole S-01 est une version améliorée.",echec:"Les bocaux contiennent un liquide alchimique complexe. Sa fonction exacte reste obscure."},{competence:"Décryptage",dd:17,reussite:"L'annotation de Sealine sur le schéma dit : 'Ne jamais alimenter cela avec des vivants.' Son écriture. Sa main.",echec:"L'annotation est ancienne et difficile à lire. Quelque chose sur des vivants."},{competence:"Intimidation",dd:14,reussite:"Elian Voss, terrifié, révèle tout : Thade a commandé le protocole, Caldris fournit le matériel, la Larme est le catalyseur.",echec:"Elian se tait. Il a plus peur de Thade que des PJ."}],indices:[{indice:"Le schéma de la Larme de Vael",localisation:"Dossier caché sous la plaque",detection:"Investigation DD 12",information:"La Larme est le catalyseur du rituel de seuil. Cachet de Caldris sur le schéma.",usage:"Comprendre que la Larme est l'objet central du plan de Thade."},{indice:"L'annotation de Sealine",localisation:"Schéma de la Larme",detection:"Décryptage DD 17",information:"'Ne jamais alimenter cela avec des vivants.' Écriture de Sealine.",usage:"Sealine savait. Elle a essayé d'empêcher Thade. Il l'a fait quand même."},{indice:"La liste des patients",localisation:"Cinquante dossiers 'stabilisés'",detection:"Lecture directe",information:"Cinquante patients stabilisés par des dérivés du protocole S-01, menés après Nyx. Sept échecs dans les bocaux.",usage:"Thade et Elian ont reproduit S-01 sur des vivants après Sealine."}],guide_mj:{intention:"Révéler l'ampleur des expériences de Thade et le rôle de la Larme de Vael.",mise_en_place:"Laboratoire sous amphithéâtre. Porte métallique. Odeur de formol.",deroulement:["Les PJ entrent.","Ils trouvent les dossiers et les bocaux.","Ils découvrent le schéma de la Larme.","Elian Voss est présent (de jour) ou absent (de nuit)."],actions_utiles:["Récupérer le protocole S-01.","Interroger Elian Voss.","Prendre les bocaux comme preuves.","Comparer avec les archives médicales."],fronts_heritiers:["Front 'Le Plan de Thade' — la Larme est le catalyseur.","Front 'Les Factions de la Crise' — Caldris est un acteur extérieur."],jeu_des_pnj:"Elian est un homme brisé. Il sait ce qu'il a fait. Il a peur de Thade et peur de lui-même.",escalade:"Si les PJ tuent Elian, ils perdent un témoin clé. S'ils le retournent, il peut témoigner au Conseil.",sortie:"Les PJ quittent le laboratoire avec le protocole, la Larme et la liste. Ils ont tout sauf la Tour."},reperes_de_jeu:{indice_indispensable:"Les PJ doivent savoir que la Larme de Vael est le catalyseur et que Thade et Elian ont reproduit S-01 sur des vivants après Sealine.",ne_pas_bloquer_sur_un_jet:"Le schéma de la Larme est visible sans jet. Le nom et le cachet sont lisibles.",question_dramatique:"Que vaut la vie de cinquante patients face à celle d'une femme qu'on aime ?"},transitions:{resume:"Les PJ quittent le laboratoire. Derrière eux, les bocaux restent dans l'obscurité.",reussite:"Les PJ ont le protocole, la Larme et un témoin. Prochaine étape : la Tour.",echec:"Les PJ ont trouvé le schéma sans comprendre le protocole. Olane ou Mara peuvent les aider à interpréter."}}]},{titre:"Acte III — La Confrontation",stake:"Les PJ confrontent Thade ou ses agents. La Tour s'active. Le déphasage s'accélère. La Spirale est à portée.",location:"Tour Arcanique, Centre Civique",scenes:[{id:"s2_assaut_tour",titre:"L'Assaut de la Tour",type:"Boss",resume_mj:"Les PJ montent la Tour Arcanique. Chaque étage est modifié : piliers de cristal, runes, objets en lévitation. Des étudiants charmés, des gardes piégés, des créatures planaires séduites par Thade. Chaque rencontre a une option non-létale. Le décompte des victimes compte pour l'épilogue.",idLieu:"tour_arcanique",idsPnj:["etudiants_charmes","gardes_pieges","creature_spirale_cooptee","magi_tuteur_loyal"],format_livre:{ambiance:"La Tour Arcanique se dresse au cœur de l'Université. De l'extérieur, elle semble normale — une flèche de pierre grise, des fenêtres étroites, un toit d'ardoise. Mais en franchissant le seuil, l'air change. Il sent la lavande et l'ozone. Les premiers étages sont banals — couloirs lambrissés, salles de cours vides, tableaux anciens. Mais à mesure qu'on monte, les murs changent. Des piliers de cristal poussent entre les pierres comme des racines inversées. Des runes brillent dans les angles, d'un bleu profond. Des objets flottent dans l'air — des livres, des plumes, des tasses, immobiles, comme suspendus dans du verre. Le bourdonnement du vortex au sommet est perceptible dès le troisième étage.",deroulement_narratif:`Les PJ montent étage par étage. Étages 1-2 : banals, transition. Des couloirs vides, des salles désertées. L'occasion de se préparer.

Étage 3 : étudiants charmés. Trois étudiants aux yeux vides. Ils lèvent les mains et lancent des sorts — Boule de feu, Rayon de givre. Persuasion DD 16 ou Dissipation de la magie pour les libérer sans violence. Ils se réveillent désorientés. Les tuer compte comme victime pour l'épilogue.

Étage 4 : gardes piégés et magi-tuteur loyal. Les gardes sont protégés par des runes explosives — les attaquer déclenche les runes. Discrétion DD 16 pour les éviter par les couloirs latéraux. Le magi-tuteur est un allié caché — il se présente si les PJ ne l'attaquent pas. Il peut expliquer la Tour, la cuve et le rituel au sommet.

Étage 5 : créature de la Spirale. Une entité cooptée par Thade — pas hostile par nature, mais prisonnière. Diplomatie DD 15 pour la retourner. Elle se retire si les PJ la traitent avec respect. Si elle attaque, elle est puissante mais ne veut pas mourir.

Étage 6 : ardoise. Investigation DD 10. Équation préliminaire de S-01, datée de sept ans. Thade travaillait déjà sur la théorie des seuils avant la disparition de Sealine. Mais le rituel actuel naît après Nyx, quand la recherche devient obsession.

Étage 7 : porte du Laboratoire de Verre. L'air sent la lavande à saturation. Le bourdonnement du vortex est audible. Derrière la porte : le corps de Thade dans la cuve.`,notes_mj:"5-6 rencontres tactiques. Chaque rencontre a une option non-létale. Le MJ doit tenir le décompte du nombre de victimes — ce décompte détermine le ton de l'épilogue du Scénario 3. Personne dans la Tour n'est un ennemi volontaire — sauf Thade. Les étudiants sont des victimes. La créature est une prisonnière. Le magi-tuteur est un allié. S'ils tuent tout, l'épilogue sera sombre. S'ils minimisent les victimes, l'épilogue peut être lumineux."},texte_a_lire:`La Tour Arcanique se dresse au cœur de l'Université. De l'extérieur, elle semble normale. De l'intérieur, elle est transformée. Les premiers étages sont banals — couloirs lambrissés, salles de cours. Mais plus vous montez, plus les murs changent. Des piliers de cristal poussent entre les pierres. Des runes brillent dans les angles. Des objets flottent dans l'air, immobiles.

Au troisième étage, un étudiant vous regarde avec des yeux vides. Il lève la main. Une boule de feu apparaît.`,objectif:"Atteindre le seuil du sommet en minimisant les victimes.",contexte_mj:{situation:"La Tour est un dispositif rituel. Chaque étage est modifié pour canaliser l'énergie vers le sommet. Thade a charmé des étudiants, piégé des gardes et coopté une créature de la Spirale. Les PJ doivent monter étage par étage.",secrets:["Chaque étudiant charmé peut être libéré avec Dissipation de la magie ou Persuasion DD 16. Les tuer compte comme victime pour l'épilogue.","La créature de la Spirale au 5e étage n'est pas hostile par nature. Elle a été séduite par Thade. Parler DD 15 peut la retourner.","Le magi-tuteur loyal au 4e étage est un allié caché. Il peut guider les PJ s'ils ne l'attaquent pas."],rappels:["5-6 rencontres tactiques. Chaque rencontre a une option non-létale.","Le décompte des victimes détermine le ton de l'épilogue."]},defis:[{competence:"Persuasion",dd:16,reussite:"Les PJ libèrent les étudiants charmés sans violence. Ils se réveillent désorientés mais vivants.",echec:"Les étudiants sont trop profondément charmés. Seul un combat ou Dissipation les arrête."},{competence:"Diplomatie",dd:15,reussite:"La créature de la Spirale accepte de se retirer. Elle n'est pas l'ennemie de Thade — elle est sa prisonnière.",echec:"La créature attaque. Elle est puissante mais ne veut pas mourir."},{competence:"Discrétion",dd:16,reussite:"Les PJ évitent deux rencontres en passant par les couloirs latéraux que Thade n'a pas modifiés.",echec:"Tous les couloirs mènent aux rencontres. Les PJ doivent combattre ou négocier."}],indices:[{indice:"L'ardoise du 6e étage",localisation:"Salle de cours désertée",detection:"Investigation DD 10",information:"Équation préliminaire de S-01 datée de sept ans. Les premières recherches de Thade sur les seuils précèdent la disparition de Sealine.",usage:"Les premières recherches de Thade sur les seuils précèdent la disparition de Sealine ; le rituel actuel, lui, naît de sa perte. Thade n'a pas dérapé par chagrin — il a choisi."}],guide_mj:{intention:"L'assaut de la Tour est la percée du Scénario 2 — pas l'apothéose. Les PJ atteignent le 7e étage, découvrent le corps de Thade et comprennent que le sommet est le vortex. Mais ils n'affrontent pas encore Thade dans le vortex : ils comprennent que le Scénario 3 commence maintenant.",mise_en_place:"La Tour est ouverte si les PJ ont un accès (Olane) ou forcée (Effraction/combat).",deroulement:["Étages 1-2 : banals, transition.","Étage 3 : étudiants charmés.","Étage 4 : gardes piégés + magi-tuteur loyal.","Étage 5 : créature de la Spirale.","Étage 6 : ardoise, preuve.","Étage 7 : porte du Laboratoire de Verre."],actions_utiles:["Libérer les étudiants charmés.","Parler à la créature planaire.","Trouver le magi-tuteur.","Lire l'ardoise du 6e."],fronts_heritiers:["Front 'Le Plan de Thade' — la Tour est le dispositif.","Front 'Le Sceau qui cède' — le rituel est proche."],jeu_des_pnj:"Les étudiants sont des victimes. La créature est une prisonnière. Le magi-tuteur est un allié. Personne dans la Tour n'est un ennemi volontaire — sauf Thade.",escalade:"Si les PJ tuent tout, l'épilogue sera sombre. S'ils minimisent les victimes, l'épilogue peut être lumineux.",sortie:"Les PJ atteignent la porte du Laboratoire de Verre. Derrière : le corps de Thade dans la cuve. Au-dessus : le sommet, le vortex, la Larme."},reperes_de_jeu:{indice_indispensable:"Les PJ doivent atteindre le 7e étage et savoir que le sommet contient le vortex.",ne_pas_bloquer_sur_un_jet:"Même si tous les jets échouent, les PJ peuvent combattre leur chemin vers le haut. Le coût est plus élevé.",question_dramatique:"Combien de victimes acceptable pour arrêter un homme qui ne veut pas être arrêté ?"},transitions:{resume:"Les PJ atteignent la porte du Laboratoire de Verre. L'air sent la lavande à saturation.",reussite:"Les PJ ont monté la Tour avec un minimum de victimes. Ils sont prêts pour le seuil du sommet.",echec:"Les PJ ont monté la Tour en force. Les victimes s'accumulent. L'épilogue sera sombre."}},{id:"s2_laboratoire_verre",titre:"Le Laboratoire de Verre",type:"Révélation",resume_mj:"Les PJ entrent dans le Laboratoire de Verre. Au centre : une cuve cylindrique en cristal. Dedans : le corps de Thade dans un liquide doré. Il est vivant, immobile, connecté à la Tour. Un mur de cahiers reliés bordeaux : Thade écrit à Sealine tous les jours depuis huit ans. La plume du cahier ouvert écrit en temps réel.",idLieu:"laboratoire_verre",idsPnj:["thade_coren","magi_tuteur_loyal"],format_livre:{ambiance:"La rotonde du 7e étage est baignée d'une lumière dorée qui n'a pas de source visible — elle émane des murs eux-mêmes, comme si la pierre avait absorbé huit ans de magie et ne savait plus comment ne pas briller. Une cuve cylindrique en cristal occupe le centre, douze mètres de diamètre, quatre mètres de haut. Le cristal est transparent — on voit tout. Dedans, un corps flotte dans un liquide doré, immobile. Thade Coren. Les yeux fermés. Le visage paisible. Des tubes l'alimentent — nutriments, mana, quelque chose de plus sombre. Des runes brillent sur la cuve, d'un or qui pulse lentement. L'air sent la lavande à saturation — pas un parfum, une présence. Le bourdonnement du vortex au sommet vibre dans les murs.",deroulement_narratif:`Sur le mur adjacent, des cahiers reliés bordeaux alignés par date. Des dizaines de cahiers. Huit ans de cahiers. Le dernier est ouvert sur un pupitre. Une plume écrit dedans, seule, en temps réel. L'écriture est fine, régulière, sans hésitation. Thade écrit depuis le vortex.

Si les PJ lisent le cahier ouvert, ils voient que Thade parle à Sealine comme si elle était là. Il raconte sa journée. Il décrit ce qu'il fait. Il dit qu'il est proche. Il dit qu'il va la ramener. Il ne sait pas qu'il a échoué. Ou il ne veut pas le savoir.

Investigation DD 12 : le système de la cuve est clair — tubes alimentaires, runes de préservation, connexion arcanique vers le sommet. Détruire la cuve interrompt la connexion entre Thade et le vortex. Connaissances (mystères) DD 16 : détruire le corps coûte une phase au Thade du sommet. Il sera affaibli mais pas arrêté.

Les PJ peuvent : détruire la cuve et le corps, lire les cahiers, écrire dans le cahier ouvert (Thade lira au sommet — c'est un canal de communication), ou emporter les cahiers comme preuve. Le magi-tuteur, s'il est présent, peut expliquer : « Son esprit est au sommet. Son corps est ici. La cuve maintient le lien. Détruisez le corps, et il sera plus faible là-haut. Mais il saura que vous êtes venus. »

La décision de détruire le corps est morale, pas mécanique. Les PJ regardent le visage paisible de Thade. Ils lisent les lettres à Sealine. Et ils doivent choisir : détruire le corps d'un homme qui écrit à sa femme tous les jours, ou monter au sommet sans avantage.`,notes_mj:"Aucun jet requis pour voir la cuve et les cahiers. Le corps de Thade est reconnaissable. La scène est le seuil du Scénario 3 — l'humanité de Thade révélée au moment où les PJ comprennent que l'affrontement final les attend au sommet. Si les PJ détruisent le corps, Thade au sommet perd une phase mais peut accélérer le rituel en représailles. Si les PJ écrivent dans le cahier, Thade peut répondre — c'est une dernière conversation avant le Scénario 3."},texte_a_lire:`La rotonde est baignée d'une lumière dorée. Une cuve cylindrique en cristal occupe le centre, douze mètres de diamètre. Dedans, un corps flotte dans un liquide doré. Thade Coren. Les yeux fermés. Le visage paisible. Des tubes l'alimentent. Des runes brillent sur la cuve.

Sur le mur adjacent, des cahiers reliés bordeaux alignés par date. Huit ans de cahiers. Le dernier est ouvert. Une plume écrit dedans, seule, en temps réel.`,objectif:"Décider quoi faire du corps de Thade dans la cuve.",contexte_mj:{situation:"Le corps de Thade est dans la cuve. Il est vivant mais immobile. Son esprit est au sommet de la Tour, dans le vortex. La cuve maintient son corps pendant que son esprit accomplit le rituel. Détruire le corps coûte une phase au Thade du sommet.",secrets:["Les cahiers sont des lettres à Sealine. Huit ans de lettres. Tous les jours. La plume écrit en temps réel — Thade écrit depuis le vortex.","Si les PJ lisent le cahier ouvert, ils voient que Thade parle à Sealine comme si elle était là. Il ne sait pas qu'il a échoué. Ou il ne veut pas le savoir.","Détruire le corps interrompt la connexion entre Thade et le vortex. Il perd une phase de puissance au sommet."],rappels:["Le magi-tuteur loyal peut expliquer la cuve si les PJ ne l'ont pas attaqué.","Si les PJ écrivent dans le cahier ouvert, Thade peut les lire au sommet. C'est un canal de communication."]},defis:[{competence:"Investigation",dd:12,reussite:"Le système de la cuve est clair : tubes alimentaires, runes de préservation, connexion arcanique vers le sommet. Détruire la cuve interrompt la connexion.",echec:"La cuve est complexe. Les runes sont inconnues. Difficile de savoir quoi faire."},{competence:"Connaissances (mystères)",dd:16,reussite:"Détruire le corps coûte une phase au Thade du sommet. Il sera affaibli mais pas arrêté.",echec:"Le lien entre la cuve et le sommet est arcanique et puissant. Difficile d'évaluer l'impact."}],indices:[{indice:"Les cahiers de Thade",localisation:"Mur du laboratoire",detection:"Lecture directe",information:"Huit ans de lettres à Sealine. Tous les jours. La plume écrit en temps réel.",usage:"Comprendre que Thade n'a jamais renoncé. Il parle à Sealine comme si elle était là."},{indice:"Le cahier ouvert",localisation:"Bureau adjacent",detection:"Lecture directe",information:"Thade écrit depuis le vortex. Le cahier est un canal de communication.",usage:"Les PJ peuvent écrire dans le cahier. Thade lira au sommet."}],guide_mj:{intention:"Révéler la vérité humaine de Thade. Il n'est pas un monstre distant. Il est un homme qui écrit à sa femme tous les jours depuis huit ans.",mise_en_place:"Rotonde de pierre claire. Cuve centrale. Lumière dorée. Parfum de lavande.",deroulement:["Les PJ entrent et voient la cuve.","Ils examinent le corps de Thade.","Ils découvrent les cahiers.","Ils décident : détruire le corps, lire les cahiers, ou écrire dans le cahier ouvert."],actions_utiles:["Détruire la cuve et le corps.","Lire les cahiers.","Écrire à Thade dans le cahier.","Emporter les cahiers comme preuve."],fronts_heritiers:["Front 'Le Plan de Thade' — le corps est le point faible.","Front 'Le Sceau qui cède' — le rituel est en cours au sommet."],jeu_des_pnj:"Le magi-tuteur peut expliquer. Sinon, les cahiers parlent pour Thade.",escalade:"Si les PJ détruisent le corps, Thade au sommet perd une phase. Mais il peut accélérer le rituel en représailles.",sortie:"Les PJ quittent le laboratoire. La porte du sommet est devant eux. L'air sent la lavande à saturation. Le bourdonnement du vortex est audible."},reperes_de_jeu:{indice_indispensable:"Les PJ doivent savoir que le corps de Thade est dans la cuve et que le détruire affaiblit Thade au sommet.",ne_pas_bloquer_sur_un_jet:"La cuve et les cahiers sont visibles sans jet. Le corps de Thade est reconnaissable.",question_dramatique:"Pouvez-vous détruire le corps d'un homme qui écrit à sa femme tous les jours ?"},transitions:{resume:"Les PJ se tournent vers la porte du sommet. Le bourdonnement du vortex les appelle. Ils n'ont pas encore affronté Thade — mais ils savent maintenant que le Scénario 3 commence de l'autre côté de cette porte.",reussite:"Les PJ ont détruit le corps ou lu les cahiers. Ils se tiennent au seuil du sommet. Le Scénario 3 commence.",echec:"Les PJ ont vu la cuve sans agir. Ils se présentent au seuil du sommet sans avantage."}}]}]},o={id:"scenario3",titre:"La Dame de la Spirale",niveau:"Niveaux 9-12 · 4-6 séances · Acte III de la trilogie",vue_ensemble:{ton:"Apothéose tragique. Le thriller devient affrontement moral. L'horreur devient choix. Le ton est grave, lent, définitif — chaque mot compte parce que c'est le dernier. Pas de rebondissement : les PJ savent tout. Reste à décider. Et le prix de chaque décision est irréversible.",themes:["L'amour comme catastrophe — Thade fait tout cela par amour. L'amour n'excuse rien, mais il explique tout.","La vérité comme arme — les révélations accumulées pendant la campagne sont les armes les plus puissantes contre Thade. Les cahiers, l'annotation, les patients, les bocaux.","Le choix irréversible — trois options, chacune avec un prix. Aucune option n'est pure. Aucune n'est sans prix. Le choix appartient aux PJ.","L'épilogue comme miroir — le monde d'après reflète les alliances, les victimes et la décision finale. La campagne se termine sur ce que les PJ ont fait, pas sur ce qu'ils ont voulu."],question_dramatique:"Quand un homme a détruit un monde par amour, pouvez-vous le juger sans détruire ce qu'il aime ? Et si vous sauvez ce qu'il aime, que devient le monde ?",structure_narrative:[{phase:"1. Entrée dans le vortex",resume:"Les PJ franchissent la porte du sommet. Le ciel est violet. Le vortex bourdonne. Thade est là, les mains tendues vers la Larme. Pas de retour possible."},{phase:"2. Combat contre Thade / vérités comme armes",resume:"Thade combat pour gagner du temps, pas pour tuer. Trois phases : Archimage Épuisé, Larme se Fissure, Épuisement. Chaque vérité sur Sealine fissure la Larme. Les PJ peuvent gagner par la parole autant que par la force."},{phase:"3. Conversation avec Sealine",resume:"Sealine apparaît dans le vortex. Calme, lucide, présente. Elle sait tout. Elle ne demande rien. Elle explique les trois options et leurs prix. Le choix appartient aux PJ."},{phase:"4. Choix final",resume:"Détruire la Larme (Sealine est perdue, le sceau se referme), détacher la Larme sans la briser (le seuil filtre, la Spirale persiste, Sealine revient), ou laisser Thade ouvrir le seuil (la Spirale déferle, le monde est transformé). Aucune option n'est pure. Aucune n'est sans prix."},{phase:"5. Épilogue variable",resume:"Le monde d'après. Le MJ décrit les conséquences sur Valombre, les PNJ survivants, le ciel, les routes. Le décompte des victimes de la Tour détermine le ton. La campagne se termine sur ce que les PJ ont fait."}],pnj_cles:[{id:"thade_coren",nom:"Thade Coren",role:"Archimage au sommet. Combat par amour, pas par cruauté. Chaque vérité le blesse plus qu'un sort. S'effondre à la phase 3."},{id:"sealine_coren",nom:"Sealine Vael",role:"La Dame de la Spirale. Apparaît dans le vortex. Calme, triste, lucide. Sait tout. Ne demande rien. Accepte le choix des PJ."},{id:"magi_tuteur_loyal",nom:"Le Magi-Tuteur loyal",role:"Allié possible au sommet. Peut intervenir si les PJ ne l'ont pas attaqué dans la Tour. Témoin de la fin."}],lieux_cles:[{id:"sommet_tour_vortex",nom:"Sommet de la Tour Arcanique",role:"Plateforme circulaire, marbre clair, ciel violet. Le vortex au centre. La Larme au cœur. Le lieu du combat final et du choix."},{id:"place_fondation",nom:"Place de la Fondation",role:"Lieu de l'épilogue. Les gens se rassemblent. Le ciel change. Le monde d'après commence ici."}],ce_que_les_pj_savent:["Thade est dans le vortex au sommet de la Tour. Son corps est dans la cuve au 7e étage.","La Larme de Vael est le catalyseur du rituel. Elle est au cœur du vortex.","Thade et Elian ont reproduit S-01 sur des vivants après Sealine. Sealine a essayé de l'empêcher.","Les cahiers bordeaux : Thade écrit à Sealine tous les jours depuis huit ans.","Le décompte des victimes de la Tour déterminera le ton de l'épilogue."],ce_que_les_pj_doivent_decouvrir:["Les vérités accumulées pendant la campagne sont des armes. Chaque vérité sur Sealine fissure la Larme.","Sealine est présente dans le vortex. Elle est lucide. Elle sait tout.","Le choix final a trois options, chacune avec un prix irréversible.","Aucune option n'est pure. Aucune n'est sans prix. Il y a seulement le choix que les PJ assument."]},revelations_indispensables:[{id:"rev_verites_armes",titre:"Les vérités accumulées sont des armes",resume:"Chaque vérité découverte pendant la campagne — l'annotation de Sealine, les 50 patients d'Elian, les 7 bocaux, les cahiers bordeaux, les 142 consultations — fissure la Larme de Vael pendant le combat contre Thade. Les PJ peuvent gagner la phase 2 sans combattre, en parlant. Les vérités sont plus puissantes que les sorts.",sources:["Cahiers bordeaux du Laboratoire de Verre (Scénario 2, Acte III).","Annotation de Sealine sur le schéma de la Larme (Scénario 2, Acte II).","Dossiers des patients et bocaux du laboratoire d'Elian Voss (Scénario 2, Acte II).","Registre des 142 consultations de la Réserve Interdite (Scénario 2, Acte II)."],declencheur:"Persuasion DD 18 pour lire un extrait des cahiers ou révéler une vérité à Thade pendant le combat. Chaque vérité réussie fissure la Larme.",plan_b:"Si les PJ n'ont pas les preuves matérielles, ils peuvent citer de mémoire ce qu'ils ont vu. Le MJ accorde un avantage de circonstance si les PJ décrivent ce qu'ils ont découvert. Le magi-tuteur peut aussi témoigner.",consequence_si_ratee:"Les PJ doivent vaincre Thade par la force seule. La phase 2 est plus longue et plus dangereuse. La Larme ne se fissure pas — le combat va jusqu'à l'épuisement de Thade."},{id:"rev_sealine_presente",titre:"Sealine est présente dans le vortex",resume:"Sealine n'est pas un souvenir. Elle est là, dans le vortex, lucide et présente. Elle sait ce que Thade a fait. Elle sait ce qu'elle coûte. Elle ne demande rien — elle accepte. C'est elle qui explique les trois options aux PJ. C'est elle qui dit : « Vous devez décider. Pas lui. Pas moi. Vous. »",sources:["Le vortex au sommet de la Tour (Scénario 3, phase 3 du combat).","Sealine elle-même, quand elle apparaît après l'effondrement de Thade."],declencheur:"Automatique à la fin de la phase 3. Sealine apparaît que les PJ aient fissuré la Larme ou non.",plan_b:"Aucun plan B nécessaire. Sealine apparaît dans tous les cas. La question n'est pas si elle apparaît, mais ce que les PJ font de sa présence.",consequence_si_ratee:"Si les PJ attaquent Sealine ou ignorent sa présence, elle se retire dans le vortex. Le choix final devient plus confus — les PJ doivent décider sans ses explications. Le prix de chaque option est moins clair."},{id:"rev_trois_options",titre:"Le choix final a trois options, chacune avec un prix",resume:"Détruire la Larme : Sealine est perdue, le sceau se referme, Valombre revient à la normale avec ses cicatrices. Détacher la Larme sans la briser : le seuil filtre, la Spirale persiste, Sealine revient fragile, Valombre apprend à vivre avec. Laisser Thade ouvrir le seuil : la Spirale déferle, Valombre est transformée, Thade rejoint Sealine — ou croit enfin l'atteindre. Le monde est différent. Aucune option n'est pure. Aucune n'est sans prix.",sources:["Sealine explique les trois options pendant la conversation à trois.","Art de la magie DD 18 pour analyser le vortex et confirmer les conséquences."],declencheur:"La conversation à trois (Scénario 3, scène 2). Sealine présente les options. Les PJ choisissent.",plan_b:"Si les PJ n'ont pas parlé à Sealine, le magi-tuteur ou Olane (par communication magique) peut expliquer les options. Mais l'explication est moins complète et moins personnelle.",consequence_si_ratee:"Si les PJ hésitent trop longtemps, le rituel s'accomplit seul. Le seuil s'ouvre. La Spirale déferle. C'est l'option 3 sans choix conscient — le pire scénario, car les PJ n'ont pas décidé."},{id:"rev_decompte_victimes",titre:"Le décompte des victimes détermine le ton de l'épilogue",resume:"Le MJ a compté les victimes de la Tour pendant le Scénario 2. Étudiants charmés tués au lieu d'être libérés. Gardes piégés tués au lieu d'être évités. Créature de la Spirale tuée au lieu d'être retournée. Ce décompte détermine le ton de l'épilogue : lumineux, nuancé ou sombre. Valombre se souvient de ce que les PJ ont fait.",sources:["Le décompte tenu par le MJ pendant l'Assaut de la Tour (Scénario 2, Acte III).","Les PNJ survivants réagissent en fonction du décompte pendant l'épilogue."],declencheur:"Automatique pendant la scène d'épilogue (Scénario 3, scène 3).",plan_b:"Aucun plan B. Le décompte est ce qu'il est. Si le MJ n'a pas tenu de décompte, il évalue globalement : peu de victimes, moyen, ou beaucoup.",consequence_si_ratee:"Pas applicable. Le décompte n'est pas un jet — c'est un constat. Les conséquences sont narratives, pas mécaniques."}],fronts_actifs:[{id_front:"front_plan_thade",nom:"Le Plan de Thade — accomplissement",etat_initial:"Thade est au sommet de la Tour, connecté au vortex. La Larme de Vael est au cœur du vortex. Le rituel est en cours. Le ciel de Valombre vire au violet. L'horloge est à l'étape finale — si personne n'arrête Thade, le seuil s'ouvre.",manifestation_scenarios:"Le vortex bourdonne au sommet. Le ciel est violet. Le déphasage devient général. Des créatures de la Spirale apparaissent dans la Tour. Les routes de Valombre ne sont plus fiables.",interactions_scenes:[{scene:"Le Vortex",interaction:"Le combat contre Thade est le front. Chaque round rapproche le rituel de son accomplissement. Chaque vérité sur Sealine fissure la Larme et ralentit le rituel. Si les PJ détruisent le corps dans la cuve (Scénario 2), Thade est affaibli d'une phase."},{scene:"La Conversation à Trois",interaction:"Le front se résout ici. Le choix des PJ détermine l'issue : le rituel s'arrête (Larme détruite), le rituel est partiellement accompli (Sealine sauvée), ou le rituel s'accomplit totalement (seuil ouvert)."}],leviers_pj_scenario:"Les PJ peuvent : combattre Thade pour gagner du temps, utiliser les vérités comme armes pour fissurer la Larme, détruire le corps dans la cuve pour affaiblir Thade, ou parler à Sealine pour comprendre les options avant de choisir."},{id_front:"front_sceau_qui_cede",nom:"Le Sceau qui cède",etat_initial:"Le sceau des Sept Thanes est au bord de la rupture. Les prélèvements, le rite inversé d'Edran Morn, et le rituel de Thade ont accumulé les fissures. Si le rituel s'accomplit, le sceau cède entièrement. Si la Larme est détruite, le sceau se referme. Si Sealine est sauvée, le sceau reste entrouvert.",manifestation_scenarios:"Les zones déphasées sont maintenant générales. Les routes mentent partout. Le ciel est violet. Les tombes des Thanes craquent. Les filaments planaires sont visibles dans toute la ville.",interactions_scenes:[{scene:"Le Vortex",interaction:"Le combat accélère ou ralentit la fissuration. Chaque vérité qui fissure la Larme ralentit le rituel. Chaque round perdu accélère le sceau vers la rupture."},{scene:"Le Monde d'Après",interaction:"Le sort du sceau est révélé dans l'épilogue. Si la Larme est détruite, les tombes sont restaurées. Si Sealine est sauvée, le sceau reste entrouvert. Si le seuil s'ouvre, le sceau n'existe plus — la Spirale et Valombre fusionnent."}],leviers_pj_scenario:"Les PJ ne peuvent pas agir directement sur le sceau au Scénario 3. Le sort du sceau dépend entièrement du choix final. Les actions des Scénarios 1 et 2 (restauration des rites, arrêt du rite d'Edran) déterminent l'état initial du sceau au début du Scénario 3."},{id_front:"front_cite_sous_pression",nom:"La Cité sous pression",etat_initial:"Valombre est en état d'urgence. Le déphasage général paralyse les routes. La garde est débordée. Le Conseil est impuissant. Les factions — Champion, Endeuillés, Résistance — attendent l'issue. Le ciel violet terrifie la population. L'horloge est à l'étape finale.",manifestation_scenarios:"Les rues sont vides. Les gens se barricadent. Le Champion harangue une foule terrifiée. Les Endeuillés, s'ils n'ont pas été dispersés, attendent le retour des morts. Mara et la Résistance préparent l'après.",interactions_scenes:[{scene:"Le Monde d'Après",interaction:"L'épilogue montre ce que devient la cité. Le Champion est discrédité ou renforcé selon le choix. Les Endeuillés se dispersent ou trouvent la paix. Mara reconstruit. Olane réforme. Thorgar restaure. Le décompte des victimes détermine si la cité fait confiance aux PJ ou les craint."}],leviers_pj_scenario:"Les PJ n'agissent pas sur la cité pendant le combat final. Leur influence sur la cité se manifeste dans l'épilogue, à travers les alliances construites pendant les Scénarios 1 et 2 et le décompte des victimes de la Tour."}],scenes_structure:{legende:{obligatoire:"La scène doit être jouée. Le scénario ne peut pas se terminer sans elle.",obligatoire_flexible:"La scène doit être jouée, mais son contenu peut être adapté ou déplacé.",optionnel:"La scène peut être ignorée, mais elle enrichit l'expérience et peut fournir des indices ou alliés."},scenes:[{titre:"Le Vortex",acte:"Acte I",statut:"obligatoire",axe:"Cosmique",dependances:["L'Assaut de la Tour (Scénario 2)","Le Laboratoire de Verre (Scénario 2)"],revele:["Les vérités comme armes","La Larme est le catalyseur","Thade combat par amour, pas par cruauté"],note:"Le combat se déroule en 3 phases. Si les PJ ont détruit le corps dans la cuve, Thade est affaibli. Si les PJ ont les cahiers, ils peuvent les lire à Thade."},{titre:"La Conversation à Trois",acte:"Acte I",statut:"obligatoire",axe:"Moral",dependances:["Le Vortex (Thade doit être vaincu ou affaibli)"],revele:["Sealine est présente et lucide","Les trois options et leurs prix","Le choix appartient aux PJ"],note:"Aucun jet. C'est une conversation et un choix. Sealine ne demande rien — elle accepte. Thade est brisé et ne combat plus."},{titre:"Le Monde d'Après",acte:"Acte II",statut:"obligatoire",axe:"Épilogue",dependances:["La Conversation à Trois (le choix final doit être fait)"],revele:["Les conséquences du choix sur Valombre","Le sort des PNJ survivants","Le ton de l'épilogue selon le décompte des victimes"],note:"Narration pure. Pas de jets. Le MJ décrit les conséquences selon le choix, les alliances et le décompte. La campagne se termine ici."}]},synopsis:"Tout converge au sommet de la Tour Arcanique. Thade est dans le vortex, la Larme de Vael au creux de ses mains. La Spirale est à portée. Sealine l'attend de l'autre côté. Les PJ doivent monter, affronter l'archimage et décider : détruire la Larme, sauver Sealine, ou laisser Thade ouvrir le seuil. Chaque choix a un prix. La campagne se joue ici.",evenements_mondiaux:{chronologie_inevitable:["Le vortex s'ouvre au sommet de la Tour. Le ciel de Valombre vire au violet.","Le déphasage devient général. Les routes de Valombre ne sont plus fiables.","La Spirale filtre par le vortex. Des créatures et des échos apparaissent dans la Tour.","Si personne n'arrête le rituel, le seuil s'ouvre. La Spirale et Valombre fusionnent."],consequences_echecs:["Si les PJ tardent : le rituel s'accomplit. Le seuil s'ouvre. Valombre et la Spirale fusionnent.","Si les PJ détruisent la Larme sans parler à Sealine : Sealine est perdue. Thade devient un archimage brisé et dangereux.","Si les PJ laissent Thade ouvrir le seuil : la Spirale déferle. Valombre est transformée. Thade franchit le seuil vers Sealine, mais ce qu'elle fera de lui appartient à l'épilogue. À quel prix ?","Si les PJ tuent Thade sans résoudre la Larme : le vortex s'effondre. Le sceau se referme. Mais la Larme reste, et quelqu'un d'autre la trouvera."]},actes:[{titre:"Acte I — Le Sommet",stake:"Les PJ atteignent le sommet de la Tour et affrontent Thade dans le vortex.",location:"Sommet de la Tour Arcanique",scenes:[{id:"s3_vortex",titre:"Le Vortex",type:"Boss",resume_mj:"Les PJ atteignent le sommet. Plateforme circulaire, marbre clair, ciel violet. Au centre, le vortex : puits horizontal d'énergie. Au cœur, la Larme de Vael. Thade se tient devant, les mains tendues. Le combat se déroule en 3 phases : Archimage Épuisé, Larme se Fissure, Épuisement.",idLieu:"sommet_tour_vortex",idsPnj:["thade_coren","sealine_coren","magi_tuteur_loyal"],format_livre:{ambiance:"Le sommet de la Tour Arcanique est une plateforme circulaire de marbre clair, ouverte sur le ciel. Pas de murs. Pas de toit. Le ciel est violet — pas le violet du crépuscule, un violet qui n'a rien à voir avec l'heure. L'air bourdonne. Pas un vent — une vibration, basse, continue, qui monte du centre de la plateforme. Au centre, le vortex : un puits horizontal d'énergie violette, tourbillonnant, qui ne mène nulle part et partout à la fois. Au cœur du vortex, quelque chose brille. Une larme. La Larme de Vael. Le sol est chaud sous les pieds. Les runes gravées dans le marbre brillent d'un or qui pulse au rythme du bourdonnement.",deroulement_narratif:`Thade se tient devant le vortex. Ses mains sont tendues. Son visage est paisible. Il ne regarde pas les PJ — il regarde le vortex. « Vous êtes venus », dit-il. « Je le savais. Je savais que vous viendriez. » Une pause. Puis : « Elle m'attend. »

Phase 1 — Archimage Épuisé : Thade combat avec des sorts puissants mais il est épuisé par le rituel. Ses attaques sont prévisibles — Boule de feu, Rayon de givre, Mur de force. Il ne cherche pas à tuer. Il cherche à gagner du temps. Chaque round qu'il gagne rapproche le rituel de son accomplissement. Les PJ peuvent le combattre ou tenter de parler.

Phase 2 — Larme se Fissure : Si les PJ ont détruit le corps dans la cuve, ou s'ils révèlent une vérité sur Sealine (les cahiers, l'annotation, les expériences, les patients, les bocaux), la Larme se fissure. Persuasion DD 18 pour lire un extrait des cahiers ou révéler une vérité. Chaque vérité réussie fissure la Larme un peu plus. Thade devient désespéré et imprévisible — ses sorts sont moins contrôlés, plus puissants, plus dangereux.

Phase 3 — Épuisement : Thade s'effondre sur le marbre. Le vortex vacille. La Larme est fissurée mais pas détruite. Une forme se dessine dans l'énergie violette. Sealine. La conversation à trois commence.

Si les PJ ont le magi-tuteur avec eux, il peut intervenir à la phase 2 — il dit à Thade : « Maître, arrêtez. Elle ne voudrait pas ça. » Thade hésite un round. Si les PJ ont détruit le corps dans la cuve (Scénario 2), Thade perd une phase de puissance — il passe directement à la phase 2 après 2 rounds au lieu de 4.`,notes_mj:"Le combat n'est pas un combat standard — c'est une course contre le rituel. Le MJ doit tenir le décompte du nombre de rounds. Au round 5, le rituel est à moitié accompli. Au round 10, le rituel s'accomplit. Les PJ ne le savent pas exactement, mais le bourdonnement du vortex augmente d'intensité à chaque round. Les vérités sont les armes les plus puissantes : chaque vérité réussie (Persuasion DD 18) compte comme 2 rounds de combat. Les PJ peuvent gagner la phase 2 sans combattre — en parlant."},texte_a_lire:`Le sommet de la Tour est ouvert sur le ciel. Le marbre est clair, presque blanc. L'air bourdonne. Un vortex se déploie au centre de la plateforme — un puits horizontal d'énergie violette, tourbillonnant, qui ne mène nulle part et partout à la fois. Au cœur du vortex, quelque chose brille. Une larme. La Larme de Vael.

Thade se tient devant le vortex. Ses mains sont tendues. Son visage est paisible. Il ne vous regarde pas. Il regarde le vortex.

« Vous êtes venus », dit-il. « Je le savais. Je savais que vous viendriez. »

Une pause. Puis : « Elle m'attend. »`,objectif:"Arrêter le rituel de Thade et décider du sort de la Larme de Vael.",contexte_mj:{situation:"Thade est au sommet, connecté au vortex. La Larme de Vael est au cœur du vortex. Le rituel est en cours. Le combat se déroule en 3 phases. Chaque vérité sur Sealine fissure la Larme.",secrets:["Phase 1 — Archimage Épuisé : Thade combat avec des sorts puissants mais il est épuisé par le rituel. Ses attaques sont prévisibles.","Phase 2 — Larme se Fissure : Si les PJ ont détruit le corps dans la cuve, ou s'ils révèlent une vérité sur Sealine (les cahiers, l'annotation, les expériences), la Larme se fissure. Thade devient désespéré et imprévisible.","Phase 3 — Épuisement : Thade s'effondre. Le vortex vacille. Sealine peut apparaître. La conversation à trois commence.","Chaque vérité sur Sealine (l'annotation 'ne jamais alimenter avec des vivants', les 50 patients, les 7 bocaux) fissure la Larme un peu plus. Les PJ peuvent utiliser les vérités comme armes."],rappels:["Thade ne veut pas tuer les PJ. Il veut les retarder. Chaque round qu'il gagne rapproche le rituel de son accomplissement.","Si les PJ ont les cahiers du Laboratoire de Verre, ils peuvent les lire à Thade. Chaque lettre fissure la Larme.","Le magi-tuteur loyal peut intervenir si les PJ ne l'ont pas attaqué dans la Tour."]},defis:[{competence:"Athlétisme",dd:15,reussite:"Les PJ se frappent un chemin vers le vortex à travers les vents planaires.",echec:"Les vents repoussent les PJ. Ils doivent trouver une autre approche."},{competence:"Persuasion",dd:18,reussite:"Les PJ lisent un extrait des cahiers ou révèlent une vérité sur Sealine. La Larme se fissure. Thade vacille.",echec:"Thade refuse d'écouter. « Vous ne comprenez pas. Vous n'avez jamais perdu quelqu'un. »"},{competence:"Art de la magie",dd:18,reussite:"Les PJ identifient la structure du vortex. La Larme est le catalyseur. La retirer arrête le rituel mais libère l'énergie accumulée.",echec:"Le vortex est trop complexe. Impossible de savoir quoi faire sans risquer une catastrophe."}],indices:[{indice:"Les vérités comme armes",localisation:"Cahiers, archives, laboratoire",detection:"Connaissances accumulées",information:"Chaque vérité sur Sealine fissure la Larme. L'annotation, les patients, les bocaux, les cahiers.",usage:"Les PJ peuvent gagner la phase 2 sans combattre — en parlant."},{indice:"La Larme de Vael",localisation:"Cœur du vortex",detection:"Art de la magie DD 18",information:"La Larme est le catalyseur. La retirer arrête le rituel. La détruire libère l'énergie. La laisser ouvre le seuil.",usage:"Le choix final dépend de ce que les PJ font de la Larme."}],guide_mj:{intention:"Le combat final. 3 phases. Les vérités sur Sealine sont les armes les plus puissantes.",mise_en_place:"Sommet ouvert. Ciel violet. Vortex. Thade devant. Larme au centre.",deroulement:["Phase 1 : combat arcanique. Thade puissant mais épuisé.","Phase 2 : la Larme se fissure. Les PJ utilisent les vérités.","Phase 3 : Thade s'effondre. Le vortex vacille. Sealine apparaît."],actions_utiles:["Combattre Thade.","Lire les cahiers à voix haute.","Révéler les vérités sur Sealine.","Tenter de détacher la Larme du vortex."],fronts_heritiers:["Tous les fronts convergent ici."],jeu_des_pnj:"Thade ne combat pas par cruauté. Il combat parce que Sealine l'attend. Chaque vérité le blesse plus qu'un sort. Sealine, si elle apparaît, est calme, triste, lucide.",escalade:"Si les PJ tardent, le rituel s'accomplit. Le seuil s'ouvre. La Spirale déferle.",sortie:"Thade s'effondre. Le vortex vacille. Sealine apparaît dans le vortex. La conversation à trois commence."},reperes_de_jeu:{indice_indispensable:"Les PJ doivent savoir que les vérités sur Sealine fissurent la Larme et que la Larme est le catalyseur.",ne_pas_bloquer_sur_un_jet:"Même si tous les jets échouent, le combat se déroule. Les PJ peuvent combattre Thade jusqu'à l'épuisement.",question_dramatique:"Pouvez-vous arrêter un homme qui ne fait tout cela que par amour ?"},transitions:{resume:"Thade s'effondre sur le marbre. Le vortex vacille. Une forme apparaît dans l'énergie violette.",reussite:"Les PJ ont vaincu Thade et fissuré la Larme. Sealine apparaît.",echec:"Les PJ ont vaincu Thade par la force, sans fissurer la Larme. Le vortex est instable. Sealine apparaît, mais la situation est plus dangereuse."}},{id:"s3_conversation_trois",titre:"La Conversation à Trois",type:"Dilemme",resume_mj:"Sealine apparaît dans le vortex. Elle est calme, lucide, présente. Elle parle aux PJ et à Thade. Elle sait ce que Thade a fait. Elle sait ce qu'elle coûte. La conversation n'est pas un combat — c'est un choix. Trois options : détruire la Larme (Sealine est perdue, le sceau se referme), détacher la Larme sans la briser (le seuil reste entrouvert, la Spirale filtre, Sealine revient), ou laisser Thade ouvrir le seuil (la Spirale déferle, Thade franchit le seuil vers Sealine, Valombre est transformée).",idLieu:"sommet_tour_vortex",idsPnj:["thade_coren","sealine_coren"],format_livre:{ambiance:"Le vortex vacille. Le bourdonnement a diminué — pas disparu, mais atténué. Le ciel violet est toujours là, mais il tremble, comme s'il hésitait. Le marbre sous les pieds est chaud. Thade est au sol, genoux pliés, mains ouvertes. Il ne combat plus. Il regarde le vortex. La forme qui se dessine dans l'énergie violette prend des détails — une femme, des cheveux sombres, un visage calme, des vêtements simples. Elle ressemble à quelqu'un qui préparait le thé quand tout a basculé. L'air sent la lavande. Pas un parfum — une présence.",deroulement_narratif:`Sealine se matérialise dans le vortex. Elle ne flotte pas — elle se tient, comme si le vortex était une fenêtre et elle de l'autre côté. Elle regarde Thade. Elle regarde les PJ. Elle est calme.

« Thade », dit-elle. Thade lève la tête. Ses yeux sont brisés. « Sealine. » « Je sais », dit-elle. « Je sais tout. Les patients. Les bocaux. La Larme. Je sais. » Un silence. Puis : « Et je sais pourquoi. »

Elle se tourne vers les PJ. « Vous devez décider. Pas lui. Pas moi. Vous. »

Sealine explique les trois options avec une clarté tranquille :
1. Détruire la Larme. Le sceau se referme. Le déphasage s'arrête. Sealine disparaît. Thade est brisé mais vivant. Valombre revient à la normale — avec ses cicatrices.
2. Détacher la Larme : extraire la Larme du vortex sans la briser. Sealine revient, fragile. Le seuil reste entrouvert. La Spirale filtre de manière permanente. Valombre apprend à vivre avec. Thade est jugé mais pas exécuté.
3. Laisser Thade ouvrir le seuil. La Spirale déferle. Valombre et la Spirale fusionnent. Le ciel reste violet. Les routes mènent partout et nulle part. Thade franchit le seuil vers Sealine — mais ce qu'elle fera de lui appartient à l'épilogue. Le monde est différent. Pas meilleur, pas pire — différent.

Les PJ peuvent parler à Sealine et à Thade avant de choisir. Sealine répond avec une honnêteté absolue. Thade ne parle que si on lui adresse la parole. Il dit : « Je voulais la ramener. C'est tout. Je voulais la ramener. »

Aucun jet. C'est une conversation et un choix. Le MJ laisse le silence s'installer après les explications. Les PJ décident quand ils sont prêts.`,notes_mj:"Le MJ ne pousse pas les PJ vers une option. Les trois sont valides. Le MJ décrit les conséquences avec la même neutralité pour chaque option. Si les PJ hésitent, le MJ applique trois avertissements : 1) Le vortex pulse, la Larme brille plus fort. 2) Sealine prévient : « Le choix ne peut pas attendre. » 3) Thade tente de reprendre le contrôle ou la Larme s'ouvre d'elle-même. Après le troisième avertissement, le rituel s'accomplit seul — c'est l'option 3 sans choix conscient."},texte_a_lire:`Une forme se dessine dans le vortex. D'abord un contour, puis des détails. Une femme. Cheveux sombres, visage calme, yeux qui ont vu plus que ce qu'un visage devrait porter. Elle porte des vêtements simples — une robe de maison, des chaussures plates. Elle ressemble à quelqu'un qui préparait le thé quand tout a basculé.

« Thade », dit-elle.

Thade lève la tête. Ses yeux sont brisés. « Sealine. »

« Je sais », dit-elle. « Je sais tout. Les patients. Les bocaux. La Larme. Je sais. »

Un silence. Puis : « Et je sais pourquoi. »

Elle se tourne vers vous. « Vous devez décider. Pas lui. Pas moi. Vous. »`,objectif:"Décider du sort de la Larme, de Sealine, de Thade et de Valombre.",contexte_mj:{situation:"Sealine est présente dans le vortex. Elle est lucide. Elle sait tout. Elle n'accuse pas Thade, mais elle ne veut pas qu'il ouvre le seuil. Le choix appartient aux PJ.",secrets:["Sealine sait que Thade et Elian ont reproduit S-01 sur des vivants après elle. Elle lui pardonne mais ne l'absout pas.","Si les PJ détruisent la Larme, Sealine disparaît. Le sceau se referme. Thade est brisé mais vivant.","Si les PJ sauvent Sealine (détacher la Larme sans la briser), le seuil s'ouvre partiellement. La Spirale filtre de manière permanente. Sealine revient mais Valombre est changée.","Si les PJ laissent Thade ouvrir le seuil, la Spirale déferle. Valombre et la Spirale fusionnent. Thade franchit le seuil vers Sealine, mais le monde est transformé."],rappels:["Aucune option n'est pure. Aucune n'est sans prix.","Sealine ne demande rien. Elle accepte ce que les PJ décident.","Thade est brisé. Quelle que soit la décision, il ne combat plus."]},guide_mj:{intention:"Le choix final. Pas de combat. Une conversation. Le prix de chaque option doit être clair.",mise_en_place:"Sommet. Vortex vacillant. Sealine dans le vortex. Thade au sol. Les PJ debout.",deroulement:["Sealine parle aux PJ.","Elle explique les trois options.","Les PJ discutent entre eux et avec Thade.","Les PJ choisissent."],actions_utiles:["Détruire la Larme.","Détacher la Larme sans la briser.","Laisser Thade ouvrir le seuil.","Parler à Sealine et à Thade avant de choisir."],fronts_heritiers:["Tous les fronts se résolvent ici."],jeu_des_pnj:"Sealine est calme, triste, lucide. Elle ne pleure pas. Elle a pleuré tout ce qu'elle pouvait pleurer. Thade est brisé. Il ne parle que si on lui adresse la parole.",escalade:"Pas d'escalade. C'est une conversation, pas un combat.",sortie:"Les PJ font leur choix. Les conséquences se déploient dans la scène d'épilogue."},reperes_de_jeu:{indice_indispensable:"Les PJ doivent comprendre les trois options et leurs conséquences.",ne_pas_bloquer_sur_un_jet:"Aucun jet. C'est une conversation et un choix.",question_dramatique:"Que choisissez-vous quand aucune issue ne vous laisse innocent ?"},transitions:{resume:"Les PJ font leur choix. Le vortex réagit. Le monde change.",reussite:"Les PJ ont choisi en connaissance de cause. L'épilogue reflète leur décision.",echec:"Les PJ hésitent trop longtemps. Le rituel s'accomplit seul. Le seuil s'ouvre. La Spirale déferle."}}]},{titre:"Acte II — L'Épilogue",stake:"Les conséquences du choix final se déploient sur Valombre.",location:"Valombre — lieux variés selon le choix",scenes:[{id:"s3_monde_apres",titre:"Le Monde d'Après",type:"Conclusion",resume_mj:"La scène d'épilogue varie selon le choix des PJ. Le MJ décrit les conséquences sur Valombre, les factions, les PNJ survivants et le monde. Cette scène n'a pas de jets — c'est une narration pure.",idLieu:"place_fondation",idsPnj:["mara_dirigeante","thorgar_pretre_nain","maera_olane"],format_livre:{ambiance:"Le ciel de Valombre change. Lentement, imperceptiblement, mais il change. Les rues se réorganisent — ou retrouvent leur place, ou deviennent autre chose. Les gens sortent des maisons, lèvent les yeux, regardent. Sur la Place de la Fondation, la statue des Fondateurs est toujours là. Les bâtiments administratifs sont toujours là. Mais le ciel n'est plus le même. Et les gens le savent. L'air sent la pierre humide, le pain, la fumée — ou la lavande, selon le choix. La Place est pleine. Pas pour une émeute. Pas pour un discours. Pour voir. Pour comprendre. Pour décider ce qu'ils font maintenant.",deroulement_narratif:`Le MJ décrit les conséquences selon le choix des PJ :

Si la Larme est détruite : le ciel reprend sa couleur normale. Le déphasage s'arrête. Les routes redeviennent fiables. Les tombes des Thanes sont restaurées — Thorgar confirme que le sceau est refermé. Thade est brisé, jugé ou exilé selon les alliances des PJ. Sealine est perdue. Valombre revient à la normale — mais avec les cicatrices. Les gens se souviennent de ce qui s'est passé.

Si Sealine est sauvée : le ciel garde une teinte violacère, légère, permanente. Le déphasage persiste mais est gérable — certaines rues sont trompeuses, mais la plupart sont fiables. Sealine revient, fragile, silencieuse. Thade est jugé mais pas exécuté — les PJ peuvent témoigner. Valombre apprend à vivre avec la Spirale. Les gens savent que le monde a changé, mais il n'a pas fini.

Si le seuil s'ouvre : le ciel est violet. Les routes mènent partout et nulle part. La Spirale déferle. Valombre est transformée. Thade franchit le seuil vers Sealine — ils disparaissent dans le vortex, ou ils restent, selon ce que les PJ ont dit et ce que Sealine décide. Le monde est différent. Pas meilleur, pas pire — différent. Les gens s'adaptent. La vie continue, mais pas comme avant.

Les PNJ survivants apparaissent : Mara reconstruit. Thorgar restaure les rites. Olane réforme l'Université. Ursula soigne les blessés. Le Champion, s'il n'a pas été arrêté, profite du chaos ou est discrédité. Les Endeuillés, s'ils n'ont pas été dispersés, trouvent la paix ou disparaissent.

Le décompte des victimes de la Tour détermine le ton : peu de victimes, l'épilogue est lumineux — les gens font confiance aux PJ. Beaucoup de victimes, l'épilogue est sombre — les gens craignent les PJ.

Les PJ ont un dernier moment pour parler aux PNJ, visiter les lieux marquants, et décider de l'avenir de leurs personnages.`,notes_mj:"Narration pure. Pas de jets. Le MJ décrit et les PJ réagissent. L'épilogue doit refléter les choix, les alliances et les pertes de toute la campagne. Le MJ peut demander aux PJ ce que leurs personnages font dans les semaines qui suivent. C'est la dernière scène de la campagne — elle mérite du temps et de l'attention.",matrice_epilogue:[{choix:"Larme détruite",sealine:"perdue",thade:"brisé / jugé / exilé",sceau:"refermé",valombre:"normale avec cicatrices",ton:"amer"},{choix:"Larme détachée (Sealine sauvée)",sealine:"revenue fragile",thade:"jugé, pas exécuté",sceau:"entrouvert",valombre:"changée mais vivable",ton:"mélancolique"},{choix:"Seuil ouvert",sealine:"réunie avec Thade ou disparue",thade:"accompli / perdu",sceau:"aboli",valombre:"fusionnée à la Spirale",ton:"mythique"}]},texte_a_lire:`Le ciel de Valombre change. Lentement, imperceptiblement, mais il change. Les rues se réorganisent. Les gens s'arrêtent, lèvent les yeux, regardent. Quelque chose est arrivé — ou quelque chose est parti. Le monde n'est plus exactement celui qu'il était hier.

Sur la Place de la Fondation, les gens se rassemblent. Pas pour une émeute. Pas pour un discours. Pour voir. Pour comprendre. Pour décider ce qu'ils font maintenant.`,objectif:"Voir les conséquences du choix final et clore la campagne.",contexte_mj:{situation:"Le MJ décrit les conséquences selon le choix : Si la Larme est détruite : le sceau se referme. Le déphasage s'arrête. Le froid cesse. Les tombes des Thanes sont restaurées. Thade est brisé, jugé ou exilé. Sealine est perdue. Valombre revient à la normale — mais avec les cicatrices. Si Sealine est sauvée : le seuil filtre. Le déphasage persiste mais est gérable. Sealine revient, fragile. Thade est jugé mais pas exécuté. Valombre apprend à vivre avec la Spirale. Si le seuil s'ouvre : la Spirale déferle. Valombre est transformée. Le ciel est violet. Les routes mènent partout et nulle part. Thade franchit le seuil vers Sealine. Le monde est différent. Pas meilleur, pas pire — différent.",secrets:["Le décompte des victimes de la Tour détermine le ton de l'épilogue. Peu de victimes : l'épilogue est lumineux. Beaucoup de victimes : l'épilogue est sombre.","Les PNJ survivants apparaissent : Mara, Thorgar, Olane, Ursula. Leur réaction dépend du choix et des relations construites pendant la campagne.","Le Champion de la Bannière Pure, s'il n'a pas été arrêté, profite du chaos ou est discrédité selon le choix."],rappels:["C'est une scène de narration. Pas de jets. Le MJ décrit et les PJ réagissent.","L'épilogue doit refléter les choix, les alliances et les pertes de toute la campagne."]},guide_mj:{intention:"Clore la campagne avec les conséquences du choix final.",mise_en_place:"Place de la Fondation. Les gens rassemblés. Le ciel change.",deroulement:["Le MJ décrit le changement du ciel et de la ville.","Les PNJ survivants apparaissent et réagissent.","Le sort de Thade et de Sealine est révélé.","Les PJ ont un dernier moment pour interagir."],actions_utiles:["Parler aux PNJ survivants.","Visiter les lieux marquants de la campagne.","Décider de l'avenir des PJ."],fronts_heritiers:["Tous les fronts sont résolus."],jeu_des_pnj:"Mara reconstruit. Thorgar restaure les rites. Olane réforme l'Université. Ursula soigne les blessés. Chacun selon sa nature.",escalade:"Pas d'escalade. C'est la fin.",sortie:"La campagne est terminée. Les PJ quittent Valombre ou y restent. Le monde continue."},reperes_de_jeu:{indice_indispensable:"Les PJ doivent voir les conséquences de leur choix.",ne_pas_bloquer_sur_un_jet:"Pas de jets. Narration pure.",question_dramatique:"Valombre survivra-t-elle à ce que vous avez fait ?"},transitions:{resume:"Le soleil se couche sur Valombre. Le ciel prend sa couleur définitive — normale, violette, ou entre les deux.",reussite:"La campagne se termine sur un épilogue qui reflète les choix des PJ.",echec:"La campagne se termine sur un épilogue plus sombre, mais qui reflète aussi les choix."}}]}],encadres_mj:[{id:"enc_pj_tuent_thade_sans_parler",titre:"Que faire si les PJ tuent Thade sans utiliser les vérités",situation:"Les PJ combattent Thade par la force dès la phase 1, sans lire les cahiers ni révéler les vérités sur Sealine. Ils veulent en finir vite.",principe:"Thade peut être vaincu par la force. Ce n'est pas un échec — c'est un choix. Mais le combat est plus long, plus dangereux, et la Larme ne se fissure pas. Sealine apparaît quand même, mais la conversation est plus tendue.",proceder:[{etape:"Le combat se déroule normalement",detail:"Les trois phases se succèdent. Thade est puissant mais épuisé. Sans les vérités, la phase 2 est plus longue — Thade ne se désespère pas, il continue à combattre avec une régularité mécanique."},{etape:"Sealine apparaît à la phase 3",detail:"Sealine apparaît, mais elle regarde les PJ avec une tristesse différente. Elle dit : « Vous l'avez arrêté. Mais vous ne savez pas pourquoi il a commencé. » Les PJ peuvent encore parler à Thade au sol."},{etape:"Le choix reste le même",detail:"Les trois options sont toujours disponibles. Mais le contexte est différent : les PJ ont vaincu Thade par la force, sans comprendre. L'épilogue peut en tenir compte."}],a_ne_pas_faire:["Ne pas punir les PJ pour avoir combattu. C'est un choix valide.","Ne pas rendre le combat impossible. Thade est épuisé, pas invincible.","Ne pas forcer les PJ à parler s'ils veulent combattre."]},{id:"enc_pj_veulent_sauver_sealine",titre:"Que faire si les PJ veulent sauver Sealine à tout prix",situation:"Les PJ sont décidés dès le début : ils veulent sauver Sealine. Ils ne veulent pas détruire la Larme ni laisser le seuil s'ouvrir. Ils veulent la troisième voie.",principe:"L'option 2 (détacher la Larme sans la briser) est valide. Mais le MJ doit s'assurer que les PJ comprennent le prix : le seuil reste entrouvert, la Spirale filtre, Valombre est changée. Ce n'est pas une fin heureuse.",proceder:[{etape:"Sealine explique le prix",detail:"Sealine dit : « Si vous me retirez du vortex, je reviendrai. Mais la porte ne se refermera pas. La Spirale continuera de filtrer. Valombre ne sera plus exactement ce qu'elle était. » Les PJ doivent entendre ça avant de choisir."},{etape:"Le retrait de la Larme",detail:"Art de la magie DD 18 pour détacher la Larme sans la briser. Réussite : la Larme se détache du vortex. Sealine se matérialise pleinement. Le vortex se réduit mais ne disparaît pas. Échec : la Larme se fissure et se brise partiellement. Sealine revient mais le seuil est plus ouvert que prévu."},{etape:"L'épilogue reflète le choix",detail:"Le ciel garde une teinte violacère. Les routes sont parfois trompeuses. Sealine est là, fragile, silencieuse. Thade est jugé. Valombre apprend à vivre avec la Spirale. Ce n'est pas une fin heureuse — c'est un nouveau commencement."}],a_ne_pas_faire:["Ne pas transformer l'option 2 en solution parfaite. Elle a un prix.","Ne pas empêcher les PJ de la choisir. C'est un choix valide.","Ne pas oublier que Thade doit être jugé — les PJ ne décident pas seul de son sort."]},{id:"enc_pj_hesitent_trop_longtemps",titre:"Que faire si les PJ hésitent trop longtemps",situation:"Les PJ sont dans la conversation à trois. Sealine a expliqué les options. Les PJ discutent, débattent, ne se décident pas. Le temps passe.",principe:"Le rituel n'attend pas. Si les PJ hésitent trop longtemps, le rituel s'accomplit seul. C'est l'option 3 sans choix conscient.",proceder:[{etape:"Premier avertissement — le vortex pulse",detail:"Le bourdonnement du vortex augmente. La Larme brille plus fort. Le ciel s'assombrit. Le MJ décrit : « Vous sentez que le rituel approche de son accomplissement. »"},{etape:"Deuxième avertissement — Sealine prévient",detail:"Sealine dit : « Le temps presse. Si vous ne choisissez pas, le rituel s'accomplira seul. Ce ne sera pas votre choix — ce sera l'absence de choix. »"},{etape:"Troisième avertissement — la Larme s'ouvre d'elle-même",detail:"Thade tente de se relever ou la Larme s'ouvre d'elle-même. Le MJ décrit : « Le vortex s'élargit. La Larme pulse. C'est presque fini. » Si les PJ ne choisissent toujours pas, le rituel s'accomplit. Le seuil s'ouvre. La Spirale déferle. C'est l'option 3, mais sans décision consciente. L'épilogue est plus sombre — les PJ n'ont pas choisi, ils ont laissé faire."}],a_ne_pas_faire:["Ne pas éterniser l'hésitation. Le MJ donne trois avertissements, puis le rituel s'accomplit.","Ne pas punir les PJ avec un TPK. Le rituel s'accomplit, mais les PJ survivent.","Ne pas forcer un choix avant les avertissements. Laisser le temps de la discussion."]},{id:"enc_pj_attaquent_sealine",titre:"Que faire si les PJ attaquent Sealine",situation:"Les PJ voient Sealine dans le vortex et l'attaquent. Ils la considèrent comme une créature de la Spirale, pas comme une personne.",principe:"Sealine ne combat pas. Elle se retire dans le vortex. Le choix final devient plus confus — les PJ doivent décider sans ses explications.",proceder:[{etape:"Sealine se retire",detail:"Sealine ne se défend pas. Elle dit : « Je ne suis pas votre ennemie. » Puis elle se retire dans le vortex. La Larme pulse. Le rituel continue."},{etape:"Les options sont moins claires",detail:"Sans Sealine pour expliquer, les PJ doivent déduire les options par eux-mêmes. Art de la magie DD 18 pour analyser le vortex. Le magi-tuteur, s'il est présent, peut expliquer. Sinon, les PJ naviguent à l'aveugle."},{etape:"L'épilogue en tient compte",detail:"Si les PJ détruisent la Larme, Sealine est perdue — ils l'ont attaquée puis détruite. Si les PJ sauvent Sealine, elle revient mais se méfie des PJ. Si le seuil s'ouvre, Sealine disparaît dans la Spirale. L'épilogue est plus sombre."}],a_ne_pas_faire:["Ne pas rendre Sealine combattante. Elle ne combat pas.","Ne pas punir les PJ avec un TPK. Les conséquences sont narratives.","Ne pas empêcher les PJ de choisir. Les options sont toujours là, mais moins claires."]}],aides_jeu:{indices_recap:[{scene:"Le Vortex",jet:"Persuasion DD 18",info:"Lire un extrait des cahiers ou révéler une vérité sur Sealine fissure la Larme. Chaque vérité compte comme 2 rounds de combat."},{scene:"Le Vortex",jet:"Art de la magie DD 18",info:"Identifier la structure du vortex. La Larme est le catalyseur. La détacher arrête le rituel sans refermer complètement le seuil. La détruire libère l'énergie et referme le sceau. La laisser ouvre le seuil."},{scene:"Le Vortex",jet:"Athlétisme DD 15",info:"Se frapper un chemin vers le vortex à travers les vents planaires."},{scene:"La Conversation à Trois",jet:"Aucun jet",info:"Sealine explique les trois options. Le choix appartient aux PJ. Aucun jet nécessaire."},{scene:"Le Monde d'Après",jet:"Aucun jet",info:"Narration pure. Le MJ décrit les conséquences selon le choix, les alliances et le décompte des victimes."}],pnj_recap:[{id:"thade_coren",nom:"Thade Coren",faction:"Université Arcanique (Archimage)",role_court:"Boss final / Homme brisé",apparition:"Acte I, scène 1",info_cle:"Combat par amour, pas par cruauté. Chaque vérité le blesse. S'effondre à la phase 3.",dd_clés:"Persuasion DD 18 pour les vérités. Athlétisme DD 15 pour les vents planaires."},{id:"sealine_coren",nom:"Sealine Vael",faction:"La Spirale",role_court:"La Dame de la Spirale / Choix final",apparition:"Acte I, scène 2",info_cle:"Lucide, calme, présente. Sait tout. Ne demande rien. Explique les trois options.",dd_clés:"Aucun jet. C'est une conversation."},{id:"magi_tuteur_loyal",nom:"Le Magi-Tuteur loyal",faction:"Université Arcanique (Allié)",role_court:"Témoin / Allié possible",apparition:"Acte I, scène 1 (si survivant)",info_cle:"Peut intervenir à la phase 2. Peut expliquer les options si Sealine est absente.",dd_clés:"Aucun jet. Son intervention est narrative."}],lieux_recap:[{id:"sommet_tour_vortex",nom:"Sommet de la Tour Arcanique",scenes:["Le Vortex","La Conversation à Trois"],info:"Plateforme circulaire, marbre clair, ciel violet. Vortex au centre. Larme au cœur. Lieu du combat final et du choix."},{id:"place_fondation",nom:"Place de la Fondation",scenes:["Le Monde d'Après"],info:"Lieu de l'épilogue. Les gens se rassemblent. Le ciel change. Le monde d'après commence ici."}],chronologie_recap:["Les PJ franchissent la porte du sommet. Le ciel est violet.","Phase 1 : Thade combat, épuisé mais puissant. Les PJ combattent ou parlent.","Phase 2 : Les vérités fissurent la Larme. Thade devient désespéré.","Phase 3 : Thade s'effondre. Sealine apparaît. La conversation à trois commence.","Sealine explique les trois options. Les PJ choisissent.","L'épilogue déploie les conséquences sur Valombre."]}},d=[i,l,o],p=Object.freeze({"L'Architecte":{etiquette:"L'Ambitieux / L'Architecte",couleur:"text-purple-300 border-purple-800/60 bg-purple-950/30"},"Le Fléau":{etiquette:"La Force Brute / Le Fléau",couleur:"text-red-300 border-red-800/60 bg-red-950/30"},"L'Institution":{etiquette:"L'Institution / L'Allié ambigu",couleur:"text-blue-300 border-blue-800/60 bg-blue-950/30"},"La Force Environnementale":{etiquette:"La Force Environnementale",couleur:"text-emerald-300 border-emerald-800/60 bg-emerald-950/30"}}),m=[{id:"front_plan_thade",nom:"Le Plan de Thade",type:"Front antagoniste",icone:s,couleur:"text-violet-300 border-violet-900 bg-violet-950/30",enjeu:"Thade Coren utilise l'autorité de l'Université, les fragments de la Larme de Vael et les dispositifs de la Tour Arcanique pour forcer une ouverture vers la Spirale. S'il réussit, il ramènera peut-être Sealine, mais transformera Valombre en ancre d'un passage que nul ne saura refermer.",description:"Depuis huit ans, Thade rassemble les fragments de la Larme, étudie les faiblesses du seuil et instrumentalise les survivants de Nyx. Son plan ne dépend plus seulement de l'affaiblissement des tombes : la Tour devient une machine capable de concentrer artificiellement les flux de la Spirale. Pour l'arrêter, il faut briser son dispositif, retourner ses soutiens ou l'amener à renoncer lui-même au retour de Sealine.",questionDramatique:"Les PJ peuvent-ils révéler le vrai projet de Thade avant que l'Université ne devienne son rempart ?",forcesActives:[{nom:"Thade Coren",idsPnj:["thade_coren"],role:"Architecte du plan. Opère dans le cadre légal jusqu'à ce que le cadre ne suffise plus. Poli, précis, jamais cruel — l'atrocité est dans l'efficacité, pas dans le ton."},{nom:"Les Loyalistes de la Tour",idsPnj:["magi_tuteur_loyal","jaren_velt"],role:"Obstacle institutionnel retournable. Verrouillent la Tour par obéissance, pas par fanatisme. Leur fidélité tient à la carrière et au déni."}],signesVisibles:["Des salles sont scellées pour « travaux » ou « sécurité » sans explication.","Les flux arcaniques de plusieurs bâtiments sont détournés vers la Tour.","Les communications vers et depuis la Tour passent par un secrétariat qui filtre les priorités.","Des prélèvements funéraires et des instruments réquisitionnés convergent vers les laboratoires de la Tour.","Les objets enchantés dérivent légèrement vers la Tour et les sorts de détection renvoient des échos contradictoires."],scenesJouables:{enquete:["Suivre la trace des prélèvements funéraires jusqu'aux laboratoires de la Tour (Jaren Velt comme piste).","Retrouver Olane et comprendre pourquoi ses accès ont été restreints — elle a les chiffres mais pas les preuves publiques."],roleplay:["Confronter un maître arcaniste loyaliste : il défend l'Université avant de comprendre qu'elle est parasitée.","Négocier avec Thade lui-même : courtois, lucide, il justifie chaque étape comme une nécessité."],action:["Infiltrer les niveaux scellés de la Tour pendant que les gardes sont en rotation.","Extraire Olane de l'Université avant que ses preuves ne soient confisquées par une procédure interne."]},leviersPJ:["Retourner les Loyalistes en prouvant ce que Thade assemble réellement.","Protéger Olane et ses preuves pour maintenir l'enquête interne ouverte.","Démontrer publiquement la vérité pour forcer l'Université à agir contre Thade.","Confronter Thade avec Sealine elle-même (si les PJ ont atteint la Spirale) pour l'amener à renoncer."],menaces:[{id:"menace_retour_sealine",nom:"Le Retour de Sealine",categorie:"L'Architecte",nature:"Thade rassemble les composants, détourne les flux et verrouille la Tour pour ouvrir le vortex.",objectifFinal:"Thade concentre la Larme reconstituée au sommet de la Tour, ouvre le vortex et franchit le seuil pour en extraire Sealine — sacrifiant la stabilité de Valombre et son propre corps comme ancre planaire.",idsPnj:["thade_coren"],avancement:{type:"A",declencheurPrincipal:"Thade accomplit une étape de son plan (réunion des composants, alimentation de la Tour, verrouillage, ouverture du vortex).",declencheurSecondaire:"Un échec PJ significatif ou une couverture institutionnelle peut accélérer l'étape.",avanceHorsChamp:!0,avanceParEnquete:!1},conséquenceRemplissage:"Le vortex s'ouvre au sommet de la Tour. Thade franchit le seuil et Valombre devient une ancre planaire.",annulation:"Extrêmement difficile : il faut refermer le vortex depuis l'intérieur de la Tour, avec un coût planaire majeur.",horloge:{taille:6,etapes:[{titre:"Thade récupère les derniers composants",indice:"Les prélèvements funéraires, les protocoles de Nyx et les instruments réquisitionnés convergent vers les laboratoires de la Tour. Les assistants ne savent pas ce qu'ils assemblent, mais chaque livraison réduit ce qui manque encore."},{titre:"Les flux de l'Université sont détournés",indice:"Les flux arcaniques de plusieurs bâtiments sont détournés vers la Tour. Des cours sont annulés, des salles sont scellées et les protections ordinaires de l'Université deviennent instables."},{titre:"Olane est isolée",indice:"Ses accès sont restreints, ses demandes restent sans réponse et ses collègues sont encouragés à traiter ses soupçons comme une rivalité personnelle. Les témoins hésitent à lui parler ouvertement."},{titre:"La Tour est placée sous autorité spéciale",indice:"Les accès sont verrouillés, les communications filtrées et les défenseurs obéissent à des ordres qu'ils ne peuvent plus discuter. La cuve de cristal et les dispositifs du sommet fonctionnent en continu."},{titre:"La Larme est alimentée",indice:"Une ligne lumineuse traverse l'artefact. Les objets enchantés dérivent vers la Tour, les sorts renvoient des échos contradictoires et les mages ressentent une seconde pulsation derrière leur propre magie. Des couloirs rejoignent des pièces qu'ils ne devraient pas toucher."},{titre:"Le vortex s'ouvre",indice:"Un bourdonnement traverse les Hauteurs, le ciel prend une teinte violette et la Larme devient visible au cœur du vortex. Thade n'a plus besoin d'autorisation, d'assistants ni de dissimulation : le retour a commencé."}]}},{id:"menace_loyalistes_tour",nom:"Les Loyalistes de la Tour",categorie:"L'Institution",nature:"Assistants, mages subalternes et gardes de la Tour qui obéissent aux ordres de Thade sans comprendre ce qu'ils assemblent.",objectifFinal:"Les Loyalistes verrouillent la Tour au point qu'aucune intervention extérieure ne peut y pénétrer sans un assaut ouvert.",idsPnj:["magi_tuteur_loyal","jaren_velt"],noteMJ:"Les Loyalistes sont un obstacle à l'échelle des PJ, pas un boss. Ils peuvent être retournés, convaincus, intimidés ou contournés. Si les PJ leur démontrent ce que Thade assemble réellement, ils peuvent changer de camp. Si les PJ les ignorent, ils rendent l'assaut final beaucoup plus difficile.",conséquenceRemplissage:"La Tour est verrouillée. Pénétrer suppose un assaut ouvert, une infiltration difficile ou une trahison interne.",annulation:"Possible : si les PJ retournent un ou plusieurs Loyalistes, démontrent la vérité sur le dispositif, ou offrent une alternative institutionnelle crédible."},{id:"menace_larme_vael",nom:"La Larme de Vael",categorie:"La Force Environnementale",nature:"Fragment planaire qui accumule les résonances et produit des anomalies magiques croissantes dans la Tour.",objectifFinal:"La Larme se fissure et devient une ouverture permanente, même si Thade tombe.",idsPnj:["thade_coren"],noteMJ:"La Larme est un danger qui produit des scènes : anomalies magiques, déformations géométriques, échos contradictoires. Elle n'a pas d'horloge propre — elle suit l'horloge principale. Aux étapes 4 et 5, les anomalies deviennent visibles pour tout mage passant près de la Tour.",conséquenceRemplissage:"La Larme se fissure et devient une ouverture permanente. Le vortex continue de croître sans Thade.",annulation:"Difficile : il faut extraire ou sceller la Larme, ce qui suppose d'avoir neutralisé le contrôle de la Tour."}]},{id:"front_factions_crise",nom:"Les Factions de la Crise",type:"Front de factions",icone:a,couleur:"text-red-300 border-red-900 bg-red-950/30",enjeu:"Les cercles de Nyx, la pression caldrisienne et le Champion de la Bannière Pure ne forment pas un ennemi unique mais un tissu de factions aux motivations contradictoires qui se renforcent mutuellement par la peur. Si aucune main ne les sépare, elles vont se détruire mutuellement — ou déclencher une répression aveugle qui frappera aussi les innocents.",description:"Depuis la catastrophe qui a dispersé l'Ordre de Nyx originel, le nom est devenu un abri pour tous ceux que les institutions n'accueillent pas : Ursula soigne les pauvres dans sa cave, Elian Voss poursuit son protocole S-01 sur des patients non consentants, Edran Morn rassemble des familles endeuillées autour de pratiques de plus en plus radicales. Parallèlement, l'émissaire Maelric représente un gouvernement qui voit les routes commerciales se dégrader et une cité incapable d'expliquer ce qui se passe sous ses rues. Le Champion de la Bannière Pure, lui, est venu avec une conviction : Valombre a failli à son rôle de verrou. Ces factions ne se concertent pas, mais elles se renforcent mutuellement par la peur.",questionDramatique:"Les PJ peuvent-ils séparer les innocents des coupables avant que la peur ne transforme chaque cercle en ennemi public ?",forcesActives:[{nom:"Elian Voss",idsPnj:["elian_voss"],role:"Chercheur qui justifie ses crimes par ses résultats. Efface ses traces et prépare sa fuite avec un commanditaire caldrisien."},{nom:"Edran Morn et les Endeuillés",idsPnj:["edran_morn"],role:"Meneur capable d'hésiter si ses actes menacent des vivants, mais que la douleur collective pousse vers des décisions irréparables."},{nom:"Le Champion de la Bannière Pure",idsPnj:["champion_banniere_pure"],role:"Chevalier qui croit en sa mission purificatrice. Rassemble une milice autour de la peur des cercles de Nyx."}],signesVisibles:["Des familles endeuillées quittent les réseaux d'entraide ordinaires pour rejoindre Edran Morn.","Des patients arrivent chez Ursula avec des notes médicales dans une écriture inconnue.","Le Champion tient des discours publics sur les « cercles de Nyx » et rassemble des partisans visibles.","Des convois extérieurs annulent leur étape à Valombre « pour raisons sanitaires ».","Des passages dans les égouts sont dégagés et des marchandises sans étiquette apparaissent dans les réserves."],scenesJouables:{enquete:["Enquêter sur les patients « stabilisés » d'Elian Voss : retrouver les familles qui cherchent un proche disparu.","Identifier le commanditaire caldrisien d'Elian via le cachet sur ses notes — lien avec Maelric ?"],roleplay:["Confronter Edran Morn : le convaincre que les rites qu'il pratique menacent directement le sceau des Thanes.","Débattre publiquement avec le Champion de la Bannière Pure : démontrer que ses accusations frappent les innocents autant que les coupables."],action:["Infiltrer le laboratoire d'Elian sous l'amphithéâtre avant qu'il n'efface les preuves du protocole S-01.","Intervenir physiquement quand la milice du Champion attaque un refuge supposé de Nyx."]},leviersPJ:["Retourner Edran Morn en démontrant le danger des rites sur le sceau.","Détruire ou sécuriser les preuves du protocole S-01 avant qu'Elian ne les efface.","Démontrer publiquement les mensonges du Champion pour briser sa base populaire.","Produire une preuve de stabilité crédible pour calmer la pression de Maelric et du Conseil.","Négocier avec Maelric : c'est un homme rationnel qui cherche des réponses, pas un ennemi."],menaces:[{id:"menace_radicalisation_cercles",nom:"La Confusion des Cercles",categorie:"L'Institution",nature:"Crise collective où les cercles de Nyx, les autorités, Caldris, le Champion et le Syndicat se renforcent mutuellement par la peur, les accusations publiques et les preuves partielles.",objectifFinal:"La peur impose sa propre logique : les institutions, la milice et les factions clandestines cessent de distinguer innocents, coupables, malades, chercheurs et fanatiques. La purge, la répression ou la fuite éclate publiquement.",idsPnj:["elian_voss","edran_morn","champion_banniere_pure","envoye_caldris","le_collecteur"],avancement:{type:"A",declencheurPrincipal:"L'une des factions actives franchit un seuil sans être contrée par les PJ.",declencheurSecondaire:"La pression caldrisienne ou un incident public peut accélérer la crise.",avanceHorsChamp:!0,avanceParEnquete:!1},conséquenceRemplissage:"La crise éclate publiquement : purge, répression ou fuite. Les innocents et les coupables sont frappés ensemble.",annulation:"Possible : si les PJ séparent les factions, retournent un meneur ou offrent une alternative crédible à la peur.",horloge:{taille:6,etapes:[{titre:"Les cercles s'organisent",indice:"Elian Voss reçoit des patients « stabilisés » avec des notes dans une écriture inconnue. Edran Morn absorbe les familles isolées. Le Champion tient ses premiers discours publics. Chaque faction prend confiance en son propre cadre."},{titre:"Les premiers signes deviennent visibles",indice:"Ursula reçoit des patients qu'elle ne reconnaît pas. Des familles cherchent un proche disparu. Le Champion obtient une victoire publique — sauvetage ou arrestation. Des passages dans les égouts sont dégagés."},{titre:"La peur monte",indice:"Le Champion impose un choix public : pour ou contre Nyx. Edran introduit des pratiques interdites dans son cercle. Elian commence à effacer ses traces. Les convois extérieurs annulent leur étape à Valombre."},{titre:"La pression caldrisienne se formalise",indice:"Maelric obtient un ultimatum du Conseil. Des convois sont retenus. La Guilde Marchande perd de l'argent. Le Conseil cherche un coupable. Les maisons marchandes déplacent leurs réserves."},{titre:"L'affrontement devient inévitable",indice:"Une milice se forme autour du Champion. Les Endeuillés pratiquent un rite près des tombes. Elian prépare sa fuite. Les reconnaissances de dette du Syndicat circulent. Chaque faction est prête à frapper."},{titre:"La crise éclate",indice:"La purge, la répression ou la fuite se déclenche. Les innocents et les coupables sont frappés ensemble. Valombre devient la cité qui a laissé la peur décider à la place de la justice."}]}},{id:"menace_endeuilles_radicalisation",nom:"Les Endeuillés d'Edran Morn",categorie:"Le Fléau",nature:"Meneur capable d'hésiter si ses actes menacent directement des vivants, mais que la douleur collective de son cercle pousse vers des décisions irréparables.",objectifFinal:"Les Endeuillés pratiquent un rite de communication avec les défunts dans le Cimetière des Terrasses — perturbant directement le sceau des Thanes.",idsPnj:["edran_morn"],noteMJ:"Edran est retournable. Si les PJ démontrent le danger des rites sur le sceau, il peut changer de cap. Sans horloge propre : sa radicalisation suit l'horloge principale. Aux étapes 3 et 5, il est en scène.",conséquenceRemplissage:"Une brèche planaire s'ouvre au Cimetière des Terrasses. Une présence de la Spirale franchit le seuil.",annulation:"Possible avant l'étape 5 : si les PJ retournent Edran, séparent le cercle ou démontrent le danger."},{id:"menace_syndicat_instrumentalisation",nom:"Le Syndicat des Brumes",categorie:"L'Institution",nature:"Réseau criminel qui vend des services à tous les cercles clandestins, rendant chaque escalade un peu plus facile.",objectifFinal:"Le Syndicat accumule assez de preuves compromettantes pour devenir intouchable politiquement.",idsPnj:["le_collecteur","contremaite_egouts","hommes_main_pegre"],noteMJ:"Le Syndicat est un facilitateur, pas un moteur. Il crée des scènes (contrebande, chantage, égouts) mais n'a pas d'horloge propre. Il profite du chaos généré par les autres factions.",conséquenceRemplissage:"Le Syndicat devient intouchable. Ses reconnaissances de dette lui assurent une protection permanente.",annulation:"Difficile : détruire les copies compromettantes ou retourner suffisamment de débiteurs."},{id:"menace_emissaire_maelric",nom:"L'Émissaire Maelric",categorie:"L'Institution",nature:"Représentant courtois et sincèrement inquiet qui réduit les vérités complexes en preuves exploitables et en délais.",objectifFinal:"Maelric obtient du Conseil une reconnaissance officielle de l'incapacité de Valombre, ouvrant la voie à une quarantaine caldrisienne.",idsPnj:["envoye_caldris"],noteMJ:"Maelric est un négociateur, pas un ennemi. Il peut être retourné avec une preuve de stabilité crédible. Sa pression suit l'horloge principale (étape 4). C'est aussi un témoin clé du déphasage.",conséquenceRemplissage:"La quarantaine est imposée. Des officiers caldrisiens contrôlent les passages hors de l'autorité de Valombre.",annulation:"Possible avant l'étape 5 : produire une preuve de stabilité crédible ou retourner Maelric."}]},{id:"front_cite_sous_pression",nom:"La Cité sous pression",type:"Front institutionnel",icone:n,couleur:"text-stone-300 border-stone-700 bg-stone-950/30",enjeu:"Les institutions de Valombre — le Conseil, l'Université, le Clergé — fonctionnent encore, mais elles ont perdu la mémoire de ce qu'elles gardent. Leurs rituels sont là, leurs titres sont là, leurs archives sont là. Mais la signification profonde de leur rôle a été effacée par des siècles de routine. Cet oubli est ce qui a permis à Thade d'agir en pleine lumière sans que personne ne pose la bonne question.",description:"Le Conseil vote, l'Université enseigne, le Clergé officie. En apparence, Valombre est une cité en ordre. Mais le Conseil ralentit chaque décision urgente par des procédures conçues pour un monde sans Spirale. L'Université déférait à Thade parce qu'il était le plus brillant et le plus titré de ses membres. Le Clergé tient les registres des morts sans savoir que sept de ces morts sont le fondement du sceau. La loi martiale, quand elle arrive, n'arrangera rien : elle donnera une apparence d'action à des gens qui ne savent pas contre quoi ils agissent.",questionDramatique:"Les PJ peuvent-ils empêcher le Conseil de remettre les pouvoirs d'urgence à Thade (ou un équivalent) avant que les institutions ne se retournent contre ceux qui veulent sauver la cité ?",forcesActives:[{nom:"Le Conseil",idsPnj:["avel_ronce","patrouille_mixte_conseil","hessa_brunefer"],role:"Corps gouvernant qui enterre la crise sous la procédure, cherche un coupable, puis remet les pouvoirs d'urgence à qui paraît le plus capable d'agir."},{nom:"L'Université",idsPnj:["maera_olane","magi_tuteur_loyal","jaren_velt"],role:"Institution compétente mais aveugle à son propre angle mort. Couvre Thade par déférence, isole Olane par réflexe corporatiste."}],signesVisibles:["Les débats du Conseil s'enlisent dans des commissions et des conflits de compétence.","Des rumeurs publiques désignent Nyx, les clans ou l'Université comme responsables de la crise.","Les accès miniers sont fermés ou confiés à des gardes civiques.","Olane n'a plus accès à ses données et ses collègues évitent de lui parler.","Des cérémonies religieuses sont simplifiées « pour des raisons de sécurité »."],scenesJouables:{enquete:["Retrouver des archives dispersées qui expliquent le rôle véritable du sceau et des Thanes.","Investiguer les coulisses du Conseil : quels conseillers sont influençables, quels liens avec Thade ou Caldris ?"],roleplay:["Convaincre un conseiller clé de ne pas voter la loi martiale ou les pouvoirs d'urgence.","Affronter le corps enseignant de l'Université : Olane a raison, mais prouver publiquement est un défi institutionnel."],action:["Empêcher l'arrestation d'un détenteur de savoir (Brogar, Thorgar) par les gardes du Conseil.","Protéger des archives menacées de saisie ou de destruction par une procédure interne."]},leviersPJ:["Influencer le vote du Conseil en retournant des conseillers ou en offrant une réponse crédible à la crise.","Soutenir Olane publiquement pour empêcher l'Université de couvrir Thade.","Retrouver et rassembler les fragments de savoir dispersés pour restaurer la mémoire du sceau.","Protéger les détenteurs de savoir menacés (Brogar, Thorgar, vieux archivistes).","Démontrer que la loi martiale aggraverait la crise au lieu de la résoudre."],menaces:[{id:"menace_derive_institutionnelle",nom:"Le Conseil, la Machine à Retarder",categorie:"L'Institution",nature:"Corps gouvernant dont la procédure est conçue pour produire du consensus, pas de la décision — et qui se paralyse dès que l'urgence dépasse ses cadres habituels.",objectifFinal:"Face à la crise, le Conseil vote une loi martiale partielle qui suspend les droits des communautés clandestines, ferme les accès miniers et place les Terrasses sous tutelle civile — au moment précis où la coopération des nains et de Nyx serait indispensable pour refermer le sceau.",idsPnj:["avel_ronce","patrouille_mixte_conseil","hessa_brunefer"],avancement:{type:"A",declencheurPrincipal:"Le Conseil enterre la crise, cherche un coupable, puis remet les pouvoirs d'urgence.",declencheurSecondaire:"La pression de Caldris (menace_emissaire_maelric) et la peur publique accélèrent les votes.",avanceHorsChamp:!0,avanceParEnquete:!1},noteMJ:"Si Thade est déjà neutralisé au moment de l'étape 6, remplacer par : « Le Conseil remet les pouvoirs de crise à une structure contrôlée par l'Université ou l'armée. » L'effet reste similaire : les opposants deviennent légalement des obstacles.",conséquenceRemplissage:"Le Conseil remet les pouvoirs d'urgence à Thade (ou une structure équivalente). Les opposants deviennent légalement des obstacles à la sécurité publique.",annulation:"Possible avant l'étape 6 : si les PJ influencent le vote, retournent des conseillers ou offrent une réponse crédible à la crise. Après l'étape 6, il faut une manœuvre politique majeure pour inverser la loi.",horloge:{taille:6,etapes:[{titre:"La crise est enterrée sous la procédure",indice:"Commissions, expertises et conflits de compétence retardent toute action concrète. Les responsables disposent de temps pour déplacer des preuves et les dangers continuent d'avancer sans réponse coordonnée."},{titre:"Les experts sont mis en concurrence",indice:"L'Université, la Guilde Marchande et les autorités naines produisent des rapports contradictoires sur la nature de la crise. Chacun défend son cadre d'analyse et disqualifie les autres. Les PJ peuvent exploiter ces divisions ou tenter de produire un consensus."},{titre:"Le Conseil cherche un responsable",indice:"Pour rassurer la population et les marchés, les débats se déplacent vers la désignation d'un coupable : Nyx, les clans, l'Université ou des agents étrangers. Les informations qui compliquent ce récit sont écartées."},{titre:"Les Terrasses sont placées sous contrôle",indice:"Les accès miniers sont fermés ou confiés à des gardes civiques. Les autorités naines perdent la maîtrise de leurs propres galeries et cessent de partager leurs plans, leurs équipes et leurs connaissances."},{titre:"Les pouvoirs d'urgence sont débattus",indice:"Le Conseil examine des propositions de loi martiale partielle, de tutelle sur les Terrasses et de transfert de l'autorité arcanique. Les débats sont vifs mais le sens général est clair : il faut quelqu'un capable de décider seul. Les PJ ont encore une fenêtre pour influencer le vote."},{titre:"Thade reçoit les pouvoirs d'urgence",indice:"Le Conseil remet la gestion de la crise arcanique à Thade ou à une structure qu'il contrôle. Les décisions peuvent désormais être prises sans débat, et les opposants deviennent légalement des obstacles à la sécurité publique."}]}},{id:"menace_universite_deference",nom:"L'Université, l'Angle Mort",categorie:"L'Institution",nature:"Institution compétente et bien intentionnée qui a développé une confiance aveugle en son membre le plus brillant. Son angle mort est aggravé par le déphasage : l'Université cherche un phénomène magique dans Valombre, alors que le phénomène est Valombre elle-même.",objectifFinal:"Quand la vérité sur Thade émerge, l'Université choisit de la gérer en interne pour protéger sa réputation — effaçant des preuves, retardant les alertes et couvrant involontairement la fuite de Thade vers la Tour.",idsPnj:["maera_olane","magi_tuteur_loyal","jaren_velt"],noteMJ:"L'Université crée des scènes (isoler Olane, confisquer l'enquête, produire une version officielle) mais n'a pas d'horloge propre. Sa dérive suit l'horloge principale : aux étapes 2 et 3, l'Université est en scène. Si les PJ sont membres de l'Université, cette menace interagit directement avec leurs accès et leur statut.",conséquenceRemplissage:"L'Université produit une version officielle qui minimise les faits, retarde l'alerte et protège la Tour. Les preuves sont déplacées, Olane n'a plus de recours interne.",annulation:"Possible avant l'étape 3 : si les PJ rassemblent des preuves publiques, retournent un membre influent du corps enseignant ou alertent une autorité externe."},{id:"menace_memoire_perdue",nom:"La Mémoire Perdue de Valombre",categorie:"La Force Environnementale",nature:"Érosion culturelle et historique qui a rendu la cité incapable de reconnaître le verrou qu'elle garde — et donc incapable de le défendre consciemment.",objectifFinal:"La crise se résout ou échoue sans que Valombre ait jamais réellement compris ce qu'elle gardait. Les gestes anciens restent des gestes. Les rites des Thanes restent des cérémonies. Rien ne change structurellement, et la prochaine génération sera aussi aveugle que celle-ci.",idsPnj:["thorgar_pretre_nain","geraud_veyre","brogar_eclaireur"],noteMJ:"La mémoire perdue crée des scènes (protéger un détenteur de savoir, retrouver des archives dispersées, empêcher la simplification d'un rite) mais n'a pas d'horloge propre. C'est un fil conducteur qui traverse tout le front : chaque étape de l'horloge principale peut s'accompagner d'une perte de savoir. Si les PJ retrouvent des fragments ou protègent un détenteur, le MJ peut retirer l'effet narratif sans toucher l'horloge principale.",conséquenceRemplissage:"Le rite est mutilé. Un geste indispensable n'est plus accompli, une formule est remplacée. Le verrou perd l'une de ses dernières protections culturelles.",annulation:"Possible : si les PJ retrouvent des fragments dispersés, protègent un détenteur menacé ou restaurent un rite avant qu'il ne soit simplifié."}]},{id:"front_sceau_qui_cede",nom:"Le Sceau qui cède",type:"Front souterrain",icone:t,couleur:"text-amber-300 border-amber-900 bg-amber-950/30",enjeu:"Les tombes des Sept Thanes, les galeries profondes et l'économie des Terrasses forment un seul système fragile. Si le sceau continue de céder, la Spirale absorbera les niveaux inférieurs tandis que la fermeture de la mine ruinera les clans et coupera Valombre de ceux qui connaissent encore ses fondations.",description:"Les profondeurs ne sont pas seulement le décor du plan de Thade. Elles possèdent leur propre dynamique : les prélèvements ont déjà endommagé le verrou, les anomalies modifient les galeries et chaque mesure de sécurité isole davantage les communautés naines. Même après la chute de Thade, le froid, les déformations et les effondrements demeureront.",questionDramatique:"Les PJ peuvent-ils maintenir les galeries ouvertes et le sceau stable assez longtemps pour que les clans nains et les institutions coopèrent ?",forcesActives:[{nom:"La Spirale",idsPnj:["creature_spirale_cooptee"],role:"Puissance ancienne qui occupe le vide laissé par le sceau affaibli, sans intention humaine mais avec des effets cohérents et croissants."},{nom:"Les autorités minières",idsPnj:["durnik_chef_mineur","garde_portail_mine","torm_garde_mine","kessak_mineur"],role:"Réaction de survie qui ferme les accès plus vite qu'elle ne résout les causes, jusqu'à rendre tout retour impossible."}],signesVisibles:["Le froid et les vibrations ne se limitent plus à une seule tombe.","Les trajets s'allongent, les cartes deviennent contradictoires et la lumière éclaire moins loin.","Les rotations minières sont interrompues et des mineurs quittent leur poste.","Les runes changent, les lanternes funéraires s'éteignent et les rites ordinaires ne suffisent plus.","Des fissures atteignent les bâtiments des Terrasses."],scenesJouables:{enquete:["Explorer les tombes pour évaluer l'état du sceau et identifier quels ancrages sont encore récupérables.","Suivre les anomalies dans les galeries : trajets qui s'allongent, cartes contradictoires, présences planaires."],roleplay:["Convaincre Durnik et les mineurs de ne pas abandonner les galeries en démontrant que le sceau peut encore être restauré.","Négocier avec Hessa Brunefer pour maintenir l'accès des Terrasses malgré la peur."],action:["Accompagner une équipe de mineurs dans les niveaux profonds pour restaurer un ancrage.","Repousser une présence de la Spirale qui a franchi une zone déformée."]},leviersPJ:["Restaurer les ancrages en replaçant les ossements et en accomplissant les rites complets.","Maintenir les galeries ouvertes en rassurant les mineurs et en restaurant la sécurité.","Empêcher l'évacuation des Terrasses en offrant une alternative crédible à la peur.","Neutraliser les sources d'alimentation du sceau : les prélèvements de Thade, les rites des Endeuillés, la mutilation du rite."],menaces:[{id:"menace_profanation_thanes",nom:"La Profanation du Sceau",categorie:"La Force Environnementale",nature:"Érosion progressive du verrou à mesure que les ossements des Thanes sont prélevés, déplacés ou privés des rites qui maintiennent leur fonction.",objectifFinal:"Les sept tombes sont suffisamment perturbées pour que le sceau cède de lui-même : la Spirale filtre dans les galeries sans qu'il soit possible de la contenir par les moyens ordinaires.",idsPnj:["thorgar_pretre_nain","durnik_chef_mineur"],avancement:{type:"B",declencheurPrincipal:"Érosion du sceau qui avance seule.",declencheurSecondaire:"Les prélèvements de Thade, les rites des Endeuillés et la mutilation du rite accélèrent l'horloge.",avanceHorsChamp:!0,avanceParEnquete:!1},conséquenceRemplissage:"Le sceau cède. La Spirale filtre dans les galeries sans qu'il soit possible de la contenir par les moyens ordinaires.",annulation:"Possible : si les PJ restaurent les ancrages, replacent les ossements ou accomplissent le rite complet, le MJ retire des segments.",horloge:{taille:6,etapes:[{titre:"Les ancrages perdent leur stabilité",indice:"Le froid et les vibrations ne se limitent plus à une seule tombe. Les runes changent, les lanternes funéraires s'éteignent et les rites ordinaires ne suffisent plus à rétablir le calme."},{titre:"Les galeries changent de mesure",indice:"Les trajets s'allongent, les cartes deviennent contradictoires et la lumière éclaire moins loin. Les équipes ne peuvent plus garantir qu'un chemin emprunté à l'aller existera encore au retour."},{titre:"Le Mausolée réagit",indice:"La dalle centrale se déplace, les anneaux du Puits de l'Abîme vibrent et des fissures apparaissent dans les murs. Chaque nouvelle perturbation se transmet désormais aux autres tombes."},{titre:"Les équipes refusent la descente",indice:"Les rotations sont interrompues, des mineurs quittent leur poste et les contremaîtres ne peuvent plus constituer d'équipes complètes. Les niveaux profonds restent sans surveillance ni entretien."},{titre:"Les lois physiques divergent",indice:"Le poids, la chute, le son et l'orientation varient d'une galerie à l'autre. Des présences planaires franchissent les zones déformées et les méthodes minières ordinaires deviennent dangereuses."},{titre:"Le réseau d'ancrage se rompt",indice:"Les sept tombes cessent d'agir comme un ensemble. Une lumière remonte du puits et les protections locales deviennent indépendantes, instables et impossibles à restaurer par un seul rite. Des sections complètes cessent d'appartenir à la mine."}]}},{id:"menace_abandon_mine",nom:"L'Abandon de la Mine",categorie:"L'Institution",nature:"Réaction de survie des guildes et des autorités qui ferme les accès plus vite qu'elle ne résout les causes, jusqu'à rendre tout retour impossible.",objectifFinal:"La Mine d'Argent est officiellement abandonnée, les Terrasses sont évacuées et Valombre perd à la fois sa principale richesse, ses ouvriers les plus compétents et l'accès aux fondations du sceau.",idsPnj:["durnik_chef_mineur","garde_portail_mine","torm_garde_mine","kessak_mineur"],noteMJ:"L'abandon de la mine crée des scènes (mineurs qui refusent de descendre, accès condamnés, évacuation des Terrasses) mais n'a pas d'horloge propre. Il suit l'horloge principale : aux étapes 4 et 6, la peur pousse à l'abandon. Si les PJ restaurent la sécurité ou rassurent les mineurs, le MJ peut annuler l'effet narratif.",conséquenceRemplissage:"La Mine d'Argent est officiellement abandonnée, les Terrasses évacuées. Valombre perd sa principale richesse et l'accès aux fondations du sceau.",annulation:"Possible avant l'étape 6 : si les PJ restaurent la sécurité dans les galeries, rassurent les mineurs ou offrent une alternative économique."}]}],v=[{id:"front_dephasage",nom:"Le Déphasage",type:"Couche de campagne",icone:r,couleur:"text-indigo-300 border-indigo-900 bg-indigo-950/30",enjeu:"Valombre n'attend pas d'être piégée : elle l'est déjà. Depuis l'explosion magique de Nyx, la Spirale n'a pas envahi la cité — elle a légèrement déplacé son ancrage. La cité, les mines, les routes proches et une partie des cols sont prises dans un voile de continuité. De l'intérieur, tout semble encore fonctionner. De l'extérieur, Valombre devient difficile à atteindre, puis presque impossible. Le déphasage ne coupe pas brutalement la ville : il remplace les ruptures par des explications plausibles. Si les PJ ne comprennent pas que la cité est déjà déconnectée du monde, toutes leurs décisions stratégiques reposent sur une carte qui ment.",description:"Le déphasage est le résultat indirect de la catastrophe de Nyx. L'explosion n'a pas seulement brisé l'Ordre et dispersé Sealine au-delà du seuil : elle a légèrement déplacé l'ancrage planaire de Valombre entière. La Spirale n'a pas envahi — elle a glissé. La cité est encore là, ses rues, ses mines, ses tours, ses entrepôts. Mais elle n'est plus tout à fait raccordée au reste du monde. Ce n'est pas une bulle visible. C'est pire : le monde continue de mentir à ceux qui vivent dedans. Un marchand reporte son départ à cause de la brume, d'un contrôle de Caldris, d'un pont abîmé, d'une taxe. Un messager revient en jurant qu'il a roulé toute la journée, alors qu'il n'a fait qu'une boucle autour des mêmes bornes. Une lettre arrive, mais elle reprend des formules anciennes, des nouvelles vagues, des signatures attendues. Les gens ne voient pas que plus personne n'entre ou ne sort. Ils voient que les routes sont difficiles en ce moment.",questionDramatique:"Les PJ peuvent-ils comprendre que Valombre est déjà déconnectée du monde avant que toutes leurs décisions ne reposent sur une carte qui ment ?",forcesActives:[{nom:"La Spirale",idsPnj:["creature_spirale_cooptee"],role:"Puissance planaire qui a glissé l'ancrage de Valombre sans l'envahir. Le déphasage progresse seul, hors-champ."}],signesVisibles:["Les délais de voyage s'allongent sans raison claire.","Des lettres venues de cités différentes utilisent exactement la même phrase.","Les entrepôts de minerai exporté ne se vident plus assez vite, mais les paiements continuent.","Une route extérieure ramène toujours au même pont, à la même borne, au même corbeau mort.","Les gardes n'ont pas enregistré d'entrée pour des convois « arrivés hier »."],scenesJouables:{enquete:["Investiguer les anomalies administratives : lettres en double, cargaisons fantômes, horloges désynchronisées.","Suivre une route extérieure et découvrir qu'elle ramène au même point."],roleplay:["Interroger Maelric sur ce que Caldris sait vraiment de l'inaccessibilité de Valombre.","Confronter Olane ou Hessa avec les anomalies et les forcer à admettre que leurs instruments sont pris dans la même dérive."],action:["Tenter de quitter Valombre à pied ou à cheval et découvrir la boucle.","Accompagner un éclaireur nain qui cartographie les limites du déphasage."]},leviersPJ:["Comprendre le déphasage en réunissant les preuves des anomalies (track de découverte).","Utiliser la révélation pour changer les hypothèses stratégiques de tous les acteurs (Conseil, Caldris, nains).","Réancrer Valombre en refermant le seuil ET en restaurant le sceau — un projet de campagne, pas une action unique."],menaces:[{id:"menace_dephasage_ancrage",nom:"Le Glissement de l'Ancrage",categorie:"La Force Environnementale",nature:"Déplacement planaire progressif qui désaccorde Valombre du monde matériel sans rupture visible, remplaçant les coupures par des explications plausibles et des boucles de route.",objectifFinal:"Valombre bascule entièrement hors du monde matériel. Les routes cessent de mener quelque part, les lettres ne portent plus que des formules répétées, et ceux qui tentent de partir reviennent sans s'en rendre compte. La cité devient un fragment dérivant entre le monde et la Spirale, sans que personne à l'intérieur ne comprenne ce qui s'est produit.",idsPnj:["creature_spirale_cooptee"],avancement:{type:"B",declencheurPrincipal:"Le déphasage progresse seul, hors-champ, depuis l'explosion de Nyx.",declencheurSecondaire:"L'ouverture du seuil par Thade ou la rupture du sceau accélèrent le déphasage.",avanceHorsChamp:!0,avanceParEnquete:!1},conséquenceRemplissage:"Valombre bascule entièrement hors du monde matériel. Les routes cessent de mener quelque part, les lettres ne portent plus que des formules répétées, ceux qui tentent de partir reviennent sans s'en rendre compte.",annulation:"Extrêmement difficile : il faut réancrer Valombre dans le monde matériel, ce qui suppose de refermer le seuil ET de restaurer le sceau. Une horloge d'inversion taille 6+ est nécessaire.",horloge:{taille:4,etapes:[{titre:"Les routes mentent doucement",indice:"Les délais de voyage s'allongent sans raison claire. Un messager jure avoir roulé toute la journée mais n'a fait qu'une boucle autour des mêmes bornes. Les marchands reportent leurs départs pour des raisons plausibles : brume, contrôle de Caldris, pont abîmé, taxe, convoi en retard. Personne ne voit que plus personne n'entre vraiment."},{titre:"Les lettres se répètent",indice:"Deux lettres venues de cités différentes utilisent exactement la même phrase. Une correspondance arrive avec des nouvelles vagues, des formules anciennes, des signatures attendues. Les registres de la Guilde montrent des cargaisons « arrivées » que personne n'a vu passer les portes."},{titre:"Les stocks s'accumulent",indice:"Les entrepôts de minerai exporté ne se vident plus assez vite, mais les paiements continuent — en lettres de crédit de plus en plus bizarres. Les mêmes maisons marchandes achètent pour un convoi qui ne part jamais vraiment. Les délais de paiement s'allongent et les garanties sont suspendues."},{titre:"Les routes ramènent au même point",indice:"Une route extérieure ramène toujours au même pont, à la même borne, au même corbeau mort. Ceux qui tentent de partir à pied ou à cheval reviennent sans s'en rendre compte. La cité n'est plus raccordée au réseau de routes du monde matériel."}]}},{id:"menace_dephasage_revelation",nom:"La Révélation par étapes",type:"decouverte",categorie:"La Force Environnementale",nature:"Processus de découverte qui confronte les PJ à l'impossibilité de quitter Valombre et à la vérité que la cité est déjà piégée — non pas par un siège visible, mais par un déphasage que personne n'a remarqué.",objectifFinal:"Les PJ comprennent que Valombre n'attend pas d'être piégée : elle l'est déjà. Cette révélation transforme toutes leurs hypothèses stratégiques — les routes ne sont pas difficiles, elles sont coupées ; le commerce ne ralentit pas, il n'existe plus ; Caldris ne menace pas, elle observe un phénomène qu'elle ne peut pas expliquer publiquement.",noteMJ:"Cette horloge est un track de découverte, pas une menace active. Elle n'avance jamais par elle-même. Le MJ coche un segment uniquement quand les PJ investiguent les anomalies du déphasage et obtiennent une information correspondant à l'étape. Les PNJ listés (Maelric, Olane, Hessa) sont des sources d'information, pas des moteurs.",idsPnj:["envoye_caldris","maera_olane","hessa_brunefer"],avancement:{type:"C",declencheurPrincipal:"Les PJ investiguent les anomalies du déphasage et obtiennent une information correspondant à l'étape.",declencheurSecondaire:"Un PNJ listé (Maelric, Olane, Hessa) apporte une information clé qui débloque une étape.",avanceHorsChamp:!1,avanceParEnquete:!0},conséquenceRemplissage:"Les PJ comprennent que Valombre est déjà piégée. Toutes leurs hypothèses stratégiques sont renversées : les routes sont coupées, le commerce n'existe plus, Caldris observe un phénomène qu'elle ne peut expliquer publiquement.",annulation:"Non applicable : on ne peut pas oublier une révélation. Une fois le track rempli, la connaissance est permanente.",horloge:{taille:6,etapes:[{titre:"Anomalie faible",indice:"Un marchand dit attendre un convoi « arrivé hier », mais personne ne l'a vu aux portes. Les gardes n'ont pas enregistré d'entrée. Le marchand insiste, vérifie ses registres, finit par admettre que les documents sont « un peu bizarres »."},{titre:"Anomalie administrative",indice:"Deux lettres venues de cités différentes utilisent exactement la même phrase, comme si elles avaient été rédigées par la même main — ou par aucune. Odran Bellec remarque que les horloges du Beffroi et d'une tour extérieure ne correspondent plus, mais attribue l'écart à un défaut de mécanisme."},{titre:"Anomalie naine",indice:"Les stocks de minerai exporté ne diminuent plus assez vite, mais les paiements continuent. Durnik ou Hessa remarque que les entrepôts sont pleins, que les lettres de crédit sont étranges, et que les maisons marchandes achètent pour des convois qui ne partent jamais. Les nains soupçonnent d'abord une manœuvre de la Guilde Marchande."},{titre:"Anomalie physique",indice:"Une route extérieure ramène toujours au même pont, à la même borne, au même corbeau mort. Un éclaireur nain ou un PJ qui tente de quitter Valombre revient sans s'en rendre compte, persuadé d'avoir voyagé pendant des heures. Les cartes deviennent contradictoires."},{titre:"Preuve de Caldris",indice:"Maelric montre une carte extérieure où Valombre n'est plus atteignable depuis des semaines. Les routes qui y mènent existent encore sur le papier, mais les convois et les messagers caldrisiens reviennent systématiquement sans avoir atteint la cité. Caldris sait que quelque chose de fondamental a changé."},{titre:"Vérité finale",indice:"La cité n'attend pas d'être piégée : elle l'est déjà. Le déphasage n'est pas une menace future mais un fait accompli depuis l'explosion de Nyx. Toutes les explications plausibles — brume, taxes, routes instables, contrôles — étaient le mensonge du monde, pas la vérité. Les PJ doivent désormais décider quoi faire d'une cité qui ne sait pas qu'elle a déjà quitté le monde."}]}}]}],u={s1_bureau_thade:[{frontId:"front_plan_thade",horlogeId:"menace_retour_sealine",declencheur:"Dès la première séance. Thade envoie les PJ enquêter pendant qu'il continue de prélever.",effet:"+1 segment (segment 1)",consequence:"Des fragments d'os convergent vers la Tour. Les PJ voient les outils d'Université sur les tombes."}],s1_premiere_descente:[{frontId:"front_sceau_qui_cede",horlogeId:"menace_profanation_thanes",declencheur:"Dès le début du S1. Le froid et les vibrations ne se limitent plus à une seule tombe.",effet:"+1 segment (segment 1)",consequence:"Le froid s'étend. Les runes changent. Les lanternes funéraires s'éteignent. Les rites ordinaires ne suffisent plus."},{frontId:"front_plan_thade",horlogeId:"menace_retour_sealine",declencheur:"Les PJ voient les outils d'Université sur les tombes — Thade prélève pendant qu'ils enquêtent.",effet:"+1 segment (segment 1)",consequence:"Des fragments d'os convergent vers la Tour."}],s1_mort_jaren:[],s1_temple_forgeron:[],s1_archives_scellees:[],s1_bureau_olane:[{frontId:"front_plan_thade",horlogeId:"menace_retour_sealine",declencheur:"Quand les PJ rencontrent Olane et qu'elle partage ses chiffres.",effet:"+1 segment (segment 2)",consequence:"Des salles sont scellées pour « travaux ». Des cours sont annulés. Les protections ordinaires de l'Université deviennent instables."},{frontId:"front_cite_sous_pression",horlogeId:"menace_derive_institutionnelle",declencheur:"Quand le Conseil enterre la crise sous des commissions. Typiquement à la fin du S1 ou au début du S2.",effet:"+1 segment (segment 1)",consequence:"Commissions, expertises et conflits de compétence. Les responsables déplacent des preuves. Les dangers avancent sans réponse coordonnée."}],s1_retour_cimetiere:[{frontId:"front_sceau_qui_cede",horlogeId:"menace_profanation_thanes",declencheur:"Quand la dalle centrale se déplace et que le Puits vibre.",effet:"+1 segment (segment 3)",consequence:"La dalle se déplace. Les anneaux du Puits vibrent. Des fissures apparaissent. Chaque perturbation se transmet aux autres tombes."}],s1_rencontre_resistance:[],s1_choix:[],s2_emeute_place:[{frontId:"front_factions_crise",horlogeId:"menace_radicalisation_cercles",declencheur:"Dès le début du S2. Chaque faction prend confiance en son cadre.",effet:"+1 segment (segment 1)",consequence:"Elian reçoit des patients « stabilisés ». Edran absorbe les familles isolées. Le Champion tient ses premiers discours."},{frontId:"front_factions_crise",horlogeId:"menace_radicalisation_cercles",declencheur:"Quand le Champion impose un choix public.",effet:"+1 segment (segment 3)",consequence:"Le Champion impose un choix : pour ou contre Nyx. Edran introduit des rites interdits. Elian commence à effacer ses traces."},{frontId:"front_cite_sous_pression",horlogeId:"menace_derive_institutionnelle",declencheur:"Quand les débats se déplacent vers la désignation d'un coupable.",effet:"+1 segment (segment 3)",consequence:"Pour rassurer la population, le Conseil désigne Nyx, les clans ou l'Université. Les informations qui compliquent ce récit sont écartées."}],s2_endeuilles_edran:[{frontId:"front_factions_crise",horlogeId:"menace_endeuilles_radicalisation",declencheur:"Quand les PJ rencontrent Ursula ou entendent parler des patients disparus.",effet:"+1 segment (segment 2)",consequence:"Ursula reçoit des patients qu'elle ne reconnaît pas. Des familles cherchent un proche. Le Champion obtient une victoire publique."}],s2_dephasage_visible:[{frontId:"front_sceau_qui_cede",horlogeId:"menace_abandon_mine",declencheur:"Quand le poids, la chute, le son et l'orientation varient d'une galerie à l'autre.",effet:"+1 segment (segment 5)",consequence:"Le poids, la chute, le son varient. Des présences planaires franchissent les zones déformées. Les méthodes minières deviennent dangereuses."},{frontId:"front_dephasage",horlogeId:"menace_dephasage_ancrage",declencheur:"Quand un PJ ou un éclaireur tente de quitter Valombre et revient sans s'en rendre compte.",effet:"+1 segment (segment 4)",consequence:"Une route ramène au même pont, à la même borne. Ceux qui partent reviennent. La cité n'est plus raccordée."}],s2_reserve_interdite:[],s2_laboratoire_elian:[],s2_assaut_tour:[{frontId:"front_plan_thade",horlogeId:"menace_loyalistes_tour",declencheur:"Quand Thade verrouille la Tour. Typiquement pendant l'Acte II ou III du S2.",effet:"+1 segment (segment 4)",consequence:"Les accès sont verrouillés. Les communications filtrées. Les défenseurs obéissent à des ordres qu'ils ne peuvent plus discuter."},{frontId:"front_factions_crise",horlogeId:"menace_syndicat_instrumentalisation",declencheur:"Quand une milice se forme autour du Champion ou qu'Edran pratique un rite près des tombes.",effet:"+1 segment (segment 5)",consequence:"Une milice se forme. Les Endeuillés pratiquent un rite près des tombes. Elian prépare sa fuite. Chaque faction est prête à frapper."}],s2_laboratoire_verre:[{frontId:"front_plan_thade",horlogeId:"menace_larme_vael",declencheur:"Quand le rituel commence à s'alimenter. Typiquement à la fin du S2 ou au début du S3.",effet:"+1 segment (segment 5)",consequence:"Les objets enchantés dérivent vers la Tour. Les sorts renvoient des échos contradictoires. Les mages ressentent une seconde pulsation."}],s3_vortex:[{frontId:"front_plan_thade",horlogeId:"menace_retour_sealine",declencheur:"Quand Thade accomplit le rituel. Automatique au début du S3 si les PJ n'ont pas arrêté Thade avant.",effet:"+1 segment (segment 6)",consequence:"Bourdonnement dans les Hauteurs. Ciel violet. Larme visible au cœur du vortex. Thade n'a plus besoin de dissimulation."},{frontId:"front_sceau_qui_cede",horlogeId:"menace_profanation_thanes",declencheur:"Si les sept tombes sont suffisamment perturbées.",effet:"+1 segment (segment 6)",consequence:"Les sept tombes cessent d'agir comme un ensemble. Une lumière remonte du puits. Des sections complètes cessent d'appartenir à la mine."}],s3_conversation_trois:[],s3_monde_apres:[]};function h(e){return u[e]||[]}export{p as C,v as c,u as e,m as f,h as o,d as s};
